window.BOOK_QCH=[["01 How neuropsychology reads the brain",18,22],["02 Testing the mind in clinic",23,27],["03 Listening to single nerve cells",28,31],["04 Reading the brain's electrical rhythms",32,36],["05 Pictures of the living brain",37,41],["06 Sampling the fluid between cells",42,45],["07 What spinal fluid can tell",46,50],["08 Changing the brain to test it",51,54],["09 Learning from brain damage",55,59],["10 Electrical stimulation of the brain",60,63],["11 Optogenetics and chemogenetics",64,67],["12 Transcranial magnetic stimulation",68,71],["13 Transcranial direct current stimulation",72,75],["14 Deep brain stimulation",76,79],["15 Vagus nerve stimulation",80,83],["16 Animal models of mental illness",84,88],["17 Stem cells and mini-brains",89,92],["18 Computational models of the mind",93,96],["19 Brain cells and cortical layers",97,101],["20 How neurones signal and learn",102,106],["21 Modelling neurons and circuits",107,110],["22 Glia: the brain's support cells",111,115],["23 How the brain gets energy",116,120],["24 Making and breaking transmitters",121,125],["25 The chemical synapse",126,129],["26 Release, clearance and recycling",130,133],["27 Receptor types and subtypes",134,137],["28 Second messengers inside the cell",138,141],["29 Peptides and other modulators",142,146],["30 How cells move big molecules",147,150],["31 How drugs hijack brain chemistry",151,155],["32 Brain, nerves and spinal cord",156,162],["33 The basal ganglia",163,167],["34 Temporal lobe, hippocampus and",168,172],["35 Frontal lobes and cingulate gyrus",173,176],["36 White matter pathways",177,180],["37 Ascending neurotransmitter systems",181,185],["38 Hunger, fullness and thirst",186,190],["39 Sleep, waking and the mind",191,195],["40 Sex, hormones and gender identity",196,200],["41 Violence and aggression",201,204],["42 Nociception and pain",205,208],["43 Movement and its disorders",209,212],["44 How brains learn",213,216],["45 Habits and compulsions",217,220],["46 Motivation and reward",221,224],["47 Emotion and its regulation",225,228],["48 Perception and its disorders",229,233],["49 Attention and ADHD",234,237],["50 Memory and its failures",238,241],["51 Frontal control and impulsivity",242,245],["52 Empathy and other minds",246,249],["53 Language and the aphasias",250,253],["54 Brain networks",254,257],["55 The hypothalamus runs the pituitary",258,262],["56 Stress: a fast and slow arm",263,267],["57 Hormones in psychiatric illness",268,272],["58 Inflammation talks to the brain",273,276],["59 When antibodies attack the brain",277,280],["60 Appetite, weight and mental illness",281,284],["61 The reproductive hormone axis",285,288],["62 How genes work and are found",289,293],["63 Common variants, tiny effects",294,297],["64 Rare variants and genetic syndromes",298,302],["65 Tools for reading genes",303,306],["66 Genes, traits and biotypes",307,311],["67 Epigenetics: marks on genes",312,316],["68 Gene editing and testing variants",317,321],["69 Mendelian randomisation",322,325],["70 Genetics in the clinic",326,329],["71 Building and ageing the brain",330,334],["72 Illness that starts early",335,338],["73 Attachment and early trauma",339,343],["74 Stress reshapes the brain",344,348],["75 Learning changes the brain",349,352],["76 Intellectual and learning disability",353,357],["77 Brain injury across the lifespan",358,361],["78 The autistic brain and its genes",362,366],["79 ADHD: late, leaky and under-tuned",367,371],["80 How drug use becomes addiction",372,376],["81 Alarms and brakes in anxiety",377,380],["82 PTSD: a fear that stays",381,384],["83 Loops, habits and tics",385,388],["84 The biology of depression",389,393],["85 The biology of bipolar disorder",394,397],["86 The biology of psychosis",398,402],["87 Thinking problems in schizophrenia",403,406],["88 Biology of self-harm and suicide",407,410],["89 Functional and somatic symptoms",411,414],["90 The biology of delirium",415,418],["91 How sleep goes wrong",419,423],["92 Genes behind learning disability",424,428],["93 The starving and bingeing brain",429,432],["94 Epilepsy and the mind",433,436],["95 Biology of personality disorder",437,440],["96 Why illnesses cluster together",441,444],["97 Hormone-sensitive mood disorders",445,448],["98 New drugs that rebuild synapses",449,453],["99 How genes change drug handling",454,458],["100 How ECT works",459,462],["101 Talking therapy changes the brain",463,466],["102 Stimulating the brain and vagus",467,470],["103 The body's automatic nerves",471,475],["104 How brain diseases build up",476,480],["105 Alzheimer's disease",481,485],["106 Vascular dementia",486,489],["107 Frontal, language and visual dementias",490,494],["108 Lewy bodies, Parkinson's and MSA",495,498],["109 Prion diseases",499,502],["110 HIV and brain infections",503,506],["111 Chronic traumatic encephalopathy",507,510],["112 Metabolic causes of dementia",511,514],["113 Motor neuron disease and ALS",515,555]];window.BOOK_QA=[[19,"What is the core idea behind neuropsychology as a way of understanding the healthy mind?","Studying what people with brain damage can and cannot do shows which mental functions can break apart separately. This reveals how normal thinking is organised.",0,1],[19,"What did Broca show in 1861 and which principle does it illustrate?","He linked loss of fluent speech to damage of the left inferior frontal gyrus. It is a classic example of localisation, where a skill depends on one area.",0,2],[19,"What did Lashley find when he removed cortex from rats trained in a maze?","Errors depended on how much cortex was removed, not where it was removed. He called this mass action.",0,3],[19,"What is meant by equipotentiality and who proposed it?","Lashley proposed that one cortical area can take over the work of another. Modern views favour specialised hubs linked in networks instead.",0,4],[20,"According to Fodor (1983), what are the key features of an input module?","It is fast, automatic and specialised for one kind of input such as vision. It is informationally encapsulated, so it cannot use general knowledge or beliefs.",0,5],[20,"Why does a visual line illusion persist even after you have measured the lines as equal?","The visual input module is informationally encapsulated. It cannot access what you know, so knowledge does not correct the illusion.",0,6],[20,"Why is a single dissociation weak evidence for a separate cognitive system?","The impaired task may simply be harder, so any damage to a general system would affect it first. Difficulty alone can explain the pattern.",0,7],[20,"What is a double dissociation and who set out its logic?","One patient fails task A but passes task B, while another shows the reverse. Teuber described this logic in 1955, and it is the strongest lesion evidence for separable systems.",0,8],[20,"How do surface and phonological dyslexia together show that reading uses separable routes?","Surface dyslexia loses irregular words such as pint but spares invented words, and phonological dyslexia shows the reverse. This crossed pattern is a double dissociation that difficulty cannot explain.",0,9],[20,"If a lesion impairs a task, does that show the skill is stored in the damaged region?","No. It shows the region is necessary for the task, and white matter damage may simply disconnect the areas that do the work.",0,10],[20,"What is diaschisis and who described it?","Von Monakow described it in 1914. It is reduced activity in a distant, undamaged area that has lost its input from the lesioned region.",0,11],[20,"What is crossed cerebellar diaschisis and how does it look on imaging?","After a cortical stroke, PET shows reduced activity in the opposite cerebellar hemisphere. MRI of that cerebellar half looks normal.",0,12],[20,"Why is reading of irregular words used to estimate premorbid ability, and when is it invalid?","Irregular word reading is relatively preserved in many illnesses. It is not valid in aphasia, dyslexia or semantic dementia, where a demographic estimate based on age, education and job is used.",0,13],[20,"What is cognitive reserve according to Stern, and what builds it?","It is the brain's ability to cope with damage, so people with the same pathology may show different symptoms. Education, complex work and mental activity build it.",0,14],[20,"What are the mean and standard deviation of scaled scores and of IQ or index scores?","Scaled scores have a mean of 10 and SD of 3. IQ and index scores have a mean of 100 and SD of 15.",0,15],[20,"A scaled score of 4 corresponds to roughly which percentile?","It is 2 SD below the mean of 10, which is about the 2nd percentile. A score 1 SD below the mean is the 16th percentile.",0,16],[20,"Why must normative data match the person being tested?","Norms should match age, education and culture. Using young, highly educated norms can make an older person with little schooling look falsely impaired.",0,17],[20,"Which tests best detect the subcortical pattern of cognitive impairment seen in HIV or small vessel disease?","Timed tests of processing speed, such as symbol-digit coding, detect the slowing called bradyphrenia. The MMSE is often normal in this pattern.",0,18],[21,"A woman aged 38 scores 16 of 50 on a two-choice memory test after mild head injury. What does this indicate?","Guessing would give about 25, so a score well below chance is a failed performance validity test. The battery cannot be interpreted, and whether she is exaggerating is a separate clinical judgement.",0,19],[24,"A woman aged 79 cannot spell WORLD backwards on the MMSE. Which cognitive domain does this item test?","Attention and concentration, including working memory. Serial sevens and months backwards test the same domain, and people with delirium fail them markedly.",1,1],[24,"What are the main limitations of the MMSE as a dementia screen?","It has 30 points but almost no executive items. A normal score never rules out dementia, especially frontotemporal dementia.",1,2],[24,"What does the MoCA add to the MMSE and what is a normal score?","It adds executive tasks and is more sensitive to mild impairment. A score of 26 or more out of 30 is normal, adding 1 point for 12 years of education or less.",1,3],[24,"What are the ACE-III cut-offs and how is a score of 84 interpreted?","The cut-offs are 88 for sensitivity and 82 for specificity out of 100. A score of 84 lies between them, so impairment is possible and needs further assessment.",1,4],[24,"What are the cut-offs for the Mini-ACE?","It is scored out of 30. A score of 25 or below is highly sensitive and 21 or below is highly specific for dementia.",1,5],[25,"What are the four index scores of the WAIS-IV?","Verbal comprehension, perceptual reasoning, working memory and processing speed. The 2024 WAIS-5 gives five indices.",1,6],[25,"Which WAIS subtests hold up with age and which decline?","Vocabulary is a hold test that is preserved. Block design is a timed, non-hold test that falls with age.",1,7],[25,"What age ranges do the WAIS, WISC and Stanford-Binet cover?","The WAIS covers about 16 to 90 and the WISC 6 to 16. The Stanford-Binet runs from age 2 to over 85 on one scale.",1,8],[25,"Which intelligence test is preferred for a person with little English, and why?","Raven's progressive matrices, a non-verbal pattern test where the person points to the missing piece. It is the classic culture-fair test.",1,9],[25,"How do the NART and TOPF estimate premorbid intelligence?","The person reads irregularly spelled words, 50 in the NART and 70 in the TOPF. Such reading is preserved into early dementia, and the TOPF is normed with current Wechsler scales.",1,10],[25,"On the Wechsler Memory Scale, what does a memory index well below IQ suggest?","A gap of about 20 points or more suggests a specific amnesia, as in Korsakoff syndrome.",1,11],[25,"How do recall and recognition help distinguish storage failure from retrieval failure?","In hippocampal storage failure, recognition is no better than recall. In retrieval failure, recognition is near normal.",1,12],[25,"Which verbal fluency task falls first in Alzheimer's disease and which in left frontal damage?","Category fluency falls first in Alzheimer's disease. Letter fluency falls with left frontal damage.",1,13],[25,"What does persistent sorting by an old rule on the Wisconsin Card Sorting Test indicate?","Impaired set-shifting with perseveration, an executive deficit. Trail making B and the Tower of London test set-shifting and planning respectively.",1,14],[25,"Which part of the Halstead-Reitan battery detects right temporal damage, and what impairment index suggests damage?","The rhythm test detects right temporal damage. An impairment index of 0.5 or more suggests brain damage.",1,15],[25,"What is needed to diagnose intellectual disability besides low IQ?","Deficits in adaptive behaviour beginning in childhood. IQ alone never makes the diagnosis.",1,16],[25,"Which tools are used to assess autism in children and to screen adults in the UK?","The ADOS-2 is a coded observation session and the ADI-R a parent interview. Adults are screened with the AQ-10, with 6 or more prompting referral under NICE CG142.",1,17],[26,"A man aged 70 scores 12 on the 6CIT in his GP surgery. How should this be interpreted?","On the 6CIT higher scores are worse, unlike the MMSE, MoCA and ACE-III. A score of 10 or more out of 28 indicates significant cognitive impairment.",1,18],[26,"What Glasgow Coma Scale scores and post-traumatic amnesia duration define severe head injury?","A GCS of 8 or less is severe, 9 to 12 moderate and 13 to 15 mild. Post-traumatic amnesia over 7 days means very severe injury.",1,19],[27,"A tearful woman aged 74 gives many 'don't know' answers after her husband's death. What is the next step?","Screen for depression, for example with the Beck Depression Inventory, then treat and retest cognition. Dementia more often gives near-miss answers and confabulation.",1,20],[29,"Which technique records the current flowing through a single ion channel, such as a GABA-A receptor?","Patch clamp recording, developed by Neher and Sakmann. It measures currents of picoamps through one or a few channels.",2,1],[29,"What makes the patch clamp able to record such tiny currents?","A glass pipette is sealed onto the membrane with a gigaohm seal. Almost no current leaks round the rim, so only current through the trapped channels is recorded.",2,2],[29,"When did Neher and Sakmann develop the patch clamp and when did they win the Nobel Prize?","They first recorded single channels in 1976 and introduced the gigaohm seal by 1981. They won the Nobel Prize in 1991.",2,3],[29,"What does extracellular single-unit recording detect, and what can it not see?","It detects each action potential of one neuron as a brief blip. It cannot see the resting potential or subthreshold postsynaptic potentials.",2,4],[29,"Which recording method is needed to see subthreshold EPSPs that build up before a spike?","Intracellular sharp electrode or whole-cell recording. These show the membrane voltage, including resting potential, postsynaptic potentials and the spike.",2,5],[30,"What is multi-unit activity in extracellular recording, and why is it a problem?","It is the mixed signal from several nearby neurons picked up by one wire. It makes it hard to attribute spikes to a single cell, which tetrodes help solve.",2,6],[30,"What is a tetrode and why does it improve single-cell isolation?","A bundle of four closely spaced wires. Each cell's spike has a different size pattern across the four tips, so spikes can be assigned to individual cells more reliably.",2,7],[30,"What is spike sorting, and which electrode design makes it more reliable?","Grouping recorded spikes by their size and shape to separate the activity of individual neurons. Tetrodes make it more reliable, as Gray showed in 1995.",2,8],[30,"At what frequency is a wire signal split into spikes and local field potential?","At about 300 Hz. Spikes lie above this and the local field potential lies below it.",2,9],[30,"What mainly generates the local field potential?","Summed synaptic and other membrane currents from thousands of neurons within a few hundred microns. It is not the spikes of the nearest cell.",2,10],[30,"Place the recording methods in order from smallest to largest scale.","Patch clamp records one channel, single-unit recording one cell, the local field potential thousands of cells, and EEG millions of cells.",2,11],[30,"What did Hubel and Wiesel find in 1959?","Neurons in the cat visual cortex that fire to lines at a particular orientation.",2,12],[30,"What are place cells, where are they found and who discovered them?","Hippocampal neurons that fire only when the animal is in one location. John O'Keefe found them in freely moving rats in 1971.",2,13],[30,"What are grid cells and where are they located?","Neurons in the medial entorhinal cortex that fire at many locations forming a regular hexagonal lattice. The Mosers described them in 2005 and shared the 2014 Nobel Prize with O'Keefe.",2,14],[30,"Apart from place and grid cells, which other spatial cells exist, and what are mirror neurons?","Head direction cells code which way the head points and border cells code walls. Mirror neurons in monkey premotor cortex fire when performing and when watching the same action.",2,15],[30,"In which patients can single neurons ethically be recorded in humans?","Only where electrodes are already placed for clinical care, mainly people with drug-resistant epilepsy having depth electrodes before surgery.",2,16],[30,"What are concept cells, as shown by Quian Quiroga in 2005?","Medial temporal neurons that fire to one person across many photos and even the written name. They show sparse and invariant coding.",2,17],[31,"How does cell-attached patch clamp differ from whole-cell mode?","Cell-attached mode records channels in the patch under the pipette on an intact cell. Whole-cell mode sums the currents of all the channels in the cell.",2,18],[33,"What does the scalp EEG actually record?","Summed, synchronised postsynaptic potentials in the apical dendrites of cortical pyramidal neurons. Action potentials are too brief and unsynchronised to sum.",3,1],[33,"Why do cortical pyramidal cells produce a measurable scalp signal?","They are aligned in parallel at right angles to the surface, and their slow postsynaptic potentials overlap in time. Berger recorded the first human EEG in 1929.",3,2],[34,"What does phase reversal around one electrode in a bipolar montage indicate?","The field of the discharge is maximal at that shared electrode, which localises the peak.",3,3],[34,"How does MEG differ from EEG in what it detects?","MEG measures the magnetic fields of the same currents using helium-cooled SQUID sensors. It best detects currents tangential to the skull, from the sulci.",3,4],[34,"What are the frequency ranges of the five EEG bands?","Delta below 4 Hz, theta 4 to 7 Hz, alpha 8 to 13 Hz, beta 13 to 30 Hz and gamma above 30 Hz.",3,5],[34,"Describe the normal alpha rhythm and the mu rhythm.","Alpha is posterior, seen with eyes closed and blocked by eye opening. The mu rhythm is central at 7 to 11 Hz and is blocked by movement or watching movement.",3,6],[34,"How does the EEG change with age in childhood, and what is abnormal in adults?","Infants show slow waves and adult alpha frequency is reached by about 8 to 10 years. Delta in an awake adult is abnormal.",3,7],[34,"How do you distinguish photic driving, a photoparoxysmal response and a photomyoclonic response?","Photic driving at the flash rate is normal. A photoparoxysmal response with spikes suggests epilepsy, while flash-locked forehead muscle twitching is photomyoclonic, as in alcohol withdrawal.",3,8],[34,"Does a normal routine EEG exclude epilepsy?","No. One routine EEG is normal in 30 to 50% of people with epilepsy. Sleep deprivation and longer recordings increase the yield.",3,9],[34,"What EEG findings are seen in juvenile myoclonic epilepsy and temporal lobe epilepsy?","Juvenile myoclonic epilepsy shows generalised 4 to 6 Hz polyspike-and-wave and photosensitivity. Temporal lobe epilepsy shows anterior temporal spikes.",3,10],[34,"What does the EEG show during a functional (dissociative) seizure?","The EEG remains normal during the attack itself.",3,11],[34,"What EEG changes occur in delirium, and what is the important exception?","Delirium causes diffuse theta and delta slowing that tracks its severity. Delirium tremens is the exception, giving fast beta activity.",3,12],[34,"Which periodic EEG patterns are seen in sporadic CJD, herpes simplex encephalitis and SSPE?","Sporadic CJD shows periodic sharp waves at 1 to 2 Hz. Herpes encephalitis shows temporal lateralised periodic discharges every 1 to 3 s, and SSPE complexes occur every 4 to 15 s.",3,13],[34,"What EEG findings are linked with anti-NMDA receptor encephalitis, Huntington's disease and schizophrenia?","Anti-NMDA receptor encephalitis may show extreme delta brush in about 30%. Huntington's gives a flat low-voltage record, and schizophrenia has no typical EEG, so EEG is used to look for organic causes.",3,14],[34,"Which event-related potential changes are found in schizophrenia and OCD?","In schizophrenia the P300 is smaller and later, mismatch negativity is reduced and P50 gating fails. The error-related negativity is larger in OCD.",3,15],[34,"How is sleep staged, and what marks stage N2?","Using EEG, eye leads and chin EMG scored in 30-second epochs. N2 is marked by sleep spindles of 12 to 14 Hz and K complexes.",3,16],[35,"Which conditions cause triphasic waves on the EEG?","Hepatic failure, renal failure, and lithium or valproate toxicity.",3,17],[35,"What sleep findings characterise depression and narcolepsy?","Depression shortens REM latency, often under about 60 minutes. Narcolepsy shows mean sleep latency of 8 minutes or less with 2 or more sleep-onset REM periods on the MSLT.",3,18],[35,"How do benzodiazepines, clozapine, opioids and cannabis change the EEG?","Benzodiazepines increase beta and suppress REM. Clozapine causes slowing and spikes, opioids increase slow activity and cannabis increases alpha.",3,19],[36,"A girl aged 8 has many brief daily staring spells triggered by overbreathing. What EEG pattern is expected?","Generalised 3 Hz spike-and-wave, typical of absence epilepsy. Hyperventilation lowers carbon dioxide and provokes the discharges.",3,20],[38,"A woman aged 79 on warfarin falls at home and becomes drowsy. Which scan comes first and why?","CT head, because it is fast and shows acute haemorrhage such as a subdural haematoma as bright white. It also shows skull fractures.",4,1],[38,"What are the main advantages and disadvantages of MRI compared with CT?","MRI uses no radiation and shows soft tissue in far better detail. It is slower and needs a still, cooperative patient without unsafe metal implants.",4,2],[38,"How do CSF and white matter appear on T1, T2 and FLAIR MRI?","On T1 CSF is dark and white matter bright, so it suits anatomy. On T2 and FLAIR water is bright so lesions stand out, and FLAIR also darkens the CSF.",4,3],[39,"What does diffusion-weighted imaging show, and in which conditions is it useful?","It shows water whose movement is restricted. It lights up acute stroke and the cortical ribboning and basal ganglia signal of sporadic CJD.",4,4],[39,"What is the swallow tail sign and what does its loss suggest?","On 3 T susceptibility-weighted MRI the healthy nigra shows a bright nigrosome-1 giving a swallow tail look. Its loss supports Parkinson's disease, and it is an MRI sign, not a DaTscan finding.",4,5],[39,"A man aged 22 presents with first-episode psychosis. When is brain imaging indicated?","It is not routine. Scan if there are red flags such as focal signs, papilloedema, new headache, seizures, head injury or rapid cognitive decline.",4,6],[39,"What does NICE NG97 recommend about structural imaging in suspected dementia?","MRI is preferred over CT unless contraindicated. It excludes tumour or subdural and supports subtype, such as medial temporal atrophy in Alzheimer's and frontal atrophy in FTD.",4,7],[39,"What MRI changes occur in Wernicke's encephalopathy, and should treatment wait for a scan?","FLAIR may show high signal in the medial thalami, mammillary bodies and periaqueductal grey. A normal scan does not exclude it, so thiamine must never be delayed.",4,8],[39,"What did Johnstone show in 1976 and what has voxel-based morphometry found in schizophrenia?","Johnstone used CT to show enlarged lateral ventricles in schizophrenia. Voxel-based morphometry shows reduced grey matter already at the first episode.",4,9],[39,"What did Gilbertson's twin study show about the hippocampus in PTSD?","Combat veterans with PTSD had small hippocampi, and so did their twins who were not exposed. A small hippocampus is partly a pre-existing risk factor.",4,10],[39,"What does diffusion tensor imaging measure, and what does fractional anisotropy mean?","DTI tracks water diffusion in white matter, which moves more easily along axons. Fractional anisotropy ranges from 0 to 1, and rising radial diffusivity indicates myelin loss.",4,11],[39,"Where is fractional anisotropy reduced in schizophrenia and after head injury?","In the uncinate fasciculus in schizophrenia. In the corpus callosum after diffuse axonal injury.",4,12],[39,"What is the physiological basis of the BOLD signal in fMRI?","Active neurons increase blood flow more than oxygen use, so paramagnetic deoxyhaemoglobin falls and the signal rises. Ogawa described it in 1990.",4,13],[39,"Why does fMRI have poor temporal resolution, and which methods give better timing?","The BOLD response lags neural activity by 4 to 6 seconds, so fMRI shows where but not exactly when. EEG and MEG give millisecond timing.",4,14],[39,"What is resting-state functional connectivity on fMRI, and who described it?","Slow BOLD fluctuations below 0.1 Hz that rise and fall together in linked brain areas at rest, described by Biswal in 1995.",4,15],[39,"Why can FDG be transported between centres but raclopride PET needs an on-site cyclotron?","Fluorine-18 has a half-life of about 110 minutes. Carbon-11, used in raclopride, has a half-life of about 20 minutes and decays before it could travel.",4,16],[39,"What FDG-PET patterns are seen in Alzheimer's disease, FTD and Lewy body dementia?","Alzheimer's shows reduced temporoparietal and posterior cingulate metabolism. FTD shows frontal and Lewy body dementia occipital hypometabolism.",4,17],[39,"What do 18F-DOPA PET, amyloid PET and DaTscan show in psychiatric and dementia practice?","18F-DOPA PET shows raised striatal dopamine synthesis in schizophrenia. A negative amyloid PET makes Alzheimer's unlikely, and DaTscan uptake is low in Lewy body dementia and Parkinson's.",4,18],[39,"What do NAA, myo-inositol, choline and lactate represent on MR spectroscopy?","NAA marks neurons, myo-inositol glia and choline cell membranes. A lactate doublet at about 1.3 ppm indicates anaerobic metabolism, as in MELAS.",4,19],[39,"What MR spectroscopy changes are seen in Alzheimer's disease and liver failure?","In Alzheimer's NAA falls and myo-inositol rises. In liver failure glutamine rises.",4,20],[43,"What is microdialysis and what does it measure?","A probe with a semipermeable tip is perfused with artificial CSF in a living animal. Small molecules diffuse in, so it measures extracellular neurotransmitter concentration.",5,1],[43,"How are microdialysis samples collected and analysed?","The outflowing dialysate is collected every 10 to 20 minutes and usually analysed by HPLC, which separates and quantifies each chemical.",5,2],[43,"Who developed microdialysis and in what decade?","Ungerstedt developed it in the 1970s.",5,3],[43,"What are the main limitations of microdialysis?","It is slow, taking minutes per sample, so it misses single release events. It measures levels rather than firing, and the probe damages nearby tissue.",5,4],[43,"How does voltammetry differ from microdialysis in measuring dopamine?","Voltammetry is electrochemical and works in under a second without perfusion. Microdialysis collects fluid and averages levels over minutes.",5,5],[44,"What is relative recovery in microdialysis and what affects it?","It is the fraction of the true extracellular level that the probe collects. It increases with slower flow or a longer membrane, so changing flow rate changes the measured level.",5,6],[44,"How does the no-net-flux method estimate the true extracellular concentration?","Several known concentrations are perfused through the probe. The level at which there is no net gain or loss equals the true extracellular concentration.",5,7],[44,"What is push-pull perfusion, and how does it differ from microdialysis?","An older method that pumps fluid into and out of brain tissue directly. Unlike microdialysis it uses no membrane.",5,8],[44,"What did Di Chiara and Imperato show in 1988?","Amphetamine, cocaine, morphine, nicotine and ethanol all increased extracellular dopamine in the rat nucleus accumbens. This shared effect underpins reward models of addiction.",5,9],[44,"Do only stimulant drugs raise nucleus accumbens dopamine?","No. All the major drugs of abuse, including opioids, nicotine and alcohol, raise extracellular dopamine there.",5,10],[44,"Which technique captures phasic dopamine release within 100 milliseconds of a cue?","Fast-scan cyclic voltammetry using a carbon-fibre electrode and rapidly changing voltage. Microdialysis is far too slow for this.",5,11],[44,"How is cerebral microdialysis used in neurointensive care?","A probe in the brain is sampled hourly after head injury or subarachnoid haemorrhage. Glucose, glutamate and the lactate to pyruvate ratio are tracked.",5,12],[44,"Why does the lactate to pyruvate ratio rise in brain ischaemia?","Without enough oxygen, pyruvate is converted to lactate. So the ratio climbs, signalling ischaemia or metabolic crisis.",5,13],[44,"What lactate to pyruvate ratio warns of ischaemia, and why is it clinically valuable?","A ratio above about 25 warns of ischaemia or metabolic crisis. It often changes before any abnormality is seen on imaging.",5,14],[45,"A woman aged 50 on neurointensive care after subarachnoid haemorrhage has a brain lactate to pyruvate ratio of 40 on day 5. Interpretation?","This is cerebral microdialysis, and a ratio above 25 suggests ischaemia. On day 5 this fits delayed vasospasm.",5,15],[45,"Why is lumbar puncture not a substitute for cerebral microdialysis in monitoring ischaemia?","Lumbar CSF cannot be sampled hourly and does not reflect the chemistry of one patch of cortex.",5,16],[47,"At which level is a lumbar puncture performed in adults and why?","At L3/4 or L4/5. The adult spinal cord ends at about L1/2, so below this the sac contains only nerve roots.",6,1],[47,"When should CT be done before a lumbar puncture?","With focal signs, papilloedema, falling consciousness, new seizures or immunosuppression, because lowering pressure below a mass may cause herniation. Antibiotics or antivirals must not be delayed for the scan.",6,2],[48,"What platelet count and anticoagulant precautions apply before a planned lumbar puncture?","Platelets should be at least about 40 x 10^9/L. Warfarin and DOACs are withheld for a set interval, but aspirin alone can continue.",6,3],[48,"A man aged 30 has a headache worse sitting up and better lying flat after LP. What is it and how is it prevented?","A post-dural puncture headache from CSF leak. A pencil-point needle reduces the risk, bed rest does not prevent it, and a blood patch treats persistent cases.",6,4],[48,"How is lumbar puncture used in suspected normal pressure hydrocephalus?","In the tap test about 30 to 50 mL of CSF is removed and gait reassessed over the next hours. Clear improvement predicts shunt benefit, and opening pressure is usually normal.",6,5],[48,"What are the normal adult CSF findings taken lying on the side?","Opening pressure 10 to 20 cmH2O, under 5 lymphocytes and no neutrophils. Protein 0.15 to 0.45 g/L and glucose about 60% of blood glucose.",6,6],[48,"What CSF picture is typical of bacterial meningitis?","Neutrophils, protein over 1 g/L and a CSF to blood glucose ratio below about 0.4, with onset over hours.",6,7],[48,"How does tuberculous meningitis differ from bacterial meningitis clinically and in the CSF?","TB meningitis develops over weeks with cranial nerve palsies. CSF shows lymphocytes, very high protein and very low glucose.",6,8],[48,"What CSF findings occur in herpes simplex encephalitis, and what if the PCR is negative early?","Lymphocytes, often with red cells. HSV PCR may be negative in the first 72 hours, so continue aciclovir and repeat the LP.",6,9],[48,"What do oligoclonal bands in CSF but not serum mean, and in which disease are they common?","They indicate antibody production within the central nervous system. They are found in over 90% of people with multiple sclerosis.",6,10],[48,"Does a negative serum NMDA receptor antibody exclude anti-NMDA receptor encephalitis?","No. CSF testing is more sensitive than serum for NMDA receptor antibodies. For LGI1 antibodies, serum is usually more sensitive.",6,11],[48,"What CSF biomarker profile is typical of Alzheimer's disease?","Low Abeta42 because it is trapped in plaques, with high total tau and phospho-tau. Phospho-tau is the more specific marker.",6,12],[48,"What is neurofilament light and how can it help in psychiatric practice?","It leaks from damaged axons. It is raised in neurodegenerative disease such as FTD but usually normal in primary psychiatric illness.",6,13],[48,"What is the CSF alpha-synuclein seed assay used for and how accurate is it?","It supports a diagnosis of Parkinson's disease, with about 88% sensitivity and 93% specificity.",6,14],[48,"What did Asberg and Linnoila find regarding CSF 5-HIAA?","Asberg (1976) found low CSF 5-HIAA after violent suicide attempts, which also predicted later suicide. Linnoila linked it to impulsive rather than planned violence.",6,15],[48,"Which CSF changes are reported in depression and schizophrenia?","CSF corticotropin-releasing hormone is raised in depression, as Nemeroff found. Kynurenic acid, an NMDA antagonist, is raised in schizophrenia.",6,16],[48,"Which CSF test is genuinely diagnostic in a psychiatric or sleep context?","CSF hypocretin-1 (orexin-A) of 110 pg/mL or less confirms narcolepsy type 1.",6,17],[49,"A woman aged 67 has rapidly progressive dementia with startle myoclonus. What does a positive CSF RT-QuIC detect?","Seeding activity of misfolded prion protein (PrPSc), supporting sporadic CJD. It is about 90% sensitive and 98 to 100% specific, unlike the non-specific 14-3-3 protein.",6,18],[49,"Can low CSF 5-HIAA predict suicide in an individual patient?","No. It is a group-level research finding and is too imprecise for individual prediction.",6,19],[50,"A feverish, confused woman aged 45 has a hemiparesis and falling GCS. What should happen before LP?","Take blood cultures, start empirical antimicrobial treatment and obtain a CT scan before any lumbar puncture.",6,20],[52,"An fMRI study shows the anterior insula activates during disgust. Does this prove the insula is necessary for disgust?","No. Activation shows only involvement. A lesion or inactivation study is needed to show necessity.",7,1],[52,"Why might an activated brain region not be needed for a task?","It may be a bystander, a downstream echo of work done elsewhere, or one of several routes that could each do the job.",7,2],[52,"Is PET better than fMRI for showing that a region causes a mental state?","No. PET also records activity, so it is just as correlational as fMRI.",7,3],[52,"What is meant by perturbing brain function?","Deliberately changing brain activity by lesion, inactivation or stimulation and observing the effect on behaviour.",7,4],[52,"What do loss-of-function and gain-of-function studies each show?","Silencing an area that stops a task shows it is necessary. Driving an area that produces a behaviour shows it is sufficient.",7,5],[53,"Why is a single dissociation weak evidence of a specific function?","The impaired task may simply be harder than the spared one, so task difficulty could explain the result.",7,6],[53,"Give a classic clinical example of a double dissociation.","Broca's aphasia gives effortful speech with preserved comprehension, while Wernicke's aphasia gives fluent speech with poor comprehension.",7,7],[53,"Who named the double dissociation logic and when?","Hans-Lukas Teuber in 1955.",7,8],[53,"What is the main problem with permanent lesions in studying function?","Over weeks the brain rewires and other areas take over, which blurs the true role of the lost area.",7,9],[53,"Which methods produce reversible inactivation of a brain area in animals?","Local infusion of muscimol, a GABA-A agonist, or lidocaine, a sodium channel blocker, or focal cooling. These silence the area for minutes to hours.",7,10],[53,"What is the main advantage of reversible inactivation over a permanent lesion?","Each animal acts as its own control, and results are not confounded by rewiring and recovery.",7,11],[53,"Why can a drug given by mouth or systemic injection not test the role of one brain area?","Systemic drugs act throughout the brain, so they are not regional.",7,12],[53,"Which lesion methods are permanent rather than reversible?","Ibotenic acid, 6-OHDA and aspiration cause permanent lesions. Muscimol, lidocaine and cooling wear off.",7,13],[53,"Why is memory tested during the Wada test?","To check that the opposite hemisphere can support memory, predicting the risk of amnesia after temporal lobe surgery.",7,14],[53,"How does TMS create a virtual lesion, as shown by Amassian in 1989?","A single pulse over occipital cortex about 100 ms after a letter flash stopped people seeing it. Pulses at other times had no effect.",7,15],[53,"What is TMS chronometry and how long does a virtual lesion last?","It uses pulse timing to show when an area is needed. The effect lasts only tens of milliseconds and causes no damage or rewiring.",7,16],[53,"How does the Wada test differ from intraoperative stimulation mapping?","The Wada test injects a drug into one carotid artery to silence a hemisphere. Stimulation mapping applies current directly to exposed cortex.",7,17],[54,"A woman aged 30 has amobarbital injected into her left internal carotid artery before temporal lobe surgery and cannot speak. What is this?","The Wada test, which silences one hemisphere for a few minutes. Speech arrest shows that side holds language.",7,18],[56,"What operation did HM have, when and why?","In 1953, aged 27, Scoville removed both medial temporal lobes, including the hippocampi and amygdalae, to treat severe epilepsy.",8,1],[56,"What memory deficit did HM develop?","Dense anterograde amnesia for declarative memory, so he could not learn new facts or events such as the names of staff.",8,2],[57,"Which abilities did HM retain after surgery?","Intelligence, working memory and digit span, older memories including childhood, and procedural skill learning such as mirror drawing.",8,3],[57,"What did Brenda Milner's mirror drawing studies of HM show?","He improved day by day but denied having done the task. Declarative memory needs the medial temporal lobe, whereas procedural learning does not.",8,4],[57,"Which brain systems support procedural memory, and where is long-term memory stored?","Skills depend on the basal ganglia and cerebellum. Older long-term memories are stored in the cortex, not the medial temporal lobe.",8,5],[57,"What happened to Phineas Gage in 1848 and how did he change?","An iron rod passed through his skull. Memory and speech were spared, but he became rude, impulsive and unable to plan.",8,6],[57,"Which brain regions were damaged in Phineas Gage?","Hanna Damasio placed the damage in the orbitofrontal and ventromedial prefrontal cortex, probably mainly left-sided. These regions link emotion to decisions and social conduct.",8,7],[57,"How does dorsolateral prefrontal damage differ from orbitofrontal damage?","Dorsolateral damage mainly impairs working memory and planning tests. Orbitofrontal and ventromedial damage alters personality, social conduct and decision-making.",8,8],[57,"What is Klüver-Bucy syndrome and which structure explains most of it?","After bilateral temporal lobe removal in 1939, monkeys became tame and fearless, mouthed objects and were hypersexual. Amygdala loss explains most of this.",8,9],[57,"What is the main drawback of aspiration, knife, heat and electrolytic lesions?","They destroy everything at the site, including fibres of passage. A deficit might therefore come from a cut tract rather than the lost nucleus.",8,10],[57,"How do excitotoxic lesions spare fibres of passage?","Ibotenic acid, kainic acid or NMDA overstimulate glutamate receptors on cell bodies until they die. Passing axons lack such receptors along their length and survive.",8,11],[57,"How does 6-hydroxydopamine kill neurons and what model does it produce?","It enters dopamine and noradrenaline cells through their transporters and kills them by oxidative stress. Unilateral injection into the medial forebrain bundle gives a rat one-sided parkinsonism with circling.",8,12],[57,"How can noradrenaline neurons be protected during a 6-OHDA lesion, and which toxin kills serotonin cells?","Desipramine given first blocks uptake into noradrenaline cells. 5,7-dihydroxytryptamine selectively kills serotonin neurons.",8,13],[57,"How was MPTP discovered as a cause of parkinsonism?","In the early 1980s young drug users in California became severely parkinsonian after using a street opioid contaminated with MPTP.",8,14],[57,"Describe how MPTP destroys nigral dopamine neurons.","It crosses the blood-brain barrier and glial MAO-B converts it to MPP+. The dopamine transporter takes MPP+ into nigral cells, where it blocks mitochondrial complex I.",8,15],[57,"How does reserpine-induced parkinsonism differ from MPTP parkinsonism?","Reserpine only depletes vesicular monoamines, so its parkinsonism reverses without cell death. MPTP kills nigral neurons.",8,16],[57,"After a small thalamic stroke, FDG-PET shows low frontal metabolism. What explains this?","Diaschisis, a distant and reversible fall in function in intact tissue that has lost input. It recovers over weeks, so early deficits can overstate the role of the damaged site.",8,17],[58,"To destroy rat entorhinal neurons but spare passing axons, which lesion method should be used?","An excitotoxic lesion with ibotenic acid. Electrolytic lesions destroy passing axons too.",8,18],[61,"Why can the cortex be stimulated in an awake patient?","The brain has no pain receptors, so only local anaesthetic for the scalp is needed.",9,1],[61,"What did Penfield's cortical stimulation in the 1930s produce?","The motor homunculus from the precentral gyrus and the sensory homunculus from the postcentral gyrus, with large hand and face areas.",9,2],[61,"What experiences did Penfield evoke by stimulating the temporal lobe?","Vivid, dream-like experiential memories or scenes.",9,3],[61,"How does Brodmann's map differ from Penfield's map?","Brodmann's map is based on cell structure under the microscope. Penfield's is functional, based on stimulation.",9,4],[61,"How did Broca's method of localising speech differ from Penfield's?","Broca used a lesion found after death, while Penfield used electrical stimulation in living patients.",9,5],[61,"How is language cortex mapped before epilepsy surgery?","Brief trains of current at about 50 Hz pass between subdural grid or stereo-EEG contacts while the patient names pictures. Sites where naming stops during current are language cortex to be spared.",9,6],[62,"Why is electrical stimulation mapping described as a reversible lesion?","It disrupts function only while current flows, with millimetre precision, and normal function returns when it stops.",9,7],[62,"Why must language be mapped individually in each surgical patient?","George Ojemann showed that the location of language sites varies greatly between individuals.",9,8],[62,"Why are afterdischarges monitored during cortical stimulation mapping?","They are runs of seizure-like activity after the current stops and can spread into a clinical seizure.",9,9],[62,"How do spike recording and stimulation differ in epilepsy surgery workup?","Recording spikes identifies the irritable zone. Stimulation tests the function of the cortex.",9,10],[62,"What did Olds and Milner discover in 1954?","Rats repeatedly pressed a lever to stimulate electrodes in the septal area, sometimes in preference to food. This intracranial self-stimulation revealed reward pathways.",9,11],[62,"Which pathway and transmitter were later linked to intracranial self-stimulation?","The medial forebrain bundle and dopamine.",9,12],[62,"Does intracranial self-stimulation reflect reward or punishment?","Reward, because animals work to obtain the stimulation.",9,13],[62,"What did Salzman and Newsome show by microstimulating area MT in 1990?","Weak stimulation biased monkeys' motion judgements towards the cells' preferred direction. MT activity helps cause motion perception rather than just accompanying it.",9,14],[62,"What is kindling as described by Goddard?","Daily brief subconvulsive amygdala stimulation in rats produced lengthening afterdischarges. By about 2 weeks each train caused a generalised seizure, and the change lasted months.",9,15],[62,"What process does kindling model, and how does it differ from habituation?","It models epileptogenesis, the development of epilepsy. It is a progressive and lasting increase in seizure response, unlike habituation, long-term depression or status epilepticus.",9,16],[62,"How did Robert Post apply kindling to mood disorders?","Early mood episodes often follow stress, while later episodes become more frequent with smaller triggers or none.",9,17],[62,"Can kindled animals develop seizures without further stimulation?","Yes. Some kindled rats later have spontaneous seizures, which is why kindling models epileptogenesis.",9,18],[65,"What is optogenetics?","It is the use of light to switch genetically defined neurons on or off. Control is cell-type specific and accurate to the millisecond in a behaving animal.",10,1],[65,"Which two features of an experiment point specifically to optogenetics rather than deep brain stimulation?","Only one genetically chosen cell type responds, and the behaviour starts and stops exactly with the light. No other tool gives both cell-type and millisecond precision.",10,2],[65,"What are opsins and where do they come from?","They are light-sensitive membrane proteins from algae and microbes. They move charged particles across the membrane when light strikes them.",10,3],[65,"How is an opsin gene delivered to neurons in an optogenetic study?","A viral vector such as adeno-associated virus or lentivirus carries the gene. The virus is injected into the target region.",10,4],[65,"How is opsin expression restricted to a single cell type?","By using a cell-type-specific promoter or a Cre-dependent construct. Only the chosen cells then make the protein and answer the light.",10,5],[65,"Why must an optic fibre be implanted as well as the virus injected?","Brain tissue scatters and absorbs light, so visible light cannot reach deep regions through the skull. The fibre brings light to within about 1 mm of the cells.",10,6],[66,"Which opsin excites neurons, and at what wavelength and colour of light?","Channelrhodopsin-2, from the alga Chlamydomonas, responds to blue light at about 470 nm. It is a cation channel letting sodium and calcium in.",10,7],[66,"How quickly does channelrhodopsin-2 make a neuron fire after the light comes on?","Within one or two milliseconds. This gives spike-by-spike control of firing.",10,8],[66,"Which opsins silence neurons, and with which light colours?","Halorhodopsin pumps chloride in under yellow light. Archaerhodopsin pumps protons out under yellow or green light.",10,9],[66,"Why do halorhodopsin and archaerhodopsin stop a neuron firing?","Both make the inside of the cell more negative, so they hyperpolarise it. The cell stays quiet while the light is on.",10,10],[66,"What does DREADD stand for and which drug activates the classic DREADDs?","Designer receptors exclusively activated by designer drugs. The original ones respond to the inert drug clozapine-N-oxide.",10,11],[66,"Which DREADD excites neurons and which inhibits them, and through which G proteins?","hM3Dq comes from the M3 receptor and couples to Gq, so it excites. hM4Di comes from M4 and couples to Gi, so it inhibits.",10,12],[66,"How were DREADD receptors engineered, and by whom?","Bryan Roth's group altered human muscarinic receptors so they no longer respond to acetylcholine. They respond instead to an otherwise inert designer drug.",10,13],[66,"How long does a single dose of clozapine-N-oxide keep a DREADD active?","The effect lasts hours. That suits questions about sustained states such as a whole night of sleep.",10,14],[66,"Why are newer DREADD agonists such as deschloroclozapine preferred to clozapine-N-oxide?","Some clozapine-N-oxide is converted back into clozapine, which has its own actions. Newer agonists avoid this confound.",10,15],[66,"Which question does optogenetics answer best and which does chemogenetics answer best?","Optogenetics answers when activity matters, because it is precise in time. Chemogenetics answers whether sustained activity over hours matters.",10,16],[66,"What is the KORD chemogenetic tool and what activates it?","KORD is built from the kappa opioid receptor and is inhibitory. It is switched on by salvinorin B.",10,17],[66,"Why are optogenetics and chemogenetics not used as treatments in patients?","Both need a foreign gene to be introduced into neurons. That is not acceptable in clinical practice, unlike deep brain stimulation.",10,18],[66,"How can optogenetics test a single pathway rather than a whole region?","Light is shone on the axon terminals of the projection, for example prefrontal cortex fibres in the dorsal raphe. Only that pathway is driven.",10,19],[67,"Why can deep brain stimulation not do what optogenetics does?","Current from an electrode affects every cell and passing fibre near the tip. It cannot select a cell type.",10,20],[69,"What physical principle underlies transcranial magnetic stimulation?","Faraday electromagnetic induction. A rapidly changing magnetic field from the coil induces an electric current in the cortex.",11,1],[69,"Why can a coil held on the scalp affect the brain without any electrode touching it?","The skull resists electric current but is effectively transparent to magnetic fields. The field crosses it and induces current in the cortex beneath.",11,2],[69,"Why must the TMS pulse be brief rather than a steady field?","Only a changing magnetic field induces a current. A static field would do nothing.",11,3],[69,"Who first stimulated the human motor cortex with a scalp coil, and when?","Anthony Barker's team, in 1985. This introduced transcranial magnetic stimulation.",11,4],[69,"Does TMS heat the brain or pass current through the scalp?","No to both. The pulses are far too brief to warm tissue, and the current is induced rather than conducted.",11,5],[70,"How deep does standard TMS act, and what does this mean for targets?","About 2 to 3 cm. It reaches cortex but not deep nuclei.",11,6],[70,"Which coil gives a focused spot, and which design reaches a little deeper?","A figure-of-eight coil focuses the field. An H-coil, used in deep TMS, reaches somewhat deeper.",11,7],[70,"What is a motor evoked potential?","It is the electrical response recorded from a hand muscle after a single pulse over the hand area of motor cortex. The hand visibly twitches.",11,8],[70,"Define the resting motor threshold.","The lowest intensity giving a motor evoked potential of at least 50 microvolts in about half of trials, such as 5 of 10, with the muscle relaxed.",11,9],[70,"Why is TMS dose set as a percentage of each person's motor threshold?","Skull thickness and cortical excitability vary between people. Individual dosing keeps the stimulus equivalent.",11,10],[70,"What is short-interval intracortical inhibition and which receptor underlies it?","A weak pulse 1 to 5 ms before a strong one shrinks the motor evoked potential. It reflects GABA-A inhibition within the cortex.",11,11],[70,"How do benzodiazepines such as lorazepam alter short-interval intracortical inhibition?","They deepen it, because they enhance GABA-A function. This confirms the GABA-A basis of the measure.",11,12],[70,"What happens with paired pulses about 10 to 15 ms apart, and at 50 to 200 ms?","At 10 to 15 ms the second response grows, which is intracortical facilitation. Two strong pulses 50 to 200 ms apart give GABA-B mediated long-interval inhibition.",11,13],[70,"Which repetitive TMS frequencies raise and which lower cortical excitability?","High frequency, 5 to 20 Hz and usually 10 Hz, raises excitability like long-term potentiation. About 1 Hz lowers it like long-term depression.",11,14],[70,"How long do the effects of repetitive TMS outlast the session?","Excitability stays changed for minutes to hours after stimulation stops. Single pulses leave no lasting change.",11,15],[70,"Describe the pulse pattern of theta-burst stimulation.","Bursts of three pulses at 50 Hz, repeated five times a second. This copies the hippocampal theta rhythm with fast bursts on top.",11,16],[70,"How do intermittent and continuous theta-burst stimulation differ in effect?","Intermittent theta burst runs 2 seconds on and 8 seconds off and excites. Continuous theta burst runs without pauses and inhibits.",11,17],[70,"How many pulses does intermittent theta burst give, and over how long?","About 600 pulses in roughly 3 minutes. That is far shorter than a standard 10 Hz session.",11,18],[70,"What did the THREE-D trial show in 2018?","Intermittent theta-burst stimulation was as effective as a 37-minute 10 Hz session for depression. This supported the much shorter protocol.",11,19],[70,"How does magnetic seizure therapy differ from ordinary TMS?","It uses magnetic stimulation to induce a seizure under anaesthesia. Ordinary TMS does not cause a seizure.",11,20],[73,"What are the defining features of transcranial direct current stimulation?","A weak constant current of 1 to 2 mA passes between two sponge electrodes on the scalp. Sessions usually last about 20 minutes.",12,1],[73,"Does tDCS make neurons fire?","No. The current is subthreshold, so it only biases the resting membrane potential towards or away from threshold.",12,2],[73,"What do anodal and cathodal tDCS do to cortical excitability?","Neurons under the anode are slightly depolarised and fire more readily. Neurons under the cathode are hyperpolarised and fire less readily.",12,3],[73,"In which direction does current flow in tDCS, and what limits how much reaches the cortex?","From the anode to the cathode through the head. Much is shunted through the scalp, but enough reaches cortex to shift excitability.",12,4],[73,"How does electroconvulsive therapy differ from tDCS, apart from the current?","The current in ECT is vastly larger and the aim is to induce a seizure. The patient is anaesthetised.",12,5],[74,"What did Nitsche and Paulus show in 2000?","With the anode over motor cortex, TMS-evoked motor potentials grew larger. Cathodal current made them smaller.",12,6],[74,"How long can the after-effect of about 13 minutes of anodal tDCS last?","Up to about 90 minutes. Longer stimulation gives longer after-effects.",12,7],[74,"What does the carbamazepine experiment tell us about the immediate effect of tDCS?","Carbamazepine, a sodium channel blocker, abolished the rise in excitability during stimulation. So the immediate effect is simple membrane polarisation.",12,8],[74,"What does dextromethorphan do to tDCS effects, and what does this show?","It blocks NMDA receptors and removes the lasting after-effect while sparing the immediate one. The after-effect therefore depends on NMDA receptors, like long-term potentiation.",12,9],[74,"Why do the drug studies argue against a purely placebo explanation of tDCS?","The two effects can be blocked separately by drugs with known mechanisms. A placebo response would not behave in this selective way.",12,10],[74,"How is a convincing sham produced in tDCS research?","The current ramps up over about 30 seconds and then switches off. People feel the same initial tingle but get almost no stimulation.",12,11],[74,"What did Gandiga and Cohen demonstrate in 2006?","Participants could not distinguish ramped sham tDCS from real tDCS. This makes double-blind trials possible.",12,12],[74,"How do tACS and tRNS differ from tDCS?","Transcranial alternating current stimulation oscillates at a chosen rhythm to entrain brain waves. Transcranial random noise stimulation applies random noise instead of a steady current.",12,13],[74,"Where are the electrodes usually placed in tDCS trials for depression?","The anode over the left dorsolateral prefrontal cortex. The cathode goes over the right supraorbital region.",12,14],[74,"Does tDCS cause seizures or heat the tissue?","No. Heating is negligible at these currents and seizures are not caused.",12,15],[74,"What is the commonest confusion between tDCS and TMS?","tDCS applies a weak current directly through scalp electrodes. TMS induces current in the cortex with a changing magnetic field.",12,16],[75,"A 2 mA constant current runs for 20 minutes with the positive pad over left DLPFC: which technique and expected effect?","This is anodal tDCS. Excitability under the anode rises.",12,17],[77,"Describe the hardware used in deep brain stimulation.","Thin electrodes are passed into a deep target through small burr holes in the skull. Wires run under the neck skin to a pulse generator below the collarbone.",13,1],[77,"A man aged 38 with severe OCD has a scar on his scalp and a device below the left clavicle: what treatment is this?","Deep brain stimulation. The generator below the clavicle with a lead reaching the skull is the giveaway.",13,2],[77,"Which DBS parameters can staff adjust from outside the body?","Amplitude, pulse width, frequency and which electrode contact is active. Nothing needs to be re-operated.",13,3],[77,"How does DBS differ from capsulotomy and cingulotomy?","DBS destroys no tissue and can be adjusted or switched off. Capsulotomy and cingulotomy are permanent ablative lesions.",13,4],[77,"How can DBS be distinguished from vagus nerve stimulation on examination?","Both have a chest generator and a lead in the neck. The DBS lead continues to the skull, whereas the VNS lead ends on the vagus nerve.",13,5],[77,"Where did deep brain stimulation originate?","From Benabid's work in Grenoble in the late 1980s. He found that high-frequency thalamic stimulation abolished tremor much like a lesion.",13,6],[78,"What frequency does effective deep brain stimulation require?","Above 100 Hz, typically about 130 Hz. Low frequencies do little or may worsen symptoms.",13,7],[78,"How does high-frequency DBS work on its target circuit?","It causes reversible functional inhibition of local cell bodies while firing nearby axons. It also disrupts abnormal oscillations across the circuit, sometimes called an informational lesion.",13,8],[78,"Does DBS destroy or heat the tissue it stimulates?","No. It neither heats nor ablates tissue, and it does not simply boost the target's normal firing.",13,9],[78,"Which targets are used for deep brain stimulation in Parkinson's disease?","The subthalamic nucleus or the globus pallidus internus. Subthalamic stimulation eases tremor and rigidity.",13,10],[78,"Why is DBS useful as a research tool in humans?","It can be switched on and off without the patient knowing. This allows blinded, sham-controlled tests of circuit theories.",13,11],[78,"What did Mayberg's team report in 2005, and in which target?","They stimulated the subcallosal cingulate, Brodmann area 25, in six people with treatment-resistant depression. Four of the six improved.",13,12],[78,"Why was the subcallosal cingulate chosen as a depression target?","PET had shown it to be overactive in depression and quieter after recovery. This fitted a circuit model of the illness.",13,13],[78,"Did large sham-controlled trials confirm DBS for depression?","No. Trials such as BROADEN in 2017 showed no clear benefit over sham stimulation.",13,14],[78,"Which targets have been used for DBS in obsessive-compulsive disorder?","The anterior limb of the internal capsule was first, reported by Nuttin in 1999. Later work moved slightly lower to the ventral capsule and ventral striatum beside the nucleus accumbens.",13,15],[78,"What are local field potentials, and what can a DBS electrode do with them?","They are the summed electrical activity of nearby cells. DBS electrodes can record them as well as stimulate.",13,16],[78,"Which oscillation is excessive in the parkinsonian subthalamic nucleus, and what does it track?","Beta activity, about 13 to 30 Hz. It tracks slowness and stiffness and falls with levodopa and with stimulation.",13,17],[78,"What is adaptive or closed-loop deep brain stimulation?","The device senses subthalamic beta activity and stimulates only when it rises, like a thermostat. Little and colleagues showed in 2013 that it worked at least as well with less energy.",13,18],[78,"Which oscillation rises with movement and dyskinesia in Parkinson's disease?","Gamma activity. Adaptive stimulation is triggered by beta rather than gamma or theta.",13,19],[81,"Why is the vagus nerve stimulator placed on the left cervical vagus?","The right vagus mainly supplies the sinoatrial node, so stimulating it risks bradycardia. The left mainly supplies the atrioventricular node, so the risk is lower.",14,1],[81,"Describe the hardware of implanted vagus nerve stimulation.","A spiral cuff electrode wraps around the left cervical vagus in the neck. A wire runs to a pulse generator under the skin of the chest.",14,2],[81,"What are typical vagus nerve stimulation settings?","Trains at about 20 to 30 Hz for 30 seconds every 5 minutes. This is the usual duty cycle.",14,3],[81,"Why is vagus nerve stimulation delivered in cycles rather than continuously?","Cycling limits side effects during the off periods. It also saves battery life.",14,4],[81,"Is the choice of side in VNS explained by afferent content or neck anatomy?","No. Both vagi run in the carotid sheath, both are mostly afferent and both give laryngeal branches, so the reason is cardiac.",14,5],[82,"What proportion of vagal fibres are afferent, and why does this matter?","About 80 percent. Vagus nerve stimulation is thought to work mainly through these ascending fibres.",14,6],[82,"Where do vagal afferents first relay centrally?","In the nucleus of the solitary tract in the medulla. Only then do signals pass onward.",14,7],[82,"Which structures receive projections from the nucleus of the solitary tract in the proposed antidepressant route?","The locus coeruleus, raphe nuclei, amygdala and hypothalamus. The nucleus ambiguus is motor and is not the entry point.",14,8],[82,"What did Krahl's animal work show about the locus coeruleus and VNS?","Lesioning the locus coeruleus abolished the anti-seizure effect of vagus nerve stimulation in rats. This supports the noradrenergic route.",14,9],[82,"What time course did Dorr and Debonnel find for noradrenaline and serotonin changes with VNS?","Locus coeruleus firing rose within days. Raphe serotonin firing rose only after about two weeks and needed intact noradrenaline neurons.",14,10],[82,"Why does a patient become hoarse when the VNS device cycles on?","Stimulated efferent fibres reach the larynx through the recurrent laryngeal nerve. Hoarseness, cough and throat discomfort occur during each on-cycle.",14,11],[82,"For which condition was vagus nerve stimulation first used, and how did psychiatric interest arise?","It was first used for drug-resistant epilepsy. Mood often improved even without fewer seizures, as Elger reported in 2000.",14,12],[82,"What did Dawson's 2021 trial show about VNS in stroke?","Vagus nerve stimulation paired with arm rehabilitation improved arm function more than sham. Paired noradrenaline and acetylcholine bursts may boost plasticity during practice.",14,13],[82,"How is the vagus reached without surgery, and which nerve is stimulated?","Transcutaneous auricular VNS clips an electrode to the cymba conchae of the outer ear. That skin is supplied by the auricular branch of the vagus, Arnold's nerve.",14,14],[82,"Why is the earlobe used as the sham site in taVNS studies?","It is supplied by the great auricular nerve, C2 to C3, with little vagal input. It feels similar but misses the vagus.",14,15],[82,"How strong is the evidence for transcutaneous auricular vagus nerve stimulation?","It is still early. The technique is mainly a research tool at present.",14,16],[82,"Which central nucleus do candidates wrongly name as the first relay for vagal afferents?","The locus coeruleus or raphe nuclei. The first central relay is in fact the nucleus of the solitary tract.",14,17],[83,"A healthy volunteer has an ear clip on the cymba conchae during a memory task: which technique is this?","Transcutaneous auricular vagus nerve stimulation. It needs no surgery and stimulates Arnold's nerve.",14,18],[85,"What are Willner's three criteria for validity of an animal model?","Face validity means it looks like the illness, construct validity means it shares the cause or mechanism, and predictive validity means it responds to effective treatments. Willner set these out in 1984.",15,1],[85,"A model responds to known antidepressants but shares no mechanism and looks nothing like depression: which validity does it have?","Predictive validity only. Drug response does not demonstrate construct validity.",15,2],[85,"Which validities are strong and weak for the forced swim test?","Predictive validity for monoamine antidepressants is strong, so it screens drugs well. Face and construct validity are weak, so it explains little about depression.",15,3],[85,"Describe the forced swim test and what is measured.","A rat is placed in an inescapable water cylinder, struggles and then floats. Immobility time is measured and antidepressants such as imipramine shorten it.",15,4],[85,"What is the mouse equivalent of the forced swim test?","The tail suspension test, in which the mouse hangs by its tail. Immobility time is scored over a session of about six minutes.",15,5],[85,"Why are the swim and tail suspension tests called screens rather than models of depression?","They respond to a single dose, unlike patients who need weeks of treatment. They therefore detect drug activity without modelling the illness.",15,6],[86,"In the learned helplessness paradigm, which animal later fails to escape and why?","The yoked animal that received the same shocks without any control. Lack of control, not the shock itself, causes the later passivity.",15,7],[86,"What does chronic unpredictable mild stress produce, and how is it measured?","It produces anhedonia, measured as reduced sucrose preference. Only weeks of antidepressant treatment restore it.",15,8],[86,"Name three other stress-based models of depression.","Social defeat by an aggressive resident, early-life maternal separation, and olfactory bulbectomy. Bulbectomy makes rats hyperactive.",15,9],[86,"Describe the elevated plus maze and the drug effect expected.","A raised cross with two walled and two open arms. Diazepam increases time spent in the open arms.",15,10],[86,"How does the light-dark box differ from passive avoidance?","In the light-dark box, chlordiazepoxide increases time in the lit side, so it measures anxiety. The same apparatus with a shock in the dark compartment becomes a memory test.",15,11],[86,"What does the Morris water maze test, and what impairs performance?","It tests spatial memory, as the rat finds a hidden platform using room cues. Hippocampal lesions and NMDA blockers slow learning.",15,12],[86,"In the radial arm maze, how are working and reference memory errors distinguished?","Re-entering an arm already emptied is a working memory error. Entering an arm that was never baited is a reference memory error.",15,13],[86,"What is spontaneous alternation in the T-maze and what reduces it?","Rats normally alternate between arms on successive trials. Hippocampal lesions and scopolamine reduce this alternation.",15,14],[86,"What is prepulse inhibition, and how is it altered pharmacologically and in schizophrenia?","A soft tone about 100 ms before a loud noise reduces the startle, reflecting sensorimotor gating. Amphetamine and NMDA blockers reduce it, antipsychotics restore it, and it is reduced in schizophrenia.",15,15],[86,"What is latent inhibition and what abolishes it?","A stimulus heard repeatedly without consequence is later learned about more slowly. Amphetamine abolishes this slowing, modelling excessive salience in psychosis.",15,16],[86,"Describe the maternal immune activation model and its adult findings.","A pregnant mouse is given poly I:C, a mimic of viral RNA, and maternal interleukin-6 alters fetal brain growth. Adult offspring show reduced prepulse inhibition, enlarged ventricles and dopamine changes after puberty.",15,17],[86,"Name three other animal models of psychosis besides maternal immune activation.","Amphetamine sensitisation, PCP as an NMDA blocker, and neonatal ventral hippocampal lesion. Each disturbs dopamine or glutamate systems.",15,18],[86,"Which models are used for Parkinson's, Alzheimer's and Huntington's disease?","Parkinson's uses 6-OHDA or MPTP lesions. Alzheimer's uses APP and PS1 transgenic mice, and Huntington's uses R6/2 mice.",15,19],[86,"How does a conditional knockout differ from a germline knockout?","A germline knockout removes the gene everywhere from conception and may be lethal. A conditional knockout uses Cre-lox so loxP-flanked genes are deleted only where Cre is expressed, and tamoxifen-inducible Cre adds timing control.",15,20],[90,"Which four factors reprogram adult cells into induced pluripotent stem cells?","Oct4, Sox2, Klf4 and c-Myc, the Yamanaka factors. They reset the epigenetic state of an adult cell.",16,1],[90,"When were mouse and human induced pluripotent stem cells first made?","Mouse cells in 2006 and human cells in 2007, by Takahashi and Yamanaka. Skin cells were reprogrammed in both cases.",16,2],[90,"How are iPSCs steered towards neurons of a particular brain region?","Morphogens such as Sonic hedgehog, Wnt, BMP4 or FGF8 are applied in sequence. These pattern the cells into region-specific neurons or glia.",16,3],[90,"What are the main advantages of iPSCs over embryonic stem cells?","No embryo is destroyed, as they come from adult somatic cells. They also carry the patient's own genome, including risk variants.",16,4],[90,"What are the main limitations of induced pluripotent stem cells?","They can form tumours called teratomas. They can also acquire genetic changes during prolonged culture.",16,5],[90,"How does direct conversion differ from iPSC reprogramming?","Factors such as Ascl1, Brn2 and Myt1l turn fibroblasts straight into neurons. The pluripotent stage is skipped altogether.",16,6],[90,"What role do neurotrophins such as BDNF and NGF play in these protocols?","They help neurons survive and mature. They do not reprogram or reset cell identity.",16,7],[91,"What did Marchetto find in neurons derived from girls with Rett syndrome?","The neurons carried the MECP2 mutation. They had smaller cell bodies and fewer synapses.",16,8],[91,"What did Brennand report in 2011 in neurons from people with schizophrenia?","The neurons showed fewer connections and reduced neurites. This was an early iPSC finding in psychosis.",16,9],[91,"Why are unrelated control cell lines a weak comparison in iPSC studies?","Two people differ at millions of DNA sites, and lines differ in how they were made. Genetic background is therefore uncontrolled.",16,10],[91,"What is an isogenic line and how is it made?","It is a line differing from the patient's own only at the variant of interest. CRISPR-Cas9 corrects the variant in patient cells or introduces it into a control line.",16,11],[91,"What are brain organoids?","Three-dimensional balls of tissue grown from stem cells. They self-organise into layered, cortex-like tissue.",16,12],[91,"What did Lancaster model with the first cerebral organoids in 2013?","Microcephaly caused by a CDK5RAP2 mutation. Progenitor cells stopped dividing and became neurons too early.",16,13],[91,"What did Mariani report in 2015 in organoids from boys with idiopathic autism and large heads?","They produced too many GABAergic inhibitory neurons compared with their fathers' organoids. Raised FOXG1 expression drove this.",16,14],[91,"Why does an organoid develop a necrotic core?","It has no blood vessels, so beyond a few millimetres the centre is starved of oxygen. The inner cells then die.",16,15],[91,"What other limitations restrict the use of brain organoids?","Their neurons stay fetal-like, so they model early development better than late-onset illness. Batches vary and microglia are absent, as these arise from yolk-sac mesoderm.",16,16],[91,"What is an assembloid, and what has it shown about interneuron migration?","It is formed by fusing organoids from different regions. When a ventral forebrain organoid joins a cortical one, interneurons migrate across, and this migration is abnormal in Timothy syndrome.",16,17],[91,"Which gene is mutated in Timothy syndrome?","CACNA1C, which encodes a calcium channel subunit. Birey reported abnormal interneuron migration in assembloids in 2017.",16,18],[91,"Are iPSCs pluripotent or totipotent, and where do they come from?","They are pluripotent, not totipotent. They are made from adult somatic cells, not embryos or germ cells.",16,19],[91,"How does an assembloid differ from a chimera?","An assembloid fuses region-specific organoids made from stem cells. A chimera mixes cells from two individuals in one organism.",16,20],[94,"What do midbrain dopamine neurons encode, according to Schultz?","A temporal difference reward prediction error. This is the gap between the reward obtained and the reward expected.",17,1],[94,"How does the dopamine burst change once a cue reliably predicts reward?","It transfers from the reward to the earliest reliable predictive cue. A fully predicted reward then produces no burst.",17,2],[94,"What happens to dopamine firing if an expected reward is withheld?","Firing dips below baseline at the time the reward was due. This is a negative prediction error.",17,3],[94,"Why is it wrong to say dopamine codes pleasure?","Dopamine tracks prediction rather than liking, and gives no burst to an expected reward. Hedonic pleasure is carried more by opioid systems.",17,4],[94,"What does the Rescorla-Wagner model of 1972 state?","The change in associative strength on each trial equals the prediction error multiplied by a learning rate. Prediction error is outcome minus expectation.",17,5],[94,"Why does a fully predicted outcome produce no learning in the Rescorla-Wagner model, and what does this explain?","Because the prediction error is zero. This explains blocking.",17,6],[94,"How does Hebb's rule differ from the Rescorla-Wagner rule?","Hebbian learning strengthens connections when cells fire together, with no error term. Rescorla-Wagner learns only from prediction error.",17,7],[95,"Contrast model-free and model-based learning, including their brain substrates.","Model-free learning stores values of past actions like a habit and uses the dorsolateral striatum. Model-based control plans with a mental map of the task using prefrontal cortex and the dorsomedial striatum.",17,8],[95,"What did Gillan find using Daw's two-step task?","A compulsivity dimension predicted less model-based control. This fits obsessive-compulsive disorder, addiction and binge eating.",17,9],[95,"What shifts behavioural control from plans towards habits?","Stress and repetition. Both tip the balance towards model-free control.",17,10],[95,"How does the Bayesian brain account describe perception?","Perception is a best guess that combines prior expectation with sensory evidence. Each is weighted by its precision or reliability.",17,11],[95,"What is predictive processing, and what is Friston's free energy principle?","Each cortical level predicts the level below, and only the mismatch is passed upward. The free energy principle is the broadest formulation of this idea.",17,12],[95,"How do current computational accounts explain delusions and hallucinations?","Over-precise sensory prediction errors make ordinary events feel significant, driving delusions. Excessively strong priors let expectation become perception, giving hallucinations.",17,13],[95,"What did Powers show in 2017 about conditioned hallucinations?","Volunteers trained to pair a tone with a picture later heard the tone when only the picture appeared. Voice-hearers did so more often.",17,14],[95,"What does it mean that the brain is a small-world network?","In graph theory terms it has high local clustering with short path lengths. A regular lattice has long paths and a random network little clustering.",17,15],[95,"What is the rich club, and why does it matter in schizophrenia?","A set of hubs such as the precuneus, cingulate and insula that connect to each other more than by chance. These costly hubs are often affected in schizophrenia.",17,16],[95,"What does dynamic causal modelling estimate?","It estimates directed or effective connectivity, that is which region drives which. It fits a generative model of regional influences.",17,17],[95,"How does multivariate pattern analysis differ from voxel-based morphometry?","MVPA trains a classifier, such as a support vector machine, on patterns across many voxels and tests it on new data. Voxel-based morphometry tests one voxel at a time.",17,18],[95,"A model scores 98 percent in training but 55 percent in a new cohort: what is this and how is it prevented?","This is overfitting; underfitting would be poor in both samples. Cross-validation guards against it by rotating training and held-out data.",17,19],[95,"What are the three components of the drift diffusion model, and how is slow decision-making in schizophrenia explained?","Drift rate reflects evidence quality, threshold reflects caution, and non-decision time covers the rest. Slow decisions in schizophrenia reflect a lower drift rate rather than extra caution.",17,20],[98,"What proportion of cortical neurons are pyramidal cells, and which transmitter do they use?","About 75 percent. They use glutamate, so they are excitatory.",18,1],[98,"Which cortical cells are the only output neurons, and where do they project?","Pyramidal cells. Their axons reach other cortical areas, the striatum, thalamus, brainstem and spinal cord.",18,2],[98,"What distinguishes Golgi type I from Golgi type II neurons?","Golgi type I neurons have a long axon and project far. Golgi type II neurons have a short axon and act locally.",18,3],[98,"Which neurons are pseudounipolar, and how are they arranged?","Sensory neurons of the dorsal root ganglion. A single stalk splits, with one branch to the periphery and one to the cord.",18,4],[98,"What is Nissl substance and what does the smooth endoplasmic reticulum make?","Nissl substance is rough endoplasmic reticulum, which makes proteins and stains darkly. Smooth endoplasmic reticulum makes the phospholipids of cell membranes.",18,5],[98,"What are Betz cells, where are they found and how large are they?","They are the giant pyramidal cells of layer V of primary motor cortex, Brodmann area 4. They approach 100 micrometres across and give the fastest corticospinal axons.",18,6],[99,"Which neuron is found only in cerebellar cortex, uses GABA and is its sole output?","The Purkinje cell. It inhibits the deep cerebellar nuclei, showing an output cell need not excite.",18,7],[99,"What are Von Economo neurons and in which illness are they lost early?","Large spindle cells in layer V of the anterior cingulate and frontoinsular cortex. Seeley found they are lost early in behavioural variant frontotemporal dementia.",18,8],[99,"What fraction of cortical interneurons express parvalbumin, and how do they fire?","About 40 percent. They are fast-firing GABA interneurons.",18,9],[99,"Where do basket cells and chandelier cells make their synapses?","Basket cells wrap the soma of the pyramidal cell. Chandelier cells grip the axon initial segment where the spike begins.",18,10],[99,"What do somatostatin and VIP interneurons do?","Somatostatin or Martinotti cells send axons to layer I and inhibit distal dendrites. VIP cells inhibit other interneurons, mainly somatostatin cells, which disinhibits pyramidal cells.",18,11],[99,"Which rhythm do parvalbumin interneurons pace, and at what frequency?","The gamma rhythm, at 30 to 80 Hz. Fast inhibition sets its timing.",18,12],[99,"What did Lewis find in the prefrontal cortex in schizophrenia?","Parvalbumin cells had less GAD67, the enzyme making GABA, and gamma was weaker during working memory. Pyramidal cell numbers were normal, so inhibitory timing fails.",18,13],[99,"Which cortical layer receives thalamic input, and which cells does it contain?","Layer IV. It holds small spiny stellate or granule cells that pass the signal up to layers II and III.",18,14],[99,"What are the roles of cortical layers V and VI?","Layer V sends output to the brainstem, spinal cord and striatum. Layer VI sends feedback to the thalamus.",18,15],[99,"How do granular and agranular cortex differ?","Sensory cortex is granular with a thick layer IV. Motor cortex is agranular, with a thin layer IV and a very large layer V.",18,16],[99,"How many layers has the neocortex and how many the allocortex?","Six in the neocortex and three in the allocortex. Allocortex includes the hippocampus as archicortex and olfactory cortex as paleocortex.",18,17],[99,"Which Brodmann areas correspond to primary motor, somatosensory, visual and auditory cortex?","Area 4 is primary motor and areas 3, 1 and 2 the postcentral somatosensory strip. Area 17 is primary visual on the calcarine sulcus, and areas 41 and 42 are primary auditory in Heschl's gyrus.",18,18],[99,"Which Brodmann areas form Broca's area and which relate to Wernicke's area?","Areas 44 and 45 in the inferior frontal gyrus form Broca's area. Area 22 is the superior temporal gyrus, with Wernicke's area at its posterior part.",18,19],[103,"What is the resting membrane potential of a neuron and why does it sit there?","About -70 mV, with the inside negative. It lies close to the potassium equilibrium potential because the membrane is most permeable to potassium, with a small sodium leak lifting it.",19,1],[103,"What does the sodium-potassium pump move per cycle, and why is it called electrogenic?","It pushes 3 sodium ions out and 2 potassium ions in for each ATP used. One extra positive charge leaves each cycle, so it contributes directly to the voltage.",19,2],[103,"What are the equilibrium potentials of potassium and sodium?","About -90 mV for potassium and about +60 mV for sodium. The resting potential lies between them, nearer potassium.",19,3],[103,"Which cation is most concentrated inside the resting neuron, and at what concentration?","Potassium, at about 140 mmol/L inside against 4 to 5 mmol/L outside. Sodium is about 145 mmol/L outside and 10 to 15 mmol/L inside.",19,4],[104,"At what voltage is threshold reached, and what happens next?","At about -55 mV. Voltage-gated sodium channels open and sodium rushes in, driving further channel opening.",19,5],[104,"What is the peak voltage of the action potential, and how does the cell then repolarise?","The inside reaches about +30 mV. Sodium channels inactivate and slower potassium channels open, so potassium leaves and the cell repolarises, dipping briefly below rest.",19,6],[104,"What is the absolute refractory period and why does it occur?","A period in which no stimulus can fire the cell. It occurs because the voltage-gated sodium channels are inactivated.",19,7],[104,"What is saltatory conduction?","The spike jumps between the nodes of Ranvier, where sodium channels cluster. Myelin insulates the stretches between the nodes, and the fastest myelinated fibres conduct at about 120 m/s.",19,8],[104,"How does tetrodotoxin affect nerve conduction?","It blocks voltage-gated sodium channels. All action potentials are therefore abolished.",19,9],[104,"What happens at the nerve terminal when the action potential arrives?","Voltage-gated calcium channels open and calcium binds synaptotagmin. SNARE proteins fuse the vesicle with the membrane so transmitter is released.",19,10],[104,"Which ion movements underlie an EPSP and an IPSP?","An excitatory postsynaptic potential comes mostly from sodium entering. An inhibitory one comes from chloride entering or potassium leaving.",19,11],[104,"What are electrical synapses and where are they common?","They are gap junctions that let current pass directly between cells. They are common in the retina.",19,12],[104,"How do ionotropic and G-protein coupled receptors differ?","Ionotropic receptors are ion channels that open within a millisecond. G-protein coupled receptors cross the membrane seven times and act more slowly, but amplify and spread the signal.",19,13],[104,"What happens to a receptor under prolonged agonist exposure, and under prolonged blockade?","Constant agonist causes desensitisation and then downregulation. Constant blockade causes upregulation.",19,14],[104,"What is a positive allosteric modulator?","A drug binding a site separate from the transmitter's own site, doing little alone. With transmitter present it shifts the dose-response curve to the left and can raise the peak.",19,15],[104,"What did Bliss and Lomo demonstrate in 1973?","A short high-frequency burst to the rabbit perforant path left the dentate response enlarged for hours. This is long-term potentiation.",19,16],[104,"Why is the NMDA receptor called a coincidence detector?","It needs glutamate bound and the membrane depolarised at the same time. Depolarisation expels its magnesium plug so calcium can enter.",19,17],[104,"What is the signalling cascade from NMDA receptor activation to a stronger synapse?","Calcium entry activates CaMKII via calmodulin. CaMKII drives more AMPA receptors into the synapse, strengthening it.",19,18],[104,"How is long-term depression induced, and what is the mechanism?","Slow stimulation at about 1 Hz gives only a small calcium rise. This activates enzymes that remove AMPA receptors from the synapse.",19,19],[104,"What did Bi and Poo show about the timing of synaptic change?","An input firing just before the cell fires is strengthened. An input firing just after is weakened, within a window of about 20 ms.",19,20],[108,"What is the main trade-off when choosing between a detailed and a simple neuron model?","A detailed model is faithful to the real cell but slow to run. A simple model loses detail but can simulate millions of cells, so the choice depends on the question.",20,1],[108,"What is a McCulloch-Pitts unit and how does it produce its output?","A 1943 binary model that sums weighted on-or-off inputs and outputs 1 if the total reaches threshold and 0 if not. It has no changing voltage and no ion channels.",20,2],[108,"What did McCulloch and Pitts show about networks of their simple units?","Networks of these units can compute logical functions, which made the unit the seed of artificial neural networks.",20,3],[108,"What technique did Hodgkin and Huxley use on the squid giant axon in 1952?","The voltage clamp, which holds membrane voltage steady while the resulting current is measured. It revealed separate sodium and potassium currents.",20,4],[108,"Which gating variables control sodium and potassium conductance in the Hodgkin-Huxley model?","Sodium is governed by activation m and inactivation h. Potassium is governed by n.",20,5],[109,"How does the Hodgkin-Huxley model explain the absolute refractory period?","After a spike the inactivation variable h stays low, so sodium channels cannot reopen until h recovers.",20,6],[109,"Why are Hodgkin-Huxley neurons rarely used in very large network simulations?","Each patch of membrane needs four linked equations, which demands heavy computing power. Simpler models without channel kinetics are used instead.",20,7],[109,"How does the leaky integrate-and-fire model represent a neuron?","Described by Lapicque in 1907, it treats the membrane as a leaky capacitor that sums input, fires a spike at threshold and then resets. It contains no ion channels.",20,8],[109,"What did Rosenblatt's perceptron of 1958 add, and what is its classic limitation?","It added weights that learn from errors. A single-layer perceptron sorts inputs into two groups but cannot solve the exclusive-or problem.",20,9],[109,"In cable theory, what is the length constant and how is it calculated?","It is the distance over which a passive voltage falls to about 37% of its starting value. It equals the square root of membrane resistance divided by internal resistance.",20,10],[109,"Which dendrite properties allow a passive signal to spread further?","Fewer leak channels (higher membrane resistance) or a wider dendrite (lower internal resistance). A thinner dendrite or higher internal resistance shortens the length constant.",20,11],[109,"What determines the membrane time constant and what does it influence?","It is membrane resistance multiplied by capacitance. It sets how fast the membrane charges and the window for temporal summation; capacitance does not set the length constant.",20,12],[109,"What is a compartmental model of a neuron?","A model that divides a real neuron into many linked pieces, each with its own channels, joining cable segments together.",20,13],[109,"How does a Hopfield network store and recall memories?","Units are linked by two-way weights so stored patterns become stable attractor states. A partial cue settles into the whole pattern, which is called pattern completion.",20,14],[109,"What keeps prefrontal cells firing during working memory once the cue has gone?","Strong recurrent excitation through slow NMDA synapses sustains the activity, while interneurons stop it spreading. A purely feedforward network cannot hold activity after input stops.",20,15],[109,"How did Murray's attractor model link NMDA dysfunction to schizophrenia?","Weakening NMDA input onto interneurons disinhibited the network and made the stored memory drift, mirroring working memory problems in schizophrenia.",20,16],[109,"How does temporal-difference learning differ from Rescorla-Wagner learning?","Rescorla-Wagner updates once per trial, while temporal-difference learning updates predictions moment by moment. Its error signal moves to the earliest cue, as dopamine firing does.",20,17],[112,"After a cortical stroke, which glial cells of macrophage lineage clear neuronal debris?","Microglia. When activated they retract their branches, become amoeboid and phagocytose dead cells and debris.",21,1],[112,"Which imaging method can detect activated microglia in psychiatric research?","TSPO PET, which is used in neuroinflammation studies of psychosis and depression.",21,2],[112,"What is the approximate ratio of glia to neurons in the human brain?","About 1:1, with roughly 86 billion neurons and a similar number of glia, as counted by Azevedo. The old 10:1 figure is wrong.",21,3],[112,"Which glial cell has a different embryonic origin from the others, and where does it come from?","Microglia arise from myeloid progenitors in the yolk sac. All other glia come from neural ectoderm.",21,4],[112,"Which astrocyte enzyme drives the glutamate-glutamine cycle?","Glutamine synthetase, found almost only in astrocytes, converts glutamate to glutamine. Neurons convert glutamine back to glutamate using glutaminase.",21,5],[113,"Why do astrocytes swell in hepatic encephalopathy?","Glutamine synthetase also clears ammonia, so excess ammonia in liver failure is converted to glutamine inside astrocytes, causing them to swell.",21,6],[113,"What are the three components of the tripartite synapse?","The presynaptic terminal, the postsynaptic spine and a surrounding astrocyte process, which releases D-serine and ATP.",21,7],[113,"What is the marker of astrocytes and which disease follows a mutation in its gene?","GFAP. A faulty GFAP gene causes Alexander disease, in which astrocytes fill with Rosenthal fibres.",21,8],[113,"What are circumventricular organs and give one example with its function?","Brain sites lacking a blood-brain barrier so the brain can sample blood. The area postrema detects toxins and triggers vomiting.",21,9],[113,"What is the glymphatic system and which astrocyte protein does it depend on?","A clearance flow of fluid in along arteries and out along veins that washes out waste such as amyloid. It depends on aquaporin-4 on astrocyte end-feet.",21,10],[113,"How does sleep affect glymphatic clearance?","During sleep the interstitial space grows by about 60% and clearance of waste increases.",21,11],[113,"How do oligodendrocytes and Schwann cells differ in how they myelinate axons?","One oligodendrocyte myelinates segments of many axons (up to about 50) in the CNS. One Schwann cell myelinates one segment of a single peripheral axon.",21,12],[113,"Which cells myelinate the optic nerve, and why?","Oligodendrocytes, because the optic nerve is part of the central nervous system.",21,13],[113,"Which myelinating cell is targeted in multiple sclerosis and which in Guillain-Barre syndrome?","Multiple sclerosis attacks oligodendrocyte myelin in the CNS. Guillain-Barre syndrome attacks Schwann cell myelin in peripheral nerves.",21,14],[113,"What white matter findings are reported in schizophrenia?","Myelin genes are less active in prefrontal cortex, and the large ENIGMA diffusion study of 4322 people found lower white matter integrity in almost every tract.",21,15],[113,"What is the role of NG2 glia in the adult brain?","These oligodendrocyte precursor cells persist into adulthood. After a lesion they divide and produce new, thinner myelin.",21,16],[113,"How do microglia prune synapses during development?","Weak synapses are tagged with complement proteins C1q and C3. Microglia carry the matching receptor and engulf the tagged synapses.",21,17],[113,"What did Sekar find about complement and schizophrenia risk?","High-expressing variants of the C4A gene, which acts upstream of C3, increase the risk of schizophrenia, implicating excessive synaptic pruning.",21,18],[113,"What is the role of radial glia in cortical development?","They act as scaffolds that new neurons climb to reach the cortex, building it inside out. They are also fetal cortical stem cells, and most later become astrocytes.",21,19],[114,"Which specialised cells line the floor of the third ventricle and project to the median eminence?","Tanycytes, a specialised type of ependymal cell that links CSF and blood to help the hypothalamus sense signals.",21,20],[117,"A 56-year-old malnourished man who drinks heavily is confused and hypoglycaemic. Why give parenteral thiamine before glucose?","Glucose metabolism consumes the remaining thiamine and can precipitate or worsen Wernicke's encephalopathy. Thiamine should come first, but hypoglycaemia must still be treated promptly.",22,1],[117,"What share of body weight and resting oxygen and glucose use does the adult brain account for?","About 2% of body weight but about 20% of resting oxygen and glucose use.",22,2],[118,"What process uses most of the brain's energy?","The sodium-potassium ATPase pump, which restores ion gradients after spikes and synaptic activity.",22,3],[118,"Why does loss of circulation damage the brain so quickly?","The brain stores almost no fuel, only a little glycogen mainly in astrocytes. Consciousness is lost within seconds and lasting damage starts within minutes.",22,4],[118,"How does glucose cross the blood-brain barrier and enter neurons?","By facilitated diffusion, not requiring energy. GLUT1 carries it across the barrier endothelium and GLUT3 takes it into neurons.",22,5],[118,"Does insulin control glucose uptake into the brain?","No. Brain uptake uses GLUT1 and GLUT3, which are not insulin-dependent; insulin-driven GLUT4 works in muscle and fat.",22,6],[118,"What is the normal ratio of CSF glucose to blood glucose?","CSF glucose is normally about 60% of blood glucose.",22,7],[118,"A 3-year-old girl has seizures and a CSF to blood glucose ratio below 0.4 with low lactate. What is likely and what treatment helps?","GLUT1 deficiency syndrome. A ketogenic diet helps because ketones enter the brain by monocarboxylate transporters, bypassing the faulty carrier.",22,8],[118,"What happens to pyruvate in the mitochondria and how does the TCA cycle start?","Pyruvate dehydrogenase converts pyruvate to acetyl-CoA, which joins oxaloacetate to form citrate. Acetyl-CoA also supplies the acetyl group of acetylcholine.",22,9],[118,"Where does most ATP from glucose come from?","Oxidative phosphorylation in mitochondria, with oxygen as the final electron acceptor, adding about 30 ATP per glucose.",22,10],[118,"How does lactate appear on MR spectroscopy and when is it seen?","As a doublet near 1.3 ppm. It is seen in hypoxia and in mitochondrial disease such as MELAS.",22,11],[118,"What fuels can the brain use during prolonged starvation?","Ketone bodies (beta-hydroxybutyrate and acetoacetate) from the liver enter via monocarboxylate transporters and can meet up to two thirds of needs. Free fatty acids cross the barrier poorly.",22,12],[118,"What is the astrocyte-neuron lactate shuttle?","Astrocytes take up glutamate with sodium, and pumping the sodium out speeds astrocyte glycolysis. The lactate made passes to neurons via MCT carriers as fuel; its importance is debated.",22,13],[118,"Which three enzymes need thiamine as a co-factor?","Pyruvate dehydrogenase, alpha-ketoglutarate dehydrogenase (inside the TCA cycle) and transketolase (in the pentose phosphate side pathway).",22,14],[118,"Which brain areas are damaged first in Wernicke's encephalopathy?","The most energy-demanding regions: the mammillary bodies, medial thalamus and periaqueductal grey.",22,15],[118,"Describe the steps of the GABA shunt.","Alpha-ketoglutarate becomes glutamate, then GABA. GABA transaminase makes succinic semialdehyde, which SSADH turns into succinate to rejoin the TCA cycle.",22,16],[118,"What accumulates in SSADH deficiency compared with GABA transaminase deficiency?","SSADH deficiency diverts succinic semialdehyde into GHB, raising GHB. GABA transaminase deficiency raises GABA but not GHB.",22,17],[118,"What roles do folate and vitamin B12 play in methylation?","They convert homocysteine back to methionine, which forms S-adenosylmethionine, the brain's main methyl donor.",22,18],[119,"What is the effect of the MTHFR C677T variant?","People with two copies (TT, about 1 in 10 Europeans) have about 30% enzyme activity and higher homocysteine.",22,19],[119,"A 30-year-old woman with a respiratory chain disorder has raised lactate after exercise. Which enzyme converts excess pyruvate to lactate?","Lactate dehydrogenase. It regenerates NAD so glycolysis can continue when oxidative phosphorylation fails.",22,20],[122,"Which dietary amino acids are the precursors of serotonin, histamine and the catecholamines?","Serotonin comes from tryptophan, histamine from histidine, and dopamine, noradrenaline and adrenaline from tyrosine.",23,1],[122,"Why does tryptophan depletion lower brain serotonin within hours?","Tryptophan hydroxylase is not saturated at normal plasma tryptophan, so serotonin synthesis follows tryptophan supply. Removing tryptophan rapidly reduces synthesis.",23,2],[122,"Which transmitters are monoamines but not catecholamines?","Serotonin, an indoleamine with an indole ring, and histamine. Catecholamines are dopamine, noradrenaline and adrenaline.",23,3],[122,"What are the rate-limiting enzymes for catecholamine and serotonin synthesis, and which co-factor do they share?","Tyrosine hydroxylase (making L-DOPA) and tryptophan hydroxylase (making 5-HTP). Both need tetrahydrobiopterin.",23,4],[123,"Which enzyme converts both L-DOPA to dopamine and 5-HTP to serotonin, and what co-factor does it need?","Aromatic L-amino acid decarboxylase (DOPA decarboxylase). It needs pyridoxal phosphate from vitamin B6.",23,5],[123,"Why is carbidopa given with L-DOPA in Parkinson's disease?","Carbidopa blocks peripheral AADC, so less L-DOPA is converted outside the brain and more reaches the brain.",23,6],[123,"Which enzyme is present in noradrenergic but not dopaminergic neurons, and where does it work?","Dopamine beta-hydroxylase, which works inside vesicles. PNMT in the adrenal gland then converts noradrenaline to adrenaline.",23,7],[123,"What are the features of congenital dopamine beta-hydroxylase deficiency?","No noradrenaline, high dopamine, and fainting on standing because of orthostatic hypotension.",23,8],[123,"Where are histamine neurons located and how is histamine inactivated?","All lie in the tuberomammillary nucleus of the hypothalamus. Histamine is cleared by enzymes, not by reuptake.",23,9],[123,"How is melatonin made and what controls its timing?","The pineal gland converts serotonin to melatonin in two steps (N-acetylation then O-methylation) at night. Sympathetic input during darkness switches on the first step.",23,10],[123,"Which enzyme makes acetylcholine and how is it altered in Alzheimer's disease?","Choline acetyltransferase joins choline and acetyl-CoA. It is markedly reduced in cortex in Alzheimer's disease due to loss of basal forebrain cholinergic neurons.",23,11],[123,"How do organophosphate pesticides cause toxicity?","They block acetylcholinesterase in the synaptic cleft, so acetylcholine accumulates and floods the synapse.",23,12],[123,"How are glutamate and GABA synthesised?","Neurons make glutamate from glutamine using glutaminase. Glutamic acid decarboxylase, which needs vitamin B6, converts glutamate to GABA in one step.",23,13],[123,"Which GABA-related enzyme is lost from the striatum in Huntington's disease?","Glutamic acid decarboxylase (GAD), the enzyme that makes GABA, as shown by Bird and Iversen.",23,14],[123,"How does the antiepileptic vigabatrin increase brain GABA levels?","It inhibits GABA transaminase, the enzyme that breaks down GABA, so GABA levels rise.",23,15],[123,"What is the main inhibitory transmitter of the spinal cord and brainstem?","Glycine. GABA is the main inhibitory transmitter in the brain, used at roughly a third of synapses.",23,16],[123,"Where is monoamine oxidase located and how do MAO-A and MAO-B differ in substrate?","MAO is on the outer mitochondrial membrane inside cells. MAO-A prefers serotonin, noradrenaline and tyramine; MAO-B prefers dopamine and is rich in astrocytes.",23,17],[123,"A 25-year-old man develops sudden parkinsonism after injecting a synthetic opioid. Which mechanism explains this?","MPTP contamination. MAO-B converts MPTP into the toxin MPP+, which destroys dopamine neurons.",23,18],[123,"What are the main metabolites of dopamine, serotonin and noradrenaline?","Dopamine gives HVA and serotonin gives 5-HIAA. Noradrenaline gives MHPG in the brain and VMA in the periphery, used to test for phaeochromocytoma.",23,19],[123,"Which CSF finding did Asberg link to suicidal behaviour, and what did Brunner find?","Asberg linked low CSF 5-HIAA to violent suicide attempts. Brunner found an X-linked MAO-A mutation in a Dutch family with impulsive aggression.",23,20],[127,"What did Otto Loewi's 1921 frog heart experiment demonstrate?","Fluid from a vagally stimulated heart slowed a second heart, proving chemical transmission by a substance later shown to be acetylcholine.",24,1],[127,"Who named the synapse and what does the term mean?","Sherrington named it in 1897. It is a junction where one neuron passes a signal to another cell.",24,2],[128,"What is an electrical synapse made of and how wide is the gap?","A gap junction formed by connexin 36 channels joining the two cytoplasms across a gap of about 3.5 nm.",24,3],[128,"What are the main properties of electrical synapses?","Current passes almost without delay, usually in both directions, without amplification or change of sign, and it weakens as it spreads.",24,4],[128,"Where are electrical synapses common in the adult brain and what is their function?","Between cortical inhibitory interneurons, in the inferior olive and in the thalamic reticular nucleus. They keep groups of cells firing synchronously.",24,5],[128,"What are the three parts of a chemical synapse and how wide is the cleft?","The presynaptic terminal with vesicles, a synaptic cleft of about 20 to 40 nm, and the postsynaptic membrane with receptors.",24,6],[128,"What is the active zone and which proteins organise it?","The presynaptic site where vesicles fuse. RIM and Munc13 tether docked vesicles beside voltage-gated calcium channels, and bassoon and piccolo are scaffold proteins.",24,7],[128,"What is the main scaffold of the postsynaptic density and what does it bind?","PSD-95, which uses PDZ domains to hold GluN2 subunits of NMDA receptors and links receptors to enzymes such as CaMKII.",24,8],[128,"Which postsynaptic scaffold protein has variants linked to autism?","SHANK3. SHANK and Homer tie the postsynaptic density to the cytoskeleton.",24,9],[128,"What is the typical synaptic delay at a chemical synapse and what causes it?","About 0.5 ms, due to calcium entry, vesicle fusion and transmitter diffusion. Electrical synapses have almost no delay.",24,10],[128,"What advantages do chemical synapses have over electrical synapses?","They are one-way, amplify signals because one vesicle opens thousands of receptors, can switch sign from excitation to inhibition, and support plasticity.",24,11],[128,"How do Gray type I and type II synapses differ?","Type I is asymmetric with a thick postsynaptic density and round vesicles, usually excitatory on spines. Type II is symmetric with flattened vesicles, usually inhibitory on somata, shafts and axons.",24,12],[128,"How are synapses classified by their target site?","Axodendritic, axosomatic or axoaxonic, according to whether they land on a dendrite, cell body or axon.",24,13],[128,"What is special about chandelier cells?","They make axoaxonic GABA synapses on the axon initial segment, where firing starts, so they powerfully control a neuron's output.",24,14],[128,"A 62-year-old male smoker has proximal weakness that improves briefly after maximal effort. What is the likely mechanism?","Lambert-Eaton myasthenic syndrome, with antibodies against presynaptic P/Q-type calcium channels reducing transmitter release; it is often linked to small cell lung cancer.",24,15],[128,"How does the synaptic lesion in myasthenia gravis differ from Lambert-Eaton syndrome?","Myasthenia gravis involves antibodies against postsynaptic acetylcholine receptors, whereas Lambert-Eaton affects presynaptic calcium channels.",24,16],[129,"Mice lacking one gap junction protein lose synchrony in the thalamic reticular nucleus. Which protein is missing?","Connexin 36, the protein forming neuronal gap junctions. Their chemical synapses remain normal.",24,17],[131,"A 54-year-old woman with Huntington's disease becomes low in mood after starting tetrabenazine. Which protein does the drug inhibit?","Vesicular monoamine transporter 2 (VMAT2), which loads monoamines into vesicles. Tetrabenazine blocks it reversibly; mood should be monitored.",25,1],[131,"Why does blocking VMAT2 reduce monoamine release?","Monoamines left in the cytoplasm are broken down by mitochondrial MAO, so less transmitter is stored and released.",25,2],[131,"How did reserpine contribute to the monoamine hypothesis of depression?","Reserpine irreversibly blocks VMAT2 and depletes monoamines, and its depressive effect supported the idea that low monoamines cause depression.",25,3],[131,"How are synaptic vesicles loaded with transmitter?","A proton pump acidifies the vesicle, and vesicular transporters exchange protons for transmitter. VMAT2 loads monoamines; other carriers load glutamate, GABA and acetylcholine.",25,4],[131,"What role does synapsin play in the nerve terminal?","It tethers reserve pool vesicles to actin. When phosphorylated during intense firing, it releases them to move to the active zone.",25,5],[132,"Which protein acts as the calcium sensor for fast vesicle release?","Synaptotagmin, which triggers fusion within about 200 microseconds of calcium entry at the active zone.",25,6],[132,"Which proteins form the SNARE fusion complex?","Synaptobrevin on the vesicle with syntaxin and SNAP-25 on the plasma membrane; they wind together to pull the membranes into fusion.",25,7],[132,"How does botulinum toxin cause muscle weakness and how long does it last?","It cleaves SNARE proteins (types A and E cut SNAP-25, type B cuts synaptobrevin), so acetylcholine is not released. The effect lasts about 3 months.",25,8],[132,"Why does tetanus toxin cause rigidity rather than weakness?","It cleaves synaptobrevin in spinal inhibitory interneurons, blocking glycine and GABA release so muscles become rigid.",25,9],[132,"What did del Castillo and Katz show at the frog neuromuscular junction?","Transmitter is released in quanta, each one vesicle. Miniature end-plate potentials of about 0.5 mV occur at rest, and evoked responses are whole multiples of this.",25,10],[132,"What does calcium change during quantal release?","Calcium changes the number of quanta released, not the size of each quantum.",25,11],[132,"How is acetylcholine cleared from the synaptic cleft?","Acetylcholinesterase splits it into choline and acetate within about 1 ms. A high-affinity choline transporter takes choline back for reuse.",25,12],[132,"How are monoamines cleared from the synapse?","Mainly by reuptake through DAT, NET and SERT, which co-transport sodium and chloride. Inside, VMAT2 repackages them or MAO degrades them.",25,13],[132,"How is dopamine cleared in the prefrontal cortex?","The prefrontal cortex has few dopamine transporters, so dopamine is cleared mainly by the noradrenaline transporter and COMT.",25,14],[132,"How is glutamate cleared and recycled?","Astrocytes take it up via EAAT2 and convert it to glutamine with glutamine synthetase. Neurons turn glutamine back into glutamate with glutaminase.",25,15],[132,"How are synaptic vesicles recycled after fusion?","Clathrin coats a pit of membrane and dynamin pinches it off, as Heuser and Reese showed. The new vesicle is refilled and reused.",25,16],[132,"What is the role of presynaptic autoreceptors?","Released transmitter binds autoreceptors on its own terminal, which reduce further release as negative feedback.",25,17],[135,"Describe the structure and ion selectivity of the GABA-A receptor.","A pentameric ligand-gated chloride channel, most often two alpha, two beta and one gamma subunit. Chloride entry inhibits the cell.",26,1],[135,"How do benzodiazepines and barbiturates differ in their action on GABA-A receptors?","Benzodiazepines bind between alpha and gamma subunits and increase opening frequency. Barbiturates increase the duration of each opening.",26,2],[135,"What are the four main classes of receptor and their typical speeds?","Ionotropic channels act in milliseconds; metabotropic GPCRs in seconds; enzyme-linked receptors such as TrkB are tyrosine kinases; intracellular steroid receptors change transcription over hours.",26,3],[135,"Which receptors belong to the Cys-loop pentameric family?","GABA-A and glycine receptors (chloride, inhibitory) and nicotinic and 5-HT3 receptors (cation, excitatory).",26,4],[135,"Which is the only ionotropic serotonin receptor?","5-HT3. All other serotonin receptors are G protein-coupled.",26,5],[135,"What are the main brain nicotinic receptor subtypes and which is linked to nicotine reward?","Alpha-4 beta-2 and alpha-7. Mice lacking the beta-2 subunit stopped self-administering nicotine.",26,6],[136,"What is the structure of the NMDA receptor and its co-agonists?","A tetramer of two GluN1 subunits, binding glycine or D-serine, and two GluN2 subunits, binding glutamate.",26,7],[136,"Why is the NMDA receptor described as a coincidence detector?","Magnesium blocks the pore at rest. It opens only when glutamate binds and the membrane is depolarised to expel magnesium, letting calcium in.",26,8],[136,"Which receptor mediates the fast excitatory postsynaptic potential?","The AMPA glutamate receptor, which passes sodium. Ionotropic glutamate receptors are AMPA, NMDA and kainate, all tetramers.",26,9],[136,"Which GABA-A alpha subunits are linked to sedation and to anxiolysis?","Alpha-1 is linked to sedation and amnesia; alpha-2 and alpha-3 are linked to anxiolysis.",26,10],[136,"What are delta-subunit GABA-A receptors and what acts on them?","Extrasynaptic receptors giving tonic inhibition. Neurosteroids such as allopregnanolone act strongly there, and flumazenil does not block them.",26,11],[136,"Why can GABA be excitatory in newborn neurons?","Before the chloride exporter KCC2 is expressed, intracellular chloride is high, so GABA-A opening depolarises the cell.",26,12],[136,"What type of receptor is GABA-B and how does it inhibit neurons?","A Gi-coupled metabotropic receptor that opens potassium channels and closes calcium channels, giving slow inhibition. Baclofen is an agonist.",26,13],[136,"What blocks glycine receptors and which disorder follows GLRA1 mutations?","Strychnine blocks them. GLRA1 mutations cause hyperekplexia, an exaggerated startle response.",26,14],[136,"How are dopamine receptors grouped by G protein coupling?","D1 and D5 couple to Gs and raise cAMP. D2, D3 and D4 couple to Gi and lower cAMP.",26,15],[136,"What is the difference between an autoreceptor and a heteroreceptor?","An autoreceptor senses the neuron's own transmitter, such as D2 on dopamine cells. A heteroreceptor senses a different transmitter.",26,16],[136,"How are muscarinic receptors coupled and what are their main roles?","M1, M3 and M5 couple to Gq; M2 and M4 to Gi. M1 serves memory, M2 slows the heart, M3 drives glands and smooth muscle, and M4 restrains striatal dopamine.",26,17],[136,"What are the roles of 5-HT1A, 5-HT2C and 5-HT7 receptors?","5-HT1A is a Gi somatodendritic autoreceptor in the raphe. 5-HT2C (Gq) knockout mice overeat and have seizures. 5-HT7 (Gs) shifts the clock in the suprachiasmatic nucleus.",26,18],[136,"Why does NMDA receptor blockade increase cortical excitation?","Parvalbumin fast-spiking interneurons are especially sensitive, so blockade silences them. Pyramidal cells are disinhibited and glutamate rises, supporting the phencyclidine model of schizophrenia.",26,19],[137,"A 78-year-old man becomes confused after starting procyclidine. Which receptor blockade most likely explains his memory impairment?","Blockade of the Gq-coupled muscarinic M1 receptor, which is abundant in cortex and hippocampus and supports memory. Anticholinergic burden should be reviewed.",26,20],[139,"A 29-year-old man takes propranolol for performance anxiety. Which G protein and second messenger does the blocked receptor use?","Beta-adrenergic receptors use Gs, which activates adenylyl cyclase to raise cAMP and activate protein kinase A.",27,1],[139,"Why does propranolol reduce the physical symptoms of anxiety?","Blocking beta-receptors prevents cAMP-driven increases in heart rate and skeletal muscle tremor, though the worry itself may remain.",27,2],[139,"What is a second messenger and which was the first discovered?","A small intracellular molecule that carries a receptor's signal onwards. Cyclic AMP was discovered by Sutherland in 1958.",27,3],[139,"How is a heterotrimeric G protein activated and switched off?","The active receptor swaps GDP for GTP on the alpha subunit, which separates from beta-gamma so both can signal. Alpha switches off by hydrolysing GTP.",27,4],[139,"How do beta-gamma subunits inhibit neurons through Gi-coupled receptors?","Beta-gamma directly opens GIRK potassium channels without cAMP, as used by M2, D2, 5-HT1A and GABA-B receptors.",27,5],[139,"How do cholera toxin and pertussis toxin affect G proteins?","Cholera toxin locks Gs in the active state. Pertussis toxin locks Gi off.",27,6],[139,"Which receptors use Gs to raise cAMP?","Beta-adrenergic, D1, 5-HT4, 5-HT6 and 5-HT7 receptors.",27,7],[139,"Which receptors are Gi-coupled and lower cAMP?","D2, alpha-2, 5-HT1A, mu opioid, M2 and GABA-B receptors.",27,8],[140,"How does the Gq pathway generate second messengers?","Gq activates phospholipase C, which splits PIP2 into IP3 and diacylglycerol.",27,9],[140,"What do IP3 and DAG each do?","IP3 releases calcium from internal stores in the endoplasmic reticulum. DAG stays in the membrane and activates protein kinase C.",27,10],[140,"Which receptors are coupled to Gq and use the phospholipase C pathway?","Alpha-1 adrenergic, 5-HT2A, 5-HT2C, M1, M3, M5 muscarinic and H1 histamine receptors.",27,11],[140,"What activates PKA, PKC and CaMKII?","PKA is activated by cAMP, PKC by DAG and calcium, and CaMKII by calcium bound to calmodulin.",27,12],[140,"Why is CaMKII considered a memory switch?","It can keep itself active after calcium falls, sustaining long-term potentiation. Mice lacking it fail spatial learning.",27,13],[140,"How does repeated signalling produce lasting change in neurons?","PKA enters the nucleus and activates the transcription factor CREB, which switches on genes such as BDNF.",27,14],[140,"How is nitric oxide made and how does it signal?","It is made on demand from arginine by nitric oxide synthase, not stored in vesicles. It diffuses to nearby cells and activates soluble guanylyl cyclase to raise cGMP.",27,15],[140,"In which direction can nitric oxide signal at synapses, and what triggers its release?","It can act as a retrograde messenger from the postsynaptic cell to the terminal. NMDA receptor activity triggers its release.",27,16],[140,"How does sildenafil affect the nitric oxide and cGMP pathway?","It inhibits phosphodiesterase 5, which breaks down cGMP, so cGMP levels rise.",27,17],[141,"Why do D2-blocking antipsychotics raise prolactin?","Dopamine from the arcuate nucleus acts on Gi-coupled D2 receptors on lactotrophs to suppress prolactin. Blocking D2 removes this brake.",27,18],[143,"Where are neuropeptides synthesised and how are they packaged?","On ribosomes in the cell body as large precursor proteins, which are cleaved into active peptides, packed into dense-core vesicles and transported down the axon.",28,1],[144,"How is the action of a released neuropeptide terminated?","By extracellular peptidases such as neprilysin and angiotensin-converting enzyme. There is no reuptake transporter for peptides.",28,2],[144,"On which type of receptor do almost all neuropeptides act?","G protein-coupled receptors, giving slow, long-lasting effects at nanomolar concentrations.",28,3],[144,"What is a neuromodulator and how does it differ from a fast transmitter?","A messenger that does not fire a cell itself but changes how strongly it responds to other inputs, often for minutes.",28,4],[144,"What is co-release? Give two examples.","Release of a peptide together with a fast classical transmitter from the same neuron. Pain fibres release substance P with glutamate; arcuate neurons release NPY with GABA.",28,5],[144,"Why is a peptide co-transmitter released only during high-frequency bursts?","Dense-core vesicles lie away from the active zone and need a large sustained calcium rise to fuse, whereas small clear vesicles empty after a single spike.",28,6],[144,"What is volume transmission and how is it recognised histologically?","Peptides released from dendrites and axonal swellings diffuse to distant receptors. It is suggested by a mismatch, with receptors where there are no peptide terminals.",28,7],[144,"Where is CRH made and what CSF and challenge findings are seen in depression?","CRH, a 41 amino acid peptide, is made in the paraventricular nucleus. In depression CSF CRH is raised and a CRH test dose gives a blunted ACTH response.",28,8],[144,"What are the main functions of neuropeptide Y?","NPY, the most abundant brain peptide, drives feeding and reduces fear. Soldiers with higher NPY coped better with survival training stress.",28,9],[144,"How does dynorphin acting at kappa receptors affect mood?","Dynorphin acts at kappa opioid receptors, is released by stress and reduces dopamine in the nucleus accumbens, causing dysphoria rather than pleasure.",28,10],[144,"What are the origins and main social roles of oxytocin and vasopressin?","Both are nine amino acid peptides from the paraventricular and supraoptic nuclei. Oxytocin drives milk let-down, maternal care and trust; vasopressin at V1a receptors drives male pair bonding.",28,11],[144,"What did vole studies show about vasopressin and pair bonding?","Monogamous prairie voles have far more V1a receptors in the ventral pallidum than promiscuous montane voles.",28,12],[144,"Which receptor does substance P act on and what processes does it mediate?","The NK1 receptor, involved in pain and vomiting.",28,13],[144,"What are endocannabinoids and why are they not stored in vesicles?","Fatty messengers, mainly anandamide and 2-AG. Lipids pass through membranes, so they are made on demand when postsynaptic calcium rises.",28,14],[144,"How do endocannabinoids reduce transmitter release?","They travel retrogradely from the postsynaptic cell to Gi-coupled CB1 receptors on the presynaptic terminal, which reduce release.",28,15],[144,"What is depolarisation-induced suppression of inhibition?","Brief depolarisation of a hippocampal neuron releases endocannabinoids that cut its GABA input via CB1 for about 30 seconds.",28,16],[144,"Where are orexin neurons located and what is their function?","Only in the lateral and perifornical hypothalamus, about 70,000 cells. They project to all arousal centres to stabilise wakefulness and also drive food seeking.",28,17],[144,"A 19-year-old man has daytime sleepiness and cataplexy. What orexin abnormality is expected?","Narcolepsy type 1 with loss of about 90% of orexin neurons and CSF orexin-A of 110 pg/mL or less.",28,18],[145,"Which enzymes make and break down the endocannabinoids?","DAG lipase alpha makes 2-AG and MAGL breaks it down. FAAH breaks down anandamide.",28,19],[145,"How do NPY and CCK differ in their effects on anxiety?","NPY reduces anxiety, whereas CCK provokes it.",28,20],[148,"What is the principal function of the endosome?","It sorts material taken in by endocytosis, recycling membrane and receptors to the surface or sending them to the lysosome for degradation.",29,1],[148,"Describe the steps of clathrin-mediated endocytosis.","The adaptor AP2 binds cargo and its receptor. Clathrin forms a basket-like coat that bends the membrane into a coated pit, which dynamin then cuts free.",29,2],[148,"What is the role of dynamin and what happens when it is blocked?","Dynamin is a GTPase that wraps the neck of a coated pit and pinches it off. When blocked, pits remain on long necks and terminals run out of vesicles.",29,3],[148,"What is the defect in the shibire fruit fly?","A heat-sensitive dynamin. At about 29 degrees vesicle retrieval fails and the fly is paralysed within minutes; cooling restores movement.",29,4],[148,"What did Brown and Goldstein show about endocytosis?","They showed receptor-mediated uptake of LDL cholesterol carriers, winning the Nobel Prize in 1985.",29,5],[149,"How can a nerve terminal keep releasing transmitter with only a few hundred vesicles?","Vesicle membrane is retrieved and reused, as shown by Heuser and Reese in 1973 using a tracer in frog nerve endings.",29,6],[149,"How does full-collapse fusion differ from kiss-and-run fusion?","In full-collapse the vesicle flattens into the membrane and is later retrieved by clathrin. In kiss-and-run a pore opens briefly and recloses, and the vesicle is reused within about a second.",29,7],[149,"How are recycled glutamate vesicles refilled?","The V-ATPase proton pump acidifies the vesicle and VGLUT uses that gradient to load glutamate. Plasma membrane carriers such as EAAT2 do not fill vesicles.",29,8],[149,"Why can peptide vesicles not be refilled at the terminal?","Peptides are made from precursors in the cell body, so new dense-core vesicles must be transported from the soma.",29,9],[149,"How does continued agonist exposure desensitise a GPCR?","GRK phosphorylates the receptor, then beta-arrestin binds, blocks G protein coupling and links the receptor to clathrin for internalisation.",29,10],[149,"What determines whether internalised receptors resensitise or are downregulated?","Receptors recycled from endosomes back to the surface resensitise, while those sent to lysosomes are degraded, causing downregulation.",29,11],[149,"How does endosomal trafficking of AMPA receptors underlie LTP and LTD?","In LTP, AMPA receptors move from recycling endosomes to the spine surface. In LTD, modest calcium activates phosphatases and AMPA receptors are removed by clathrin and dynamin.",29,12],[149,"What is transcytosis and how can large drugs use it to enter the brain?","Transport of cargo across a cell from one side to the other. Large proteins cross brain endothelium by binding receptors such as the transferrin receptor, so drugs can be linked to anti-receptor antibodies.",29,13],[149,"What are signalling endosomes and which motor moves them?","Endosomes carrying NGF bound to TrkA from the axon terminal back to the cell body to keep neurons alive. Dynein moves them retrogradely; kinesin moves cargo the other way.",29,14],[149,"A 22-year-old woman has psychosis, ataxia and vertical gaze palsy. Which disorder of endosomal trafficking is likely?","Niemann-Pick type C, in which faulty NPC1 traps cholesterol in late endosomes and lysosomes.",29,15],[149,"What endosomal change is seen early in Alzheimer's disease and Down syndrome?","Enlarged Rab5-positive early endosomes, which appear before amyloid plaques form.",29,16],[150,"Which membrane retrieval mode operates during intense high-frequency stimulation?","Bulk endocytosis, which takes in large membrane infoldings within seconds; new vesicles later bud from them because clathrin retrieval cannot keep up.",29,17],[152,"Which precursor protein is cleaved to give beta-endorphin, ACTH and MSH?","Pro-opiomelanocortin (POMC). Proenkephalin gives the enkephalins and prodynorphin gives the dynorphins.",30,1],[152,"What common neurochemical effect did Di Chiara and Imperato find for opioids, cocaine, amphetamine, nicotine and alcohol?","They all increased dopamine in the nucleus accumbens, the brain's reward hub, which explains their shared rewarding effect.",30,2],[152,"Why is heroin (diamorphine) more rewarding than morphine at the brain level?","It is a more fat-soluble prodrug that enters the brain faster and is then converted to morphine. Faster brain entry gives a stronger reward.",30,3],[152,"Which opioid receptors do beta-endorphin, the enkephalins and dynorphin each prefer?","Beta-endorphin binds mu and delta, the enkephalins favour delta, and dynorphin favours kappa.",30,4],[152,"Why does Addison's disease cause skin darkening, in terms of the POMC system?","Low cortisol drives excess POMC cleavage, producing excess MSH alongside ACTH, which darkens the skin.",30,5],[153,"What are the main effects of mu opioid receptor activation, and what reverses them?","Pain relief, euphoria, slowed breathing and pinpoint pupils. Naloxone reverses these effects.",30,6],[153,"How do opioids increase dopamine release from the ventral tegmental area?","They act on mu receptors on inhibitory GABA neurons, switching off the brake on dopamine cells. This is called disinhibition.",30,7],[153,"A man aged 30 in a UK detox unit has sweating, tachycardia and yawning after stopping heroin. What drives these features?","A rebound surge of noradrenaline from the locus coeruleus. Lofexidine or clonidine can reduce this rebound.",30,8],[153,"How does the mechanism of cocaine differ from that of amphetamine?","Cocaine blocks the dopamine, noradrenaline and serotonin transporters. Amphetamine enters the nerve ending, empties vesicles and runs the transporter in reverse.",30,9],[153,"What compound forms when cocaine is taken with alcohol, and why does it matter?","Cocaethylene, which is more toxic to the heart than cocaine alone.",30,10],[153,"A woman aged 19 becomes confused at a festival after taking ecstasy and drinking lots of water. What electrolyte problem is likely and why?","Hyponatraemia. MDMA releases vasopressin, so water is retained and sodium falls.",30,11],[153,"How does MDMA act on serotonin neurons, and what serious complications can follow?","It enters serotonin endings and runs the serotonin transporter backwards. The serotonin flood can cause hyperthermia and serotonin syndrome.",30,12],[153,"What receptor changes follow chronic heavy alcohol use, and why does sudden stopping risk seizures?","GABA-A receptors fall and NMDA receptors rise. On stopping, unopposed glutamate activity can trigger seizures.",30,13],[153,"What is kindling in alcohol withdrawal?","Each episode of withdrawal makes the next one more severe, including a higher risk of seizures.",30,14],[153,"Which receptor does nicotine act on to release dopamine, and what limits its effect?","Alpha-4 beta-2 nicotinic receptors on dopamine cells. These receptors quickly desensitise. Nicotine half-life is about 2 hours.",30,15],[153,"How do THC and synthetic cannabinoids (spice) differ at the CB1 receptor?","THC is a partial CB1 agonist, while spice compounds are full agonists and so far more toxic. CBD does not activate CB1.",30,16],[153,"How much does daily use of high-potency cannabis raise psychosis risk, and what counts as high potency?","About five-fold. High potency means more than 10% THC.",30,17],[153,"How does ketamine act, and what are the harms of repeated use?","It is an uncompetitive NMDA channel blocker at the PCP site, causing dissociation. Repeated use causes memory problems, abdominal cramps and ulcerative cystitis with bladder fibrosis.",30,18],[153,"A man aged 25 who uses nitrous oxide heavily develops leg numbness and ataxia with a normal serum B12. What is the mechanism?","Nitrous oxide oxidises the cobalt in B12, inactivating methionine synthase. This causes subacute combined degeneration of the cord despite a normal B12 level.",30,19],[154,"A man aged 23 has synaesthesia and visual trails that recur months after taking a drug on blotting paper. Which drug and receptor?","LSD, acting as an agonist at 5-HT2A receptors on layer V cortical pyramidal cells. Recurring visual changes are a persisting perceptual disturbance.",30,20],[157,"Which lobes does the lateral (Sylvian) sulcus separate, and what lies in its floor?","It separates the frontal and parietal lobes above from the temporal lobe below. The insula lies hidden in its floor.",31,1],[157,"Which gyrus and Brodmann areas form the primary motor and primary somatosensory cortex?","Primary motor cortex is the precentral gyrus, area 4. Primary somatosensory cortex is the postcentral gyrus, areas 3, 1 and 2.",31,2],[157,"Where is the leg represented on the motor homunculus, and which artery supplies it?","On the medial surface of the hemisphere, supplied by the anterior cerebral artery. Face and hand lie laterally in middle cerebral artery territory.",31,3],[158,"What proportion of right-handers and left-handers are left-hemisphere dominant for language?","About 95% of right-handers and about 70% of left-handers.",31,4],[158,"What is the Wada test and what does it establish?","A short-acting barbiturate is injected into one carotid artery to briefly suppress that hemisphere, then speech and memory are tested. It identifies the dominant hemisphere.",31,5],[158,"A man aged 70 seems flat and low after a right hemisphere stroke. What non-depressive explanation should be considered?","Aprosodia, a flat, unemotional voice from non-dominant damage, which can mimic depression. Right lesions also cause neglect and denial of weakness.",31,6],[158,"What is the classic triad of Wernicke's encephalopathy, and why is thiamine given before glucose?","Confusion, ataxia and eye movement palsies. Glucose without thiamine can worsen the damage, so parenteral thiamine is given first.",31,7],[158,"What are the features of Brown-Sequard syndrome?","Hemisection of the cord gives weakness and loss of position sense on the same side, with pain and temperature loss on the opposite side.",31,8],[158,"Why does syringomyelia cause cape-like loss of pain and temperature?","The central cavity damages crossing spinothalamic fibres in the anterior white commissure, sparing fine touch and position sense.",31,9],[158,"Which tracts are damaged in subacute combined degeneration and what reflex pattern results?","Dorsal columns, corticospinal tracts and peripheral nerves, giving absent ankle jerks with upgoing plantars.",31,10],[159,"What is the classic clinical picture of an anterior cerebral artery infarct?","Leg weaker than arm, grasp reflex, urinary incontinence and apathy (abulia). Bilateral infarction can cause akinetic mutism.",31,11],[159,"What is the classic picture of a middle cerebral artery stroke?","Face and arm weakness with homonymous hemianopia, plus aphasia if left-sided or neglect and anosognosia if right-sided.",31,12],[159,"What is locked-in syndrome and which artery is usually involved?","Basilar artery occlusion damages the ventral pons. The person is aware but can only communicate by vertical eye movement and blinking.",31,13],[159,"What are the features of lateral medullary syndrome and which artery is involved?","PICA or vertebral artery occlusion. Vertigo, hoarseness, dysphagia, Horner's syndrome, and pain loss on the same side of the face and opposite side of the body.",31,14],[159,"Distinguish the vessel and typical history of extradural and chronic subdural haemorrhage.","Extradural comes from the middle meningeal artery and shows a lucid interval. Chronic subdural comes from torn bridging veins, typically in older people, heavy drinkers and fallers.",31,15],[159,"How much CSF is made daily, what is its total volume, and where is it produced?","About 500 mL a day is made by the choroid plexus, with a total volume of about 150 mL.",31,16],[160,"Trace the flow of CSF from the lateral ventricles to its absorption.","Lateral ventricle, foramen of Monro, third ventricle, cerebral aqueduct, fourth ventricle, then foramina of Magendie and Luschka. It is absorbed by arachnoid granulations into venous sinuses.",31,17],[160,"At which brainstem levels do the cranial nerve nuclei lie?","III and IV in the midbrain, V to VIII in the pons, and IX to XII in the medulla.",31,18],[160,"In a third nerve palsy, what does a spared pupil versus a dilated pupil suggest?","A spared pupil suggests microvascular ischaemia, such as diabetes. A dilated pupil suggests compression, for example a posterior communicating artery aneurysm.",31,19],[160,"In a man aged 40 with apparent stupor, how does cold caloric testing help separate psychiatric from organic causes?","Nystagmus with the fast phase away from the cold ear means an awake cortex, as in psychiatric stupor. Tonic deviation alone suggests organic coma.",31,20],[164,"Which nuclei make up the striatum, and which make up the lentiform nucleus?","The striatum is the caudate plus putamen. The lentiform nucleus is the putamen plus globus pallidus.",32,1],[164,"What are the core members of the basal ganglia, and which nearby structures are not members?","Striatum, globus pallidus, subthalamic nucleus and substantia nigra. The thalamus, red nucleus and hippocampus are not members.",32,2],[164,"Why do the caudate and putamen share the name striatum?","They are one structure split by the internal capsule, with grey bridges crossing it that give a striped look. They share cells, origin and inputs.",32,3],[165,"What does the term corpus striatum include?","The caudate plus the whole lentiform nucleus, that is putamen and globus pallidus.",32,4],[165,"What forms the ventral striatum and what is its main function?","The merged caudate head and putamen below the internal capsule. Its main part is the nucleus accumbens, a reward hub.",32,5],[165,"What inputs does the striatum receive and what transmitter do its main cells use?","Glutamate from the cortex and dopamine from the substantia nigra pars compacta. Its medium spiny neurons use GABA.",32,6],[165,"Which nuclei are the main output of the basal ganglia to the thalamus?","The globus pallidus interna and the substantia nigra pars reticulata, which tonically inhibit the motor thalamus with GABA.",32,7],[165,"Which basal ganglia nucleus is excitatory and what transmitter does it use?","The subthalamic nucleus, which uses glutamate. The other members use GABA or dopamine.",32,8],[165,"Why is the substantia nigra dark and what happens to it in Parkinson's disease?","Its dopamine neurons contain neuromelanin, a dopamine breakdown pigment. In Parkinson's these cells die, so the nigra turns pale.",32,9],[165,"Who first showed low striatal dopamine in Parkinson's disease, and when?","Ehringer and Hornykiewicz in 1960.",32,10],[165,"Describe the direct pathway of the basal ganglia and its net effect.","Striatal neurons with D1 receptors inhibit GPi, releasing the thalamus to drive the cortex. The net effect is to allow movement.",32,11],[165,"Trace the indirect pathway and state its net effect.","Striatum (D2) to GPe to subthalamic nucleus to GPi to thalamus. The net effect is to suppress movement.",32,12],[165,"How does dopamine act on the two pathways, and what follows its loss?","It excites the direct (D1) pathway and inhibits the indirect (D2) pathway, both favouring movement. Loss, as in Parkinson's, causes slowness and rigidity.",32,13],[165,"Which cells are lost first in Huntington's disease, and why does chorea result?","GABAergic medium spiny neurons of the indirect pathway, carrying D2 receptors and enkephalin. Losing the no-go route releases the thalamus and causes chorea.",32,14],[165,"What is the boxcar ventricles sign on brain imaging?","Caudate head atrophy in Huntington's disease flattens the wall of the frontal horns, making them look square.",32,15],[165,"How many CAG repeats give full penetrance in Huntington's disease?","40 or more CAG repeats.",32,16],[165,"Which nucleus is the commonest deep brain stimulation target in advanced Parkinson's disease?","The subthalamic nucleus, with benefit first reported by Limousin and colleagues in 1995.",32,17],[165,"What is Fahr's disease and what psychiatric features can it cause?","Primary familial brain calcification of the basal ganglia and dentate nuclei with normal calcium and parathyroid hormone. It can cause psychosis, mood change, dementia and parkinsonism.",32,18],[166,"A woman aged 76 with diabetes suddenly develops flinging movements of her left arm and leg. Where is the lesion?","The right subthalamic nucleus, usually a small lacunar infarct. This causes hemiballismus on the opposite side.",32,19],[166,"How can hemiballismus be distinguished clinically from Huntington's chorea?","Hemiballismus is sudden and one-sided from a subthalamic lesion. Huntington's chorea comes on slowly and affects both sides from caudate loss.",32,20],[169,"What asymmetry of the planum temporale did Geschwind and Levitsky find in 1968?","It was larger on the left in about 65% of brains, a difference present before birth that fits left-sided language.",33,1],[169,"Where is the planum temporale and what type of cortex is it?","It is auditory association cortex in the floor of the Sylvian fissure, just behind Heschl's gyrus.",33,2],[169,"Which structures lie in the medial temporal lobe?","The hippocampus and amygdala, with the parahippocampal gyrus alongside them.",33,3],[169,"What is the entorhinal cortex and why is it important in Alzheimer's disease?","It is the front of the parahippocampal gyrus and the gateway into the hippocampus. Braak showed Alzheimer's tangles appear here first.",33,4],[170,"A man aged 45 with epilepsy reports a smell of burning rubber before seizures. Where does this aura arise?","In the uncus of the medial temporal lobe, which contains smell cortex.",33,5],[170,"Which structures make up the hippocampal formation?","The dentate gyrus, the CA fields (cornu ammonis) and the subiculum.",33,6],[170,"Trace the trisynaptic circuit of the hippocampus.","Entorhinal cortex via the perforant path to the dentate gyrus, mossy fibres to CA3, Schaffer collaterals to CA1, then output to the subiculum and fornix.",33,7],[170,"Which two arteries provide the blood supply of the hippocampus?","The posterior cerebral and anterior choroidal arteries.",33,8],[170,"What did Scoville and Milner show with patient HM in 1957?","After bilateral medial temporal lobe removal he could not form new memories, showing the hippocampus is needed for new memory.",33,9],[170,"Which hippocampal field is most vulnerable to hypoxia?","CA1, which is also the main field lost in mesial temporal sclerosis.",33,10],[170,"Distinguish the input and output nuclei of the amygdala in fear learning.","The basolateral complex is the input side that learns a cue means danger. The central nucleus is the output that drives hypothalamic and brainstem fear responses.",33,11],[170,"What are the features of Kluver-Bucy syndrome and what can cause it in humans?","Tameness, mouthing of objects and hypersexuality after bilateral temporal damage. It can follow herpes simplex encephalitis.",33,12],[170,"What deficit did Adolphs find in a woman with bilateral amygdala calcification?","She could not recognise fear in facial expressions.",33,13],[170,"Where does adult neurogenesis occur in the human brain?","In the subgranular zone of the dentate gyrus and the wall of the lateral ventricle. Eriksson showed it in adult humans in 1998.",33,14],[170,"What factors reduce and increase adult hippocampal neurogenesis?","Chronic stress reduces it, while exercise such as running and antidepressants increase it.",33,15],[170,"What did Santarelli show in 2003 about antidepressants and neurogenesis?","Blocking hippocampal cell division with X-rays in mice abolished the anxiety-related effects of fluoxetine and imipramine.",33,16],[170,"What is the current status of evidence for adult human neurogenesis?","It is contested. In 2018 Sorrells found almost none, while Boldrini found it throughout ageing, possibly due to tissue handling and marker differences.",33,17],[170,"In which disorders is hippocampal volume reduced, and what did Gilbertson's twin study show?","PTSD, recurrent depression and schizophrenia. Gilbertson showed part of the small hippocampus in PTSD predates the trauma.",33,18],[170,"What is the commonest cause of temporal lobe epilepsy in adults and its MRI appearance?","Mesial temporal sclerosis, with cell loss in CA1 and the hilus, often after prolonged febrile seizures in infancy. MRI shows a small, bright hippocampus.",33,19],[170,"What psychosis did Slater and Beard describe in 1963 in epilepsy?","A schizophrenia-like interictal psychosis arising years after epilepsy onset, in clear consciousness, often with preserved warm affect.",33,20],[174,"During an awake craniotomy, stimulating cortex just in front of the central sulcus makes the opposite hand twitch. Which area is this?","The precentral gyrus, the primary motor cortex, whose layer V Betz cells give rise to the corticospinal tract.",34,1],[174,"Where is the supplementary motor area and what does it do?","On the medial frontal surface in front of the motor strip. It plans sequences of movement.",34,2],[174,"After a right frontal eye field stroke, which way do the eyes deviate?","Towards the lesion, to the right, away from the weak side. A brisk head turn still moves them because the brainstem is intact.",34,3],[174,"Which parts of the inferior frontal gyrus form Broca's area?","The pars opercularis and pars triangularis, usually of the left hemisphere.",34,4],[174,"What does the frontal aslant tract connect and what happens if it is cut?","It links the supplementary motor area to Broca's area. Damage slows speech initiation but repetition is preserved.",34,5],[174,"What proportion of human cerebral cortex is prefrontal?","About 30%.",34,6],[174,"What are the features of dorsolateral prefrontal damage and how are they tested?","Poor planning, poor working memory and perseveration with failure to shift set. Milner showed this with a card sorting test in 1963.",34,7],[175,"What are the features of orbitofrontal or ventromedial prefrontal damage?","Tactless, impulsive and disinhibited behaviour with poor risky decisions, often with normal IQ.",34,8],[175,"What did Bechara find using the Iowa gambling task in ventromedial prefrontal patients?","They kept choosing decks with big wins but bigger losses, and their skin conductance did not rise before risky choices.",34,9],[175,"What syndrome follows medial frontal damage, and what happens if both sides are affected?","Apathy, sparse speech and unconcerned incontinence. Bilateral damage, often from anterior cerebral artery strokes, causes akinetic mutism.",34,10],[175,"How does akinetic mutism differ from coma and locked-in syndrome?","The patient is awake and the eyes track, but there is no drive to move or speak. In locked-in syndrome the person wants to communicate and uses blinking.",34,11],[175,"Name the five frontal-subcortical loops described by Alexander and colleagues in 1986.","Motor, oculomotor, dorsolateral prefrontal, lateral orbitofrontal and anterior cingulate loops.",34,12],[175,"How can a caudate stroke mimic a frontal lobe syndrome?","Frontal circuits pass through the caudate, for example the lateral orbitofrontal loop through the ventromedial caudate, so a caudate lesion disrupts them with normal cortex.",34,13],[175,"Where is the cingulate gyrus and what is its role in the Papez circuit?","It arches over the corpus callosum in the limbic lobe. It is the cortical part of the Papez circuit, receiving anterior thalamic input and sending output via the cingulum.",34,14],[175,"What is the role of the anterior cingulate cortex in motivation?","It is a hub for drive that mobilises effort to obtain reward.",34,15],[175,"What is the error-related negativity and which region generates it?","A sharp brain wave within 100 ms of a mistake, generated by the dorsal anterior cingulate, which handles conflict and error detection.",34,16],[175,"Which cingulate region is overactive in treatment-resistant depression, and how has it been targeted?","The subgenual cingulate, Brodmann area 25. Mayberg targeted it with deep brain stimulation in 2005.",34,17],[176,"A man aged 66 has slow, effortful speech in short phrases but follows commands well after a stroke. Which area is damaged?","Broca's area. This is a non-fluent aphasia with good comprehension and insight into errors.",34,18],[178,"What are the three types of white matter fibre, with an example of each?","Commissural fibres cross the midline (corpus callosum), association fibres link areas within one hemisphere, and projection fibres run up and down (internal capsule).",35,1],[178,"Name the parts of the corpus callosum from front to back.","Rostrum, genu, body and splenium.",35,2],[178,"List the stations of the Papez circuit in order.","Hippocampus, fornix, mammillary bodies, mammillothalamic tract, anterior thalamus, cingulate gyrus, cingulum, parahippocampal gyrus, then back to hippocampus.",35,3],[178,"What was the Papez circuit originally proposed for, and what is it now thought to do?","Papez proposed it in 1937 as a circuit for emotion. It is now seen as the anatomy of declarative, episodic memory.",35,4],[179,"What is the blood supply of the corpus callosum?","Mostly the anterior cerebral artery. Only the splenium is supplied by the posterior cerebral artery.",35,5],[179,"What is the AC-PC line and why does it matter?","The line joining the anterior and posterior commissures, used by Talairach as the reference for his stereotactic atlas.",35,6],[179,"Where is the posterior commissure and what fibres does it carry?","Above the aqueduct and below the pineal. It carries fibres for upward gaze and the consensual light reflex.",35,7],[179,"A woman aged 35 had her corpus callosum cut for epilepsy. A key flashed to her left visual field cannot be named. Why?","The image reaches only the right hemisphere, which cannot speak. Her left hand can still pick out the key by touch.",35,8],[179,"What is alexia without agraphia and what lesion causes it?","The patient can write but cannot read, even their own writing. It follows a left occipital stroke plus splenium damage, as described by Dejerine in 1892.",35,9],[179,"What is the largest association bundle of the hemisphere and what does it link?","The superior longitudinal fasciculus, running from the frontal lobe above the insula to the parietal, temporal and occipital lobes.",35,10],[179,"What deficit follows damage to the arcuate fasciculus?","Conduction aphasia, with fluent speech and good comprehension but impaired repetition.",35,11],[179,"What does the uncinate fasciculus connect, and in which conditions is it weaker?","The temporal pole and amygdala to the orbitofrontal and inferior frontal cortex. It is weaker in schizophrenia, psychopathy and frontotemporal dementia.",35,12],[179,"What does the inferior longitudinal fasciculus carry and what follows damage?","The ventral visual stream from occipital to anterior temporal lobe. Damage causes visual agnosia or prosopagnosia.",35,13],[179,"A man aged 55 with alcohol dependence has severe new learning impairment. Which Papez structures are damaged by thiamine deficiency?","The mammillary bodies and the mediodorsal and anterior thalamus, as in Korsakoff syndrome.",35,14],[179,"How can a third ventricle tumour cause amnesia?","A tumour in the roof of the third ventricle can cut the fornix, breaking the Papez circuit.",35,15],[179,"What does the medial forebrain bundle connect and what did Olds and Milner discover?","It runs through the lateral hypothalamus linking the ventral tegmental area to the nucleus accumbens. In 1954 Olds and Milner showed rats would self-stimulate this reward pathway.",35,16],[179,"Which tract carries hippocampal output to the mammillary bodies, and which continues to the thalamus?","The fornix carries output to the mammillary bodies. The mammillothalamic tract then runs to the anterior thalamus.",35,17],[179,"Where does the cingulum run in the Papez circuit?","Within the cingulate gyrus, carrying signals back to the parahippocampal gyrus and hippocampus.",35,18],[182,"Match the four dopamine pathways to their roles in antipsychotic effects and side effects.","Mesolimbic: positive symptoms. Nigrostriatal: extrapyramidal effects. Mesocortical: negative and cognitive symptoms. Tuberoinfundibular: prolactin control.",36,1],[182,"Why do dopamine blockers relieve nausea, and which pathway is not responsible?","They block D2 receptors in the chemoreceptor trigger zone of the brainstem, not the mesocortical pathway.",36,2],[183,"Who first mapped the brain's monoamine cell groups, and how?","Dahlstrom and Fuxe in 1964, using a fluorescence method that made monoamine cells glow.",36,3],[183,"Where does the nigrostriatal pathway start and end, and what is its function?","From the substantia nigra pars compacta to the dorsal striatum. It supports smooth movement.",36,4],[183,"Where is the ventral tegmental area and which pathways does it give rise to?","In the midbrain, medial to the substantia nigra. It gives rise to the mesolimbic and mesocortical pathways.",36,5],[183,"How is the mesocortical pathway linked to symptoms of schizophrenia?","It runs from the VTA to the prefrontal cortex, and underactivity there is linked to negative and cognitive symptoms such as poor working memory.",36,6],[183,"A woman aged 28 on risperidone develops galactorrhoea and amenorrhoea. Which pathway explains this?","D2 blockade in the tuberoinfundibular pathway, which runs from the arcuate nucleus to the median eminence and normally inhibits prolactin.",36,7],[183,"Where is the locus coeruleus and what does it produce?","A small dark nucleus in the upper pons beneath the fourth ventricle. It produces most of the brain's noradrenaline, projecting via the dorsal noradrenergic bundle.",36,8],[183,"How does locus coeruleus firing vary across the sleep-wake cycle?","It fires most during alert waking and stress, slows in deep sleep and is silent in REM sleep.",36,9],[183,"In which neurodegenerative diseases is the locus coeruleus lost?","Parkinson's disease and Alzheimer's disease.",36,10],[183,"Where is all brain histamine produced, and what is its main role?","Only in the tuberomammillary nucleus of the posterior hypothalamus. It promotes wakefulness.",36,11],[183,"Distinguish the projections of the dorsal and median raphe nuclei.","The dorsal raphe projects to the cortex and striatum. The median raphe projects to the hippocampus and septum.",36,12],[183,"Why might SSRIs take several weeks to work, according to raphe physiology?","Dorsal raphe cells carry 5-HT1A autoreceptors that take weeks to desensitise before serotonin output rises.",36,13],[183,"What does the medial septum and diagonal band of Broca project to, and what does it do?","It sends acetylcholine through the fornix to the hippocampus, pacing the hippocampal theta rhythm.",36,14],[183,"Which nuclei form the brainstem cholinergic pathway and what is their role?","The pedunculopontine and laterodorsal tegmental nuclei at the pons-midbrain junction. They project to the thalamus, fire in waking and REM, and help trigger REM sleep.",36,15],[183,"What transmitter does the corticofugal system use, and where does it project?","Glutamate, from cortical pyramidal cells to the striatum, thalamus, brainstem and spinal cord.",36,16],[183,"Why is there no discrete ascending GABA pathway like the monoamine systems?","GABA acts mainly through local interneurons. The few long GABA projections come from striatal, pallidal and cerebellar Purkinje cells.",36,17],[184,"What striatal D2 occupancy levels are linked to antipsychotic effect, raised prolactin and extrapyramidal effects?","About 65% for antipsychotic effect, about 72% for raised prolactin and about 78% for extrapyramidal side effects.",36,18],[184,"A woman aged 79 with Alzheimer's disease starts donepezil. Which nucleus loss underlies the cholinergic hypothesis?","The nucleus basalis of Meynert, which projects acetylcholine to the neocortex. Its loss lowers cortical choline acetyltransferase, as Whitehouse showed.",36,19],[187,"What happens after bilateral lesions of the ventromedial hypothalamus versus the lateral hypothalamus in rats?","Ventromedial lesions cause hyperphagia and obesity (satiety centre lost). Lateral lesions cause aphagia and weight loss (feeding centre lost).",37,1],[187,"Why is the arcuate nucleus well placed to sense hunger signals?","It lies beside a leaky part of the blood-brain barrier, so it can read hormones from the gut and fat directly.",37,2],[187,"Which arcuate neurons drive eating and which stop it?","NPY/AgRP neurons drive eating, while POMC neurons stop it.",37,3],[188,"How do alpha-MSH and AgRP act on the melanocortin 4 receptor?","Alpha-MSH from POMC neurons activates MC4R in the paraventricular nucleus to stop eating. AgRP blocks MC4R, increasing appetite.",37,4],[188,"Where is leptin made and what does it do to the arcuate neurons?","In fat cells. It excites POMC neurons and inhibits NPY/AgRP neurons, so appetite falls.",37,5],[188,"A boy aged 3 has constant hunger and severe obesity since infancy with undetectable leptin. What is the treatment?","This is congenital leptin deficiency, as described by Montague. Recombinant leptin injections reduce hunger within days.",37,6],[188,"What is meant by leptin resistance in obesity?","Most obese people have high leptin levels but respond poorly to it, so the brain ignores the signal of stored fuel.",37,7],[188,"Where is ghrelin made and how does its level change around meals?","In the stomach. It rises before each meal and falls after eating, and it activates NPY/AgRP neurons.",37,8],[188,"How do cholecystokinin and peptide YY differ from leptin in appetite control?","CCK and peptide YY are gut signals that end a single meal, while leptin acts over weeks to reflect fat stores.",37,9],[188,"Which brain systems drive hedonic eating?","Dopamine in the nucleus accumbens, opioid sites and value signals in the orbitofrontal cortex.",37,10],[188,"What is sensory-specific satiety, and what does it explain?","The pleasantness of a food falls as it is eaten while a new food keeps its value, as Rolls showed in 1981. It explains room for pudding.",37,11],[188,"What biological profile goes with increased appetite and weight gain in depression?","Immunometabolic depression, with raised CRP and interleukin-6, higher leptin, higher BMI and a stronger ventral striatal reward response to food.",37,12],[188,"What brain and hormone changes go with reduced appetite in depression?","Reduced insula activity in response to food and greater HPA axis (stress hormone) activity.",37,13],[188,"A woman aged 19 with anorexia nervosa has amenorrhoea. What hormone changes are expected?","Low leptin, high ghrelin, low T3, raised cortisol and low LH and FSH. Most reverse with weight restoration.",37,14],[188,"By what receptor actions do olanzapine and clozapine cause weight gain?","Blockade of histamine H1 and serotonin 5-HT2C receptors in the hypothalamus, which increases hunger.",37,15],[188,"Which structures sense blood osmolality to drive thirst, and why can they do this?","The OVLT and subfornical organ in the lamina terminalis. They lack a blood-brain barrier. Angiotensin II also acts on the subfornical organ when blood volume is low.",37,16],[188,"Where is vasopressin made and released, and how does it act on the kidney?","Made in the supraoptic and paraventricular nuclei, released from the posterior pituitary. It inserts aquaporin-2 channels so the kidney keeps water.",37,17],[188,"A man aged 50 on a long-stay schizophrenia ward drinks excessively and has a seizure. What is the likely problem and mechanism?","Primary polydipsia with hyponatraemia, often sodium below 125 mmol/L. Goldman showed a reset osmostat, with vasopressin released at a lower osmolality.",37,18],[188,"How common is primary polydipsia in long-stay schizophrenia, and at what osmolality does vasopressin normally switch on?","Up to 20% of long-stay patients. Vasopressin release normally starts at about 280 to 285 mOsm/kg.",37,19],[188,"How does lithium cause polyuria and thirst?","It blunts the kidney's response to vasopressin, causing nephrogenic diabetes insipidus with dilute urine.",37,20],[192,"A man aged 45 with a hypothalamic tumour sleeps in short bouts across 24 hours. Which nucleus is damaged?","The suprachiasmatic nucleus, the master circadian clock. Without it, sleep loses its daily pattern.",38,1],[192,"What are the two processes in Borbely's 1982 model of sleep regulation?","Process S, homeostatic sleep pressure that builds during waking, and Process C, the circadian rhythm set by the body clock.",38,2],[192,"Why is it hard to nap in the early evening even when tired?","The circadian clock sends its strongest waking signal in the early evening, before it falls at bedtime.",38,3],[192,"Which substance carries much of Process S, and how does caffeine affect it?","Adenosine, which builds during waking and acts on A1 and A2A receptors. Caffeine blocks these receptors, masking sleep pressure without clearing it.",38,4],[193,"Which clock genes drive the suprachiasmatic nucleus, and what is its intrinsic period?","CLOCK, BMAL1, PER and CRY, giving an intrinsic period of about 24.2 hours.",38,5],[193,"How is the suprachiasmatic nucleus reset each day?","By morning light via melanopsin-containing retinal ganglion cells and the retinohypothalamic tract.",38,6],[193,"When does pineal melatonin secretion peak?","At about 2 to 4 am, timed by the suprachiasmatic nucleus.",38,7],[193,"What is the role of the ventrolateral preoptic nucleus in sleep?","It fires during sleep and releases GABA and galanin to inhibit arousal centres. Lesions cause lasting insomnia.",38,8],[193,"What is the flip-flop switch model of sleep and waking?","The VLPO and arousal centres inhibit each other, so the brain snaps between sleep and waking. Orexin stabilises the switch, and its loss causes narcolepsy.",38,9],[193,"Which cells switch REM sleep on and which fall silent in REM?","Cholinergic cells of the laterodorsal and pedunculopontine tegmental nuclei switch REM on. Locus coeruleus and raphe cells are REM-off and fall silent.",38,10],[193,"What are normal adult sleep onset latency and REM latency?","Sleep onset takes 15 to 20 minutes, and the first REM period comes about 90 minutes later.",38,11],[193,"What proportion of sleep is REM in adults and in newborns, and how often do REM awakenings give dreams?","About 20 to 25% in adults and about 50% in term newborns. About 80% of REM awakenings give vivid dream reports.",38,12],[193,"What is the glymphatic system and how does sleep affect it?","A system that flushes waste along blood vessels. In sleeping mice the space between cells grew by about 60% and amyloid was cleared about twice as fast.",38,13],[193,"What changes in recovery sleep after total sleep deprivation?","Slow-wave sleep and delta power rebound first. The brain repays depth rather than lost hours.",38,14],[193,"What did Van Dongen show about chronic partial sleep restriction?","Six hours a night for two weeks impaired attention as much as two nights without sleep, yet people felt only slightly sleepy.",38,15],[193,"What sleep EEG changes are typical of depression?","Short REM latency, increased REM sleep and reduced slow-wave sleep.",38,16],[193,"A woman aged 40 with depression improves after one night of total sleep deprivation. What usually happens next?","About 40 to 60% respond, but most relapse after recovery sleep.",38,17],[193,"How is sleep linked to bipolar disorder and later depression?","Sleep loss can trigger mania and reduced need for sleep is an early warning sign. Insomnia roughly doubles later depression risk.",38,18],[193,"What mean sleep latency on the multiple sleep latency test suggests narcolepsy?","A mean sleep latency of 8 minutes or less.",38,19],[194,"A man aged 45, totally blind since childhood, finds his sleep drifts later each day. What is the cause?","The suprachiasmatic nucleus receives no light input, so it free-runs at its own period (non-24-hour disorder). Melatonin can help.",38,20],[197,"A man aged 42 with untreated first-episode depression reports low libido and arousal problems. How common is this and why?","Sexual dysfunction affects about 40 to 50% of people with untreated depression, from reduced dopaminergic reward drive, anhedonia and stress hormones.",39,1],[197,"Which neurotransmitters act as the accelerator and the brake of the sexual response?","Dopamine drives desire and arousal. Serotonin inhibits desire, arousal and ejaculation.",39,2],[198,"Why should a baseline sexual history be taken before starting an antidepressant?","Sexual problems are common in depression itself, so without a baseline, later problems may be wrongly blamed on treatment.",39,3],[198,"What is the role of the medial preoptic area in male sexual behaviour?","It integrates male sexual behaviour. Lesions in male rats stop mounting and mating though interest in females remains, and dopamine is released there during mating.",39,4],[198,"What is the sexually dimorphic nucleus?","A nucleus in the rat medial preoptic area, several times larger in males, whose size is shaped by hormones around birth, as Gorski showed.",39,5],[198,"Which hypothalamic area controls female receptive sexual behaviour in rats?","The ventromedial hypothalamus, which controls the lordosis posture.",39,6],[198,"Where do women make testosterone, and what changes its levels?","In the ovaries and adrenal glands. Levels fall with age and after removal of the ovaries.",39,7],[198,"A woman aged 54 has distressing low desire after the menopause despite HRT. What does NICE NG23 suggest?","Considering testosterone supplementation, usually given through the skin, since androgens support desire in women.",39,8],[198,"What is the role of oestrogen in female sexual function?","It helps vaginal comfort but is not the main hormone driving desire.",39,9],[198,"How does high prolactin reduce sexual desire?","It suppresses GnRH pulses, so LH, FSH and sex hormones fall.",39,10],[198,"How do SSRIs cause sexual dysfunction, and what problems are typical?","They raise serotonin, which brakes the sexual response, causing low desire, delayed orgasm and delayed ejaculation.",39,11],[198,"What stepped hormonal approach does WFSBP guidance recommend for men at high risk from a paraphilic disorder?","Psychological treatment and SSRIs first, then cyproterone acetate, then a GnRH agonist such as leuprorelin or triptorelin for the highest risk.",39,12],[198,"How does cyproterone acetate act in the treatment of paraphilia?","It blocks androgen receptors, reducing the effect of testosterone.",39,13],[198,"Why is cyproterone given when a GnRH agonist is started?","GnRH agonists first stimulate LH release, causing a testosterone flare for about 1 to 2 weeks before levels fall. Cyproterone covers the flare.",39,14],[198,"What monitoring is needed with hormonal treatment of paraphilia?","Informed consent plus checks of bone density, mood and metabolic health.",39,15],[198,"What did Zhou and colleagues report in 1995 about the brains of trans women?","In six trans women post mortem, the central bed nucleus of the stria terminalis (BSTc) was female-typical in size.",39,16],[198,"What are the main limitations of brain studies of gender identity?","Samples were tiny and most donors had taken hormones, which Hulshoff Pol showed can themselves change brain volume.",39,17],[198,"Is there a brain scan or gene test for gender identity, and how is it assessed?","No. Twin studies are small and no gene is found, so evidence is inconclusive. Assessment rests on the person's own account.",39,18],[198,"Where does ICD-11 classify gender incongruence?","In a chapter on conditions related to sexual health, not among mental disorders.",39,19],[199,"A woman aged 31 on amisulpride has amenorrhoea, galactorrhoea and low libido. Which pathway explains this?","D2 blockade in the tuberoinfundibular pathway removes dopamine's brake on prolactin, causing hyperprolactinaemia. Amisulpride and risperidone raise prolactin most.",39,20],[202,"How does reactive aggression differ from instrumental aggression?","Reactive aggression is hot and provoked, a threat response. Instrumental aggression is cold and planned to gain something, and is typical of psychopathy.",40,1],[202,"Which brain structures drive reactive aggression as a threat response?","The amygdala, the hypothalamus and the periaqueductal grey.",40,2],[202,"Which prefrontal regions act as the brakes on reactive aggression?","The orbitofrontal cortex and ventromedial prefrontal cortex, which weigh context and likely consequences before acting.",40,3],[202,"What did Coccaro find when people with intermittent explosive disorder viewed angry faces?","Exaggerated amygdala responses with weak orbitofrontal responses, fitting a loud alarm with weak brakes.",40,4],[202,"What change in behaviour typically follows orbitofrontal injury, as in Phineas Gage?","The person becomes quick-tempered and disinhibited, with reactive outbursts, rather than becoming a cold planner.",40,5],[203,"What did Linnoila report in 1983 about CSF 5-HIAA in violent offenders?","5-HIAA, the main serotonin metabolite, was much lower in men with impulsive violence than in those whose violence was planned.",40,6],[203,"Apart from impulsive violence, which behaviour is classically linked with low CSF 5-HIAA?","Violent suicide attempts.",40,7],[203,"Why do SSRIs and lithium have some evidence in impulsive but not planned aggression?","Low serotonin seems to weaken prefrontal control over the amygdala, which drives impulsive rather than premeditated violence.",40,8],[203,"How does the amygdala respond to fearful faces in young people with callous-unemotional traits?","It responds less than normal (Marsh). Blair argues that others' distress then fails to punish harm, so empathy is learned poorly.",40,9],[203,"What is the best-replicated physiological marker of antisocial behaviour in young people?","A low resting heart rate, explained by fearlessness or by stimulation seeking in an under-aroused child.",40,10],[203,"Is basal cortisol typically high or low in persistent antisocial youths?","Low, not high, fitting the picture of under-arousal.",40,11],[203,"What did Brunner find in a Dutch family with impulsive aggression?","The affected men lacked monoamine oxidase A, the enzyme that breaks down serotonin, noradrenaline and dopamine.",40,12],[203,"What did Caspi's 2002 New Zealand cohort study show about MAOA?","Maltreated boys with the low-activity MAOA allele had the highest rates of antisocial behaviour, showing a gene-environment interaction.",40,13],[203,"Which Caspi study is often confused with the MAOA study, and what did it examine?","The 2003 study, which looked at the serotonin transporter gene, life stress and depression.",40,14],[203,"How is testosterone related to aggression?","It has a small but real link with dominance and aggression and tends to raise amygdala reactivity to threat. High doses made a few men irritable or hypomanic.",40,15],[203,"According to Fazel, how much is the risk of violence raised in schizophrenia without substance misuse?","The odds are about 2 to 3 times those of the general population.",40,16],[203,"How does substance misuse change the risk of violence in schizophrenia?","It raises the odds to about 8 to 9 times, close to the figure for substance misuse alone, so misuse is the main amplifier.",40,17],[203,"What share of violent crime is committed by people with schizophrenia, and how often are they victims?","They commit only a small share of violent crime and are more often victims than perpetrators.",40,18],[204,"A man aged 38 has a frontal head injury, normal IQ, crude jokes and rages over slights. Which area is damaged?","The orbitofrontal cortex. The brakes on the amygdala fail, giving disinhibition and reactive rage with intelligence spared.",40,19],[206,"What is the difference between nociception and pain?","Nociception is nerve signalling of tissue damage. Pain is the unpleasant experience the brain builds from those signals, so the two can come apart.",41,1],[206,"Which fibres carry sharp, well-localised first pain, and how fast do they conduct?","Thinly myelinated A-delta fibres, at about 5 to 30 m/s.",41,2],[206,"A man aged 30 stubs his toe; a dull, spreading ache follows the sharp pain. Which fibres carry it?","Unmyelinated C fibres, which conduct slowly at about 0.5 to 2 m/s, so the ache arrives a second later.",41,3],[206,"Which fibres carry touch, and which carry proprioception and motor output?","Large myelinated A-beta fibres carry touch and vibration. A-alpha fibres carry proprioception and motor output.",41,4],[206,"Where do C fibres end in the dorsal horn, and what do they release?","In lamina II, the substantia gelatinosa, where they release glutamate and substance P.",41,5],[206,"In which dorsal horn laminae do A-delta fibres terminate?","Laminae I and V.",41,6],[206,"Where do second-order pain fibres cross, and in which tract do they ascend?","They cross within one or two spinal segments and ascend in the opposite spinothalamic tract.",41,7],[206,"What is the effect of loss-of-function mutations in SCN9A?","Loss of the Nav1.7 sodium channel causes congenital inability to feel pain, with painless injuries, and also loss of smell.",41,8],[206,"What did Melzack and Wall propose in their 1965 gate control theory?","Small pain fibres open a gate in the substantia gelatinosa, large A-beta fibres close it via inhibitory interneurons, and the brain also sets the gate.",41,9],[207,"Why does rubbing a bruise or using a TENS machine ease pain?","It activates A-beta touch fibres, which excite inhibitory interneurons and partly close the spinal pain gate.",41,10],[207,"What did Reynolds show in 1969 by stimulating the periaqueductal grey in rats?","The rats tolerated abdominal surgery without anaesthetic. The analgesia was later shown to be partly reversed by naloxone.",41,11],[207,"Through which two relays does the periaqueductal grey control pain descending to the spinal cord?","The rostral ventromedial medulla, using serotonin from nucleus raphe magnus, and the locus coeruleus, using noradrenaline.",41,12],[207,"What did Levine show about placebo analgesia after dental extraction?","Saline described as a painkiller gave relief that hidden naloxone removed, so placebo analgesia is largely opioid-driven.",41,13],[207,"Which transmitter mediates the nocebo effect, and what does proglumide do?","Cholecystokinin mediates nocebo. Proglumide, a cholecystokinin blocker, strengthens placebo relief.",41,14],[207,"What is wind-up and which receptor does it depend on?","Growing dorsal horn responses to repeated C fibre stimulation at about 1 Hz. It depends on NMDA receptors losing their magnesium block, not AMPA receptors.",41,15],[207,"How does allodynia differ from hyperalgesia?","Allodynia is pain from a normally painless stimulus. Hyperalgesia is increased pain from a stimulus that is already painful.",41,16],[207,"What is central sensitisation, and which type of pain does it underlie?","A lasting turning-up of spinal pain signalling, described by Woolf. It underlies nociplastic pain such as fibromyalgia.",41,17],[207,"Which cortical areas code the location and intensity of pain versus its unpleasantness?","Primary somatosensory cortex codes location and intensity. The anterior cingulate cortex and insula code unpleasantness, as Rainville showed with hypnosis.",41,18],[207,"How common is pain in depression, and why do the two worsen each other?","About two-thirds of people with depression report pain. Both share weak descending serotonin and noradrenaline control.",41,19],[208,"A woman aged 60 with cancer pain has a cortical lesion and still feels pain but is untroubled. Which area?","The anterior cingulate cortex. Cingulotomy removes the distress of pain while location and intensity are still perceived.",41,20],[210,"A boy aged 12 with motor and vocal tics improves on a D2 antagonist. What abnormality underlies this?","Dopaminergic overactivity in the striatum, as in Tourette's syndrome.",42,1],[210,"Which drugs reduce tics in Tourette's syndrome and which can provoke them?","D2 antagonists and tetrabenazine reduce tics, and alpha-2 agonists such as clonidine help. Dopamine agonists and stimulants can provoke tics.",42,2],[210,"What are the signs of an upper motor neuron lesion?","Spasticity that rises with the speed of stretch, brisk reflexes and an upgoing plantar, with little wasting.",42,3],[210,"What are the signs of a lower motor neuron lesion?","Wasting, fasciculation, reduced tone and reduced or absent reflexes.",42,4],[210,"Which movement signs point to basal ganglia disease?","Slowness that shrinks with repetition, rigidity, rest tremor and micrographia, handwriting that gets smaller along the line.",42,5],[210,"What does cerebellar disease do to movement, and on which side are signs found?","It gives large, poorly timed movements, with signs on the same side as the lesion.",42,6],[210,"Which dopamine receptors mark the direct and indirect basal ganglia pathways, and what does each do?","The direct pathway has D1 receptors and releases movement. The indirect pathway has D2 receptors and holds movement back.",42,7],[211,"According to Wolpert, what does the cerebellum compute, and why can we not tickle ourselves?","It builds forward models that predict the sensory result of our own movements, so the expected touch is cancelled.",42,8],[211,"Where do climbing fibres come from and what is their role in cerebellar learning?","From the inferior olive. They carry error signals that weaken parallel fibre synapses onto GABAergic Purkinje cells, the only cerebellar cortical output.",42,9],[211,"What D2 occupancy thresholds did Kapur link to response, prolactin rise and EPSE?","Response at about 65%, raised prolactin above about 72% and extrapyramidal side-effects above about 78%.",42,10],[211,"Why does D2 blockade in the striatum cause extrapyramidal side-effects?","Dopamine normally brakes cholinergic interneurons. Blocking it releases them, so acetylcholine rises and drives dystonia and parkinsonism.",42,11],[211,"When do acute dystonia and drug-induced parkinsonism appear, and what treats them?","Acute dystonia within hours to days and parkinsonism over weeks. Anticholinergics such as procyclidine restore the balance.",42,12],[211,"How is antipsychotic-induced akathisia treated, and do anticholinergics help?","Akathisia, an inner restlessness, responds poorly to anticholinergics, so propranolol is used instead.",42,13],[211,"What causes tardive dyskinesia, and what is the effect of anticholinergics?","Long D2 blockade makes receptors multiply and become supersensitive. Anticholinergics make tardive dyskinesia worse.",42,14],[211,"What is rabbit syndrome and how does it respond to anticholinergics?","A late, fast lip tremor of about 5 Hz that spares the tongue. It is parkinsonian, so it improves with anticholinergics.",42,15],[211,"What is ideomotor apraxia and where is the lesion?","Inability to mime an action such as combing hair on command, while using the real object well. The lesion is in the left parietal lobe.",42,16],[211,"What is ideational apraxia and where is it often seen?","Failure to put the steps of a task in order, such as making tea. It is often seen in dementia.",42,17],[211,"Where are the lesions in constructional, dressing and buccofacial apraxia?","Constructional and dressing apraxia are linked to the right parietal lobe. Buccofacial apraxia lies near Broca's area.",42,18],[212,"A woman aged 50 has slow, irregular rapid alternating movements of the left hand. Where is the lesion?","In the left cerebellar hemisphere, because dysdiadochokinesia appears on the same side as the lesion.",42,19],[212,"Which part of the cerebellum does alcohol damage first, and what does this cause?","The anterior vermis, causing truncal and broad-based gait ataxia.",42,20],[214,"What rule did Donald Hebb propose in 1949?","When one cell repeatedly helps to fire another, the link between them strengthens: cells that fire together wire together.",43,1],[214,"How is learning defined, and how does the brain store it?","Learning is a lasting change in behaviour that comes from experience. The brain stores it by changing synaptic strength.",43,2],[214,"What did Bliss and Lømo report in 1973?","Brief strong stimulation of a rabbit hippocampal pathway made its synapses stronger for hours or days, which is long-term potentiation.",43,3],[214,"Why does the NMDA receptor allow long-term potentiation to follow Hebb's rule?","It opens only when glutamate arrives and the receiving cell is already depolarised, so it detects two events at once.",43,4],[215,"What did Sherrington, Cajal, Pavlov and Skinner contribute, as distinct from Hebb?","Sherrington named the synapse, Cajal set out the neuron doctrine, and Pavlov and Skinner studied conditioning in behaviour.",43,5],[215,"What kind of feedback defines supervised learning?","A teacher gives a detailed error signal, saying how far and in which direction the response was wrong.",43,6],[215,"What kind of feedback defines reinforcement learning?","Only a single score saying whether the outcome was better or worse than expected.",43,7],[215,"In computational terms, what is unsupervised learning and what does the learner do?","Learning with no feedback, where the learner simply finds regular patterns in its input.",43,8],[215,"In Doya's 2000 model, which brain system carries out each type of learning?","The cerebellum does supervised learning, the basal ganglia do reinforcement learning and the cerebral cortex does unsupervised learning.",43,9],[215,"What signal do cerebellar climbing fibres carry in supervised learning?","A detailed error signal from the inferior olive, as first suggested by Marr.",43,10],[215,"What did McCormick and Thompson show about the conditioned eyeblink in rabbits?","It needs the cerebellar interpositus nucleus. A lesion there abolished the learned blink but spared the reflex blink, and the hippocampus was not needed.",43,11],[215,"In eyeblink conditioning, which cerebellar inputs carry the tone and the air puff?","The tone arrives on mossy fibres and the air puff on climbing fibres.",43,12],[215,"In fear conditioning, which amygdala nucleus stores the tone and shock link, and which expresses fear?","The lateral nucleus stores the link (LeDoux). The central nucleus sends the output.",43,13],[215,"Through which targets does the central amygdala produce the signs of conditioned fear?","Freezing via the periaqueductal grey, heart rate change via the hypothalamus and startle via the brainstem.",43,14],[215,"What does the Rescorla-Wagner model of 1972 state?","On each trial the change in associative strength equals the prediction error, what happened minus what was expected.",43,15],[215,"How does the Rescorla-Wagner model explain blocking?","Once one cue fully predicts the outcome, the prediction error is zero, so an added cue learns nothing.",43,16],[215,"What did Corlett and colleagues find in first-episode psychosis during a learning task?","Right prefrontal cortex signalled errors to expected events, and the more disrupted this was, the stronger the delusions.",43,17],[216,"Which cells send the striatum a single better-or-worse prediction error signal for reinforcement learning?","Dopamine neurons of the ventral tegmental area, as Schultz showed.",43,18],[218,"How does a goal-directed action differ from a habit?","A goal-directed action is done because its result is wanted now. A habit is triggered by a cue, whatever the result is now worth.",44,1],[218,"What did Dickinson's outcome devaluation experiments in rats show?","After the sugar lost its value, briefly trained rats stopped pressing, but overtrained rats kept pressing because it had become a habit.",44,2],[218,"A man aged 50 who changed jobs twice finds himself parked at his old office. Which structure controls this?","The dorsolateral striatum, the putamen, which takes over control of overtrained habits.",44,3],[218,"What happened to briefly trained rats after a dorsomedial striatum lesion (Yin and Knowlton)?","They behaved like overtrained rats and kept pressing after the reward was devalued, so they became more habitual.",44,4],[219,"What is the effect of a dorsolateral striatum lesion on habit formation in rats?","It prevents habit, so behaviour stays goal-directed even after long training.",44,5],[219,"Which human structures correspond to goal-directed and habitual control, and how does control shift?","The caudate supports goals and the putamen supports habit. With practice control moves from the caudate prefrontal loop to the putamen sensorimotor loop.",44,6],[219,"What role does the ventral striatum play in habits, and does it store them?","Reward value enters through the ventral striatum, but it does not store habits, and neither do the ventral pallidum or subthalamic nucleus.",44,7],[219,"What circuit is linked to obsessive-compulsive disorder?","A cortico-striato-thalamo-cortical loop running from cortex to striatum to thalamus and back to cortex.",44,8],[219,"Which cortical areas drive the OCD loop?","The orbitofrontal cortex and the anterior cingulate cortex, which drive the caudate.",44,9],[219,"Through which structure does the caudate act on the thalamus in the OCD loop, and what is it?","The lentiform nucleus, which is the putamen and globus pallidus together.",44,10],[219,"What do PET scans show in OCD?","High glucose use in the orbitofrontal cortex and caudate, rising further when symptoms are provoked.",44,11],[219,"What did Baxter find in OCD patients scanned before and after ten weeks of treatment?","Responders to fluoxetine and responders to exposure and response prevention both showed falling right caudate metabolism.",44,12],[219,"What did Gillan's 2011 slips of action study show in OCD?","People with OCD kept responding for a devalued outcome more than controls, suggesting a shift from goal-directed control towards habit.",44,13],[219,"What is the deep brain stimulation target in very severe OCD?","The ventral internal capsule and nearby ventral striatum, aiming to break the loop.",44,14],[219,"Which structures are wrongly placed in the OCD loop by candidates?","The cerebellum and red nucleus. The loop runs through the caudate and lentiform nucleus instead.",44,15],[220,"A woman aged 45 makes two coffees on autopilot though her partner left a month ago. Which structure?","The dorsolateral striatum (putamen), which runs well-practised routines regardless of current value.",44,16],[222,"What did Olds and Milner discover in 1954?","Rats pressed a lever again and again to stimulate certain brain sites, revealing a reward system.",45,1],[222,"Where do the dopamine cells of the mesolimbic pathway arise, and where do they project?","From the ventral tegmental area of the midbrain to the nucleus accumbens.",45,2],[222,"Where is the nucleus accumbens located?","It is the largest part of the ventral striatum, where the caudate and putamen meet below the internal capsule.",45,3],[222,"What did Di Chiara and Imperato show in 1988 about drugs of misuse?","Drugs people misuse raise dopamine in the nucleus accumbens.",45,4],[222,"How do stimulants differ from opioids and alcohol in raising accumbens dopamine?","Stimulants act on the dopamine transporter. Opioids and alcohol act indirectly by freeing VTA cells from GABA control.",45,5],[223,"In Schultz's monkey studies, how did dopamine cells respond to unexpected juice?","They fired a burst of activity.",45,6],[223,"After a light reliably predicts juice, when do dopamine cells burst?","To the light that predicts the juice, with no change to the juice itself.",45,7],[223,"What happens to dopamine cell firing when an expected reward is withheld?","Firing dips below baseline at the time the reward was due.",45,8],[223,"What do midbrain dopamine neurons signal, according to Schultz?","Reward prediction error, the gap between expected and actual reward, not simply pleasure, novelty or movement.",45,9],[223,"How did Berridge and Robinson distinguish wanting from liking?","Wanting, or incentive salience, is the pull to seek a reward. Liking is the pleasure when it arrives.",45,10],[223,"What happened to rats with almost no forebrain dopamine when given sugar?","They still showed liking by licking their lips but would not work for it, so dopamine drives wanting.",45,11],[223,"Which transmitter system mediates liking of a reward, and where in the brain?","Opioids acting in hedonic hotspots, such as a small area in the accumbens shell.",45,12],[223,"What is incentive sensitisation in addiction?","Repeated drug use makes wanting grow while liking stays flat or falls.",45,13],[223,"What did Pizzagalli find in unmedicated depression on a money reward task?","The nucleus accumbens and caudate responded weakly to winning, linked to anhedonia.",45,14],[223,"What is Kapur's 2003 aberrant salience model of psychosis?","Dopamine is released at the wrong times, so ordinary things feel charged with meaning, and delusions are attempts to explain this.",45,15],[223,"Under the aberrant salience model, why do delusions fade slowly with antipsychotics?","Antipsychotics dampen salience rather than erase beliefs, so delusions fade gradually instead of vanishing.",45,16],[223,"How do the dopamine targets of the VTA and substantia nigra differ?","The VTA mainly feeds the nucleus accumbens, while the substantia nigra mainly feeds the dorsal striatum.",45,17],[224,"A woman aged 40 with depression shows blunted ventral striatal response to winning money. Which structure receives VTA dopamine?","The nucleus accumbens, the main target of the mesolimbic pathway.",45,18],[226,"A woman aged 35 with depression has anhedonia. What is the most consistent fMRI finding on reward tasks?","A blunted ventral striatal response to reward, both in anticipation and receipt, tracking anhedonia severity.",46,1],[226,"Where is the amygdala, and what two routes bring it sensory information?","In the medial temporal lobe. It gets a fast, rough signal from the thalamus and a slower, detailed one from the cortex.",46,2],[226,"What did Adolphs find in patient S.M. with Urbach-Wiethe disease?","With both amygdalae calcified, she could not recognise fear in faces though she knew who people were, and showed little fear.",46,3],[227,"What brain pattern accompanies successful reappraisal of a distressing image?","Increased lateral prefrontal activity with reduced amygdala activity, as Ochsner and Gross showed.",46,4],[227,"Does fear extinction erase the original fear memory?","No. It adds a new safe memory on top, and the original fear memory remains.",46,5],[227,"Which region holds fear extinction memory in humans, and how does it behave in PTSD?","The ventromedial prefrontal cortex, which calms the amygdala. People with PTSD show weak activity there.",46,6],[227,"How does D-cycloserine help exposure therapy?","As a partial agonist at the NMDA glycine site it strengthens extinction learning, though later trials found smaller benefits.",46,7],[227,"What blood flow pattern did Mayberg find in depression?","An overactive subgenual anterior cingulate (area 25) and an underactive dorsolateral prefrontal cortex, reversing with recovery.",46,8],[227,"Which treatment developed from Mayberg's findings in depression?","Deep brain stimulation of the white matter near the subgenual cingulate, area 25.",46,9],[227,"What amygdala and prefrontal pattern is found in borderline personality disorder?","Strong amygdala responses to negative pictures with weak prefrontal control.",46,10],[227,"How does the amygdala respond to neutral pictures in schizophrenia?","It reacts almost as much to neutral pictures as to threatening ones.",46,11],[227,"How does apathy differ from anhedonia?","Apathy is loss of drive, not paying effort for a reward that is still enjoyed. Anhedonia is loss of pleasure.",46,12],[227,"Which circuits and conditions are linked to apathy?","The anterior cingulate, ventral striatum and their dopamine input. It is common in small vessel disease and Parkinson's disease, often without low mood.",46,13],[227,"What did Capuron find about symptom timing in patients given interferon-alpha for melanoma?","Fatigue and slowing began within two weeks, while low mood and anxiety came in months two and three.",46,14],[227,"How did paroxetine affect interferon-induced symptoms, and what does this suggest about fatigue?","It prevented mood symptoms but not fatigue, suggesting fatigue comes from cytokine effects on basal ganglia dopamine.",46,15],[228,"A man aged 30 becomes placid with hyperorality and hypersexuality after herpes encephalitis. Which structure is lost?","The amygdala on both sides, causing Kluver-Bucy syndrome.",46,16],[230,"A woman aged 72 ignores the left of her plate and cannot copy a cube. Which area is affected?","The non-dominant (right) parietal lobe, causing left neglect and constructional apraxia.",47,1],[230,"Which field defect does a pituitary tumour pressing on the optic chiasm cause, and why?","Bitemporal hemianopia, because it cuts the crossing nasal retinal fibres that see the temporal fields.",47,2],[230,"Which visual field defect follows a left occipital lesion?","A right homonymous hemianopia.",47,3],[230,"What field defect does a temporal lobe lesion cause, and which fibres are involved?","A contralateral upper quadrant loss, from damage to Meyer's loop of the optic radiation.",47,4],[230,"What visual field defect follows a parietal lesion of the optic radiation?","A contralateral lower quadrant loss.",47,5],[231,"What are the roles of the ventral and dorsal visual streams?","The ventral (temporal) stream tells what an object is. The dorsal (parietal) stream tells where it is, or vision for action.",47,6],[231,"How do optic ataxia and visual agnosia differ in their lesion and deficit?","Optic ataxia is dorsal stream damage with misreaching for seen objects. Visual agnosia is ventral damage with failure to recognise objects.",47,7],[231,"What is prosopagnosia, and which area is damaged?","Inability to recognise faces while voices are known, from damage, usually bilateral, to the fusiform face area.",47,8],[231,"Which visual area processes motion, and how is it placed relative to V4?","V5, which lies more laterally than the colour area V4.",47,9],[231,"What are the features of left hemispatial neglect, and where is the lesion?","Patients eat from the right of the plate and bisect lines too far right, despite full fields. The lesion is in the right inferior parietal lobule.",47,10],[231,"How do anosognosia, hemisomatognosia and somatoparaphrenia differ?","Anosognosia is denial of paralysis. Hemisomatognosia is feeling one side is missing. Somatoparaphrenia is believing the limb belongs to someone else.",47,11],[231,"What are astereognosis and agraphaesthesia, and what lesion do they indicate?","Failing to name an object by touch, and failing to read numbers traced on the palm, with normal basic sensation. Both indicate a contralateral parietal lesion.",47,12],[231,"What is Balint's syndrome and what usually causes it?","Simultanagnosia, optic ataxia and difficulty moving the eyes to targets, from bilateral parieto-occipital watershed damage, often after severe hypotension.",47,13],[231,"What is Anton's syndrome and why are pupil reflexes preserved?","Cortical blindness from bilateral occipital damage with denial of blindness. Pupils react because the light reflex uses the midbrain.",47,14],[231,"Why may central vision survive bilateral posterior cerebral artery strokes?","The occipital pole serving the macula often has a dual supply from the middle and posterior cerebral arteries, giving macular sparing.",47,15],[231,"How did Hirstein and Ramachandran explain Capgras syndrome?","Faces are recognised but give no skin conductance response, because the emotional route to the amygdala is cut. It is the mirror image of prosopagnosia.",47,16],[231,"How does predictive coding explain hallucinations?","The brain predicts its input. If prior expectations are weighted too strongly, perceptions can arise without any stimulus (Corlett).",47,17],[232,"A painter aged 64 sees the world grey after a stroke with an upper field defect. Where is the lesion?","The colour area V4 in the lingual and fusiform gyri, causing cerebral achromatopsia.",47,18],[232,"How does Charles Bonnet syndrome differ from Anton's syndrome?","In Charles Bonnet syndrome visual loss comes with images the person knows are not real. In Anton's the person denies being blind.",47,19],[235,"Which three attention networks did Posner and Petersen describe in 1990?","Alerting, orienting and executive control.",48,1],[235,"Which transmitter and source support the alerting network?","Noradrenaline from the locus coeruleus.",48,2],[235,"What does the orienting network do, and what are its region and transmitter?","It moves attention to a place in space, using parietal cortex and acetylcholine.",48,3],[235,"Which attention network is linked to the anterior cingulate cortex and dopamine?","The executive control network, which settles conflict between responses using anterior cingulate and lateral prefrontal cortex.",48,4],[235,"In Fan's attention network test, what tests each network?","A warning tone tests alerting, a spatial cue tests orienting and clashing flanker arrows test executive control.",48,5],[235,"Which of Posner's attention networks does ADHD affect most?","The executive control network.",48,6],[235,"Which regions form the dorsal attention network and what does it do?","The intraparietal sulcus and frontal eye fields on both sides. It sets attention on purpose, from the top down.",48,7],[236,"What are the location and function of the ventral attention network?","A right-sided network centred on the temporoparietal junction and ventral frontal cortex. It reorients attention to unexpected relevant events.",48,8],[236,"How does damage to the ventral attention network help explain left neglect?","It unbalances the dorsal attention network, so attention is biased away from the left.",48,9],[236,"What did Shaw's longitudinal scans show about cortical maturation in ADHD?","Peak cortical thickness came about 3 years late, at a median of 10.5 years versus 7.5 in controls.",48,10],[236,"Where was cortical delay greatest in ADHD, and what does the finding imply?","In prefrontal cortex. It suggests late maturing rather than a permanently different brain.",48,11],[236,"What did Hart and Rubia find during stop-signal tasks in ADHD?","Weak activity in the right inferior frontal cortex, basal ganglia and thalamus.",48,12],[236,"What is Sonuga-Barke's dual pathway model of ADHD?","Alongside poor inhibitory control, a second route of delay aversion, a dislike of waiting linked to reward circuits.",48,13],[236,"What is the default mode interference hypothesis of ADHD?","The default mode network is poorly suppressed during tasks and intrudes from time to time, causing lapses and variable reaction times.",48,14],[236,"On a continuous performance test, what do omission and commission errors each mark?","Omissions, missed targets, mark inattention. Commissions, responses to non-targets, mark impulsivity.",48,15],[236,"How does methylphenidate act on brain transmitters in ADHD?","It blocks the dopamine and noradrenaline transporters, raising both in the prefrontal cortex and striatum.",48,16],[237,"A boy aged 10 with ADHD has variable reaction times and missed targets. Which network fails to fall?","The default mode network, which normally switches off when a task starts.",48,17],[239,"What did Drachman and Leavitt show by giving hyoscine to young volunteers?","They learned word lists poorly, like healthy older people, showing acetylcholine has a central role in learning and memory.",49,1],[239,"What does the cholinergic hypothesis explain in Alzheimer's disease, and what does it not?","Cholinergic loss explains the memory symptoms of Alzheimer's disease, not its cause.",49,2],[239,"How does declarative memory differ from procedural memory?","Declarative memory holds facts (semantic) and events (episodic) that can be put into words. Procedural memory holds skills via the striatum and cerebellum.",49,3],[239,"What happened to patient H.M. after bilateral medial temporal lobe removal in 1953?","He developed dense anterograde amnesia and could not learn new facts or faces.",49,4],[239,"Which abilities did H.M. keep despite his amnesia?","IQ, digit span, childhood memories and procedural learning, such as improving at mirror drawing.",49,5],[240,"What are the four parts of Baddeley's working memory model?","The central executive, the phonological loop, the visuospatial sketchpad and the episodic buffer.",49,6],[240,"What do forward and backward digit span each test?","Forward span, normally about 7 plus or minus 2, mainly tests storage. Backward span adds central executive work in the dorsolateral prefrontal cortex.",49,7],[240,"What did Wilson and McNaughton observe in sleeping rats, and what process does it support?","Hippocampal place cells replayed the day's maze runs, supporting systems consolidation of memories into the cortex.",49,8],[240,"What is reconsolidation, as shown by Nader?","A retrieved memory becomes unstable again and can be erased by blocking protein synthesis.",49,9],[240,"What is Ribot's law and why does it hold?","In organic amnesia recent memories are lost before remote ones, because old memories no longer depend on the hippocampus.",49,10],[240,"What happens to memory in semantic dementia?","The anterior temporal lobes waste away and knowledge of words and objects fades.",49,11],[240,"Which structures are damaged in Korsakoff syndrome, and which memory is lost?","The mammillary bodies and mediodorsal thalamus. Episodic memory fails while skills and general knowledge stay.",49,12],[240,"What is confabulation and which lesions are linked to it?","Honest telling of real memories in the wrong time or place, with no intent to deceive. It is linked to orbitofrontal and basal forebrain damage.",49,13],[240,"What is a classic cause of confabulation apart from Korsakoff syndrome?","A ruptured anterior communicating artery aneurysm.",49,14],[240,"What does Brewin's dual representation model of PTSD propose?","A strong sensory trauma memory held by the amygdala and a weak time and place memory held by the hippocampus, so fragments replay as if now.",49,15],[240,"What did Brunet aim to do by giving propranolol before trauma memory reactivation?","To weaken reconsolidation of the trauma memory, and PTSD symptoms fell.",49,16],[240,"How does ICD-11 dissociative amnesia differ from organic amnesia?","Dissociative amnesia loses personal identity and life story, often after stress, with skills and knowledge kept. Organic amnesia rarely removes identity.",49,17],[240,"What is dissociative fugue and how does it present?","Dissociative amnesia in which the person travels away and may take on a new identity.",49,18],[241,"A man aged 56 who drinks heavily has amnesia and confabulation after earlier confusion and eye signs. Which structure?","The mammillary bodies, damaged by thiamine deficiency in Korsakoff syndrome following Wernicke's encephalopathy.",49,19],[241,"Which three enzymes depend on thiamine?","Pyruvate dehydrogenase, alpha-ketoglutarate dehydrogenase and transketolase.",49,20],[243,"What is utilisation behaviour and who first described it?","It is the compulsive picking up and using of objects within reach, even when told not to. Lhermitte described it in 1983.",50,1],[243,"Which frontal region is classically damaged in utilisation behaviour?","The orbitofrontal (lower orbital frontal) cortex, which normally inhibits responses triggered by objects in view.",50,2],[243,"A woman aged 58 on a UK ward puts on every pair of glasses she sees and drinks from any cup. Where is the lesion?","The orbitofrontal cortex. This is utilisation behaviour, a sign of frontal damage.",50,3],[243,"What are executive functions, and what everyday analogy describes the role of the frontal lobes?","They are the brain's management skills, such as planning, switching between tasks, holding goals in mind and stopping unwanted actions. The frontal lobes act like the managers of a company.",50,4],[243,"Which researcher linked separate frontal-subcortical circuits to separate frontal syndromes?","Cummings linked distinct frontal-subcortical circuits to distinct clinical syndromes.",50,5],[243,"What clinical picture follows damage to the dorsolateral prefrontal cortex?","A dysexecutive syndrome, with poor planning, loss of track in multi-step tasks and perseveration. Social manners are often preserved.",50,6],[243,"Which test shows perseveration after a rule change in dorsolateral prefrontal damage?","The Wisconsin Card Sorting Test, where the person keeps using an old sorting rule after it has changed.",50,7],[243,"What clinical picture follows orbitofrontal damage and what did Blumer and Benson call it?","Disinhibition with crude jokes, facetious humour and reckless spending, with normal IQ. They called it pseudopsychopathic.",50,8],[243,"What clinical picture follows medial frontal and anterior cingulate damage and what is it called?","Apathy, slowness, near mutism and incontinence without concern. Blumer and Benson called it the pseudodepressed picture.",50,9],[244,"Why can frontal lobe syndrome be missed on standard cognitive testing?","IQ and memory are often normal, so the clue is changed behaviour and the return of primitive reflexes such as grasp.",50,10],[244,"Who was Phineas Gage and what did his case show?","A man injured by an iron bar through the frontal lobe in 1848 who became rude and unreliable, showing frontal control of social behaviour.",50,11],[244,"What did Bechara and Damasio find with the Iowa gambling task in ventromedial prefrontal damage?","Patients kept choosing decks with big wins but bigger losses and lacked the normal skin conductance rise before risky choices.",50,12],[244,"What is Damasio's somatic marker hypothesis?","Bodily signals linked to past outcomes guide decisions before conscious reasoning. Their loss after ventromedial damage leads to poor choices.",50,13],[244,"What is delay discounting and in which conditions is it steep?","Preferring a small immediate reward over a larger later one. It is steep in ADHD, addiction and orbitofrontal damage.",50,14],[244,"According to McClure, which brain regions value immediate versus delayed rewards?","The ventral striatum values immediate rewards, while the lateral prefrontal cortex values delayed rewards.",50,15],[244,"Name two meanings of impulsivity and two psychiatric conditions besides ADHD in which it is prominent.","It can mean failure to stop an action or poor choice of reward. It is prominent in mania and borderline personality disorder.",50,16],[244,"What did Weinberger show in 1986 about frontal blood flow in schizophrenia?","During the Wisconsin Card Sorting Test, controls increased DLPFC blood flow but people with schizophrenia did not. This is hypofrontality.",50,17],[244,"With which features of schizophrenia is hypofrontality associated?","Negative symptoms, poor cognition and low prefrontal dopamine. It was not explained by poor effort.",50,18],[244,"Is hypofrontality in schizophrenia a fixed finding regardless of task?","No. It depends on task load, with overactivation on easy tasks and underactivation on hard ones. It is also reported in depression.",50,19],[245,"A man aged 34 makes crude jokes and gambles away savings after a road collision, with normal IQ. Where is the damage?","The orbitofrontal cortex, which is bruised against the bony orbital roofs in sudden deceleration injuries.",50,20],[247,"Where were mirror neurons first found and by whom?","Rizzolatti found them in premotor area F5 of the macaque monkey.",51,1],[247,"What property defines a mirror neuron?","It fires both when an animal performs an action and when it watches another individual perform the same action.",51,2],[247,"Which human regions show mirror neuron properties?","The inferior frontal gyrus and the inferior parietal lobule.",51,3],[247,"What is the status of the broken mirror theory of autism?","It proposes faulty mirror neurons cause autism, but it has only weak evidential support.",51,4],[247,"What is theory of mind and who coined the term?","Understanding that others hold beliefs and wishes different from one's own. Premack and Woodruff coined it in 1978 studying chimpanzees.",51,5],[247,"Describe the Sally-Anne test and the ability it is designed to measure.","Sally hides a marble and leaves, Anne moves it, and the child is asked where Sally will look. It tests false belief understanding.",51,6],[247,"What did Baron-Cohen, Leslie and Frith find with the Sally-Anne test in 1985?","About 80% of autistic children failed despite higher verbal mental age, while about 85% of typical and Down syndrome children passed.",51,7],[247,"Which region responds most selectively to reasoning about other people's beliefs?","The right temporoparietal junction, as shown by Saxe and Kanwisher.",51,8],[247,"Which regions make up the theory of mind network?","The right temporoparietal junction, medial prefrontal cortex and superior temporal sulcus.",51,9],[248,"At about what age do typically developing children pass false belief tasks?","At about 4 years.",51,10],[248,"What is the difference between cognitive and affective empathy?","Cognitive empathy is knowing what another feels, close to theory of mind. Affective empathy is sharing that feeling.",51,11],[248,"What did Singer find when one partner of a couple received a painful shock?","The anterior insula and anterior cingulate activated both for one's own pain and for a loved one's pain.",51,12],[248,"What face processing difference did Schultz report in autism?","Reduced fusiform face area response, with faces processed by an object region, the inferior temporal gyrus. The amygdala also responds less to faces.",51,13],[248,"What is weak central coherence and who proposed it as a theory of autism?","A theory by Frith and Happé that autistic people are biased towards local detail rather than the global whole.",51,14],[248,"How does the empathy profile in psychopathy differ from that in autism?","Psychopathy usually spares theory of mind but reduces affective empathy. Autism tends to show the reverse, with cognitive empathy harder but caring intact.",51,15],[248,"What is Blair's explanation for lack of empathy in psychopathy?","The amygdala responds weakly to others' fear and sadness, and the ventromedial prefrontal cortex fails to link causing harm with a bad outcome.",51,16],[248,"How do ICD-11 and DSM-5-TR classify persistent dissocial behaviour in adults?","ICD-11 uses personality disorder with prominent dissociality, and DSM-5-TR uses antisocial personality disorder.",51,17],[248,"Weak central coherence and aberrant salience are theories of which disorders respectively?","Weak central coherence is a theory of autism, and aberrant salience is a theory of psychosis.",51,18],[249,"Monkey premotor cells fire when grasping a raisin and when watching a keeper grasp one. Why is the right TPJ wrong?","The right TPJ is selective for beliefs rather than actions. The correct system is the mirror neuron system in the inferior frontal gyrus and inferior parietal lobule.",51,19],[251,"In what proportion of right-handed people is language in the left hemisphere?","About 95% of right-handers have left hemisphere language dominance.",52,1],[251,"Where is Broca's area and which Brodmann areas does it occupy?","The left (dominant) inferior frontal gyrus, Brodmann areas 44 and 45. Broca described it in 1861.",52,2],[251,"What are the features of Broca's aphasia?","Slow, effortful, telegraphic speech missing small words, poor repetition and good understanding. Patients are aware and often frustrated or depressed.",52,3],[251,"Why do patients with Broca's aphasia often have right face and arm weakness?","Broca's area lies next to the motor strip, so the same lesion often affects it.",52,4],[251,"Where is Wernicke's area and which Brodmann area is it?","The posterior superior temporal gyrus of the dominant hemisphere, Brodmann area 22. Wernicke described it in 1874.",52,5],[251,"What are the features of Wernicke's aphasia?","Fluent, rapid speech full of paraphasias, with poor comprehension and poor repetition. Patients seem unaware and unconcerned.",52,6],[251,"A right-handed woman aged 70 has a stroke and speaks fluently but nonsensically, unable to follow commands. Which region is damaged?","The left posterior superior temporal gyrus, Wernicke's area.",52,7],[251,"Which psychiatric phenomenon can Wernicke's aphasia be mistaken for?","The word salad of psychosis, because speech is fluent but meaningless and the patient lacks insight.",52,8],[252,"What is conduction aphasia and which structure is damaged?","Fluent speech and good comprehension but failed repetition with phonemic errors and self-correction. It results from arcuate fasciculus damage.",52,9],[252,"In which aphasias is repetition preserved and why?","In the transcortical aphasias, because the arcuate route between Wernicke's and Broca's areas is intact.",52,10],[252,"What is characteristic of transcortical sensory aphasia?","Patients repeat even long sentences well but do not understand them.",52,11],[252,"Describe the dual stream model of language of Hickok and Poeppel.","A bilateral ventral temporal stream maps sound to meaning. A left-dominant dorsal stream via the arcuate and superior longitudinal fasciculi maps sound to speech movements and carries repetition.",52,12],[252,"What are the features and classic site of anomic aphasia?","Fluent speech with good comprehension and repetition but poor naming and circumlocution. The classic site is the dominant angular gyrus, though it is the least localising aphasia.",52,13],[252,"In what settings is anomic aphasia commonly seen?","It is the usual residual deficit after recovery from other aphasias and an early sign of Alzheimer's disease.",52,14],[252,"What is the difference between semantic and phonemic paraphasias?","A semantic paraphasia swaps a related word, such as fork for knife. A phonemic paraphasia swaps sounds, such as tabe for table.",52,15],[252,"Define neologism, echolalia and perseveration in speech.","A neologism is a made-up word. Echolalia repeats the examiner's words. Perseveration repeats one's own previous answer.",52,16],[252,"What results from a dominant angular gyrus lesion and which artery is usually involved?","Alexia with agraphia, often with a right visual field defect. It is usually due to the inferior division of the middle cerebral artery.",52,17],[252,"What are the four features of Gerstmann syndrome and where is the lesion?","Finger agnosia, left-right confusion, agraphia and acalculia. The lesion is in the dominant angular gyrus.",52,18],[253,"A right-handed man aged 60 can write but cannot read back his note and has a right hemianopia. What is the lesion?","Alexia without agraphia from a left posterior cerebral artery stroke affecting the left occipital cortex and the splenium of the corpus callosum.",52,19],[253,"Why is writing preserved in alexia without agraphia?","The language areas are intact, but words seen by the right visual cortex cannot cross the damaged splenium to reach the left angular gyrus. Dejerine described it in 1892 as a disconnection syndrome.",52,20],[255,"What are large-scale brain networks and how are they usually identified?","Sets of distant brain regions whose activity rises and falls together. They are usually found with resting-state fMRI.",53,1],[255,"Who described the default mode network and when?","Marcus Raichle in 2001, noting regions that were more active at rest than during tasks.",53,2],[255,"What are the core hubs of the default mode network?","The posterior cingulate cortex, precuneus and medial prefrontal cortex, with the angular gyrus and medial temporal lobe.",53,3],[255,"What mental activity is the default mode network associated with?","Mind wandering and self-referential thought about oneself, one's past and future. It is task-negative and falls during demanding tasks.",53,4],[255,"Where does amyloid first accumulate in Alzheimer's disease in relation to brain networks?","In default mode network hubs, especially the posterior cingulate and precuneus.",53,5],[256,"Which regions make up the central executive network and what does it do?","The dorsolateral prefrontal cortex and posterior parietal cortex. It holds and manipulates information during demanding tasks.",53,6],[256,"Which regions form the dorsal attention network?","The intraparietal sulcus and the frontal eye fields.",53,7],[256,"What did Fox show in 2005 about the task-positive network and the default mode network?","They are anticorrelated even at rest, so when one rises the other falls.",53,8],[256,"Which regions make up the salience network?","The anterior insula and the dorsal anterior cingulate cortex.",53,9],[256,"What is the function of the salience network?","It detects important internal and external events and switches between the default mode and central executive networks.",53,10],[256,"What did Sridharan find about the right anterior insula?","It activates just before the brain switches from the default mode network to the executive network, acting as the switch.",53,11],[256,"What did Friston and Frith propose about schizophrenia in 1995?","That schizophrenia is a disconnection syndrome due to faulty control of synaptic plasticity.",53,12],[256,"What default mode network abnormality did Whitfield-Gabrieli find in schizophrenia?","The DMN was overactive and failed to switch off during tasks, in patients and in their relatives.",53,13],[256,"What is Menon's triple network model?","Proposed in 2011, it says many disorders share faulty salience network switching between the DMN and executive network, as in psychotic aberrant salience, depressive rumination and anxious threat bias.",53,14],[256,"Which network change is linked to rumination in depression?","Default mode network hyperconnectivity, including the subgenual cingulate, as reported by Hamilton.",53,15],[256,"What effect does psilocybin have on the default mode network?","Carhart-Harris found it reduces activity and connectivity in DMN hubs.",53,16],[256,"What default mode network finding is described in ADHD?","The DMN is poorly suppressed during tasks.",53,17],[256,"Is the precuneus part of the salience network?","No. The precuneus belongs to the default mode network, a common exam trap.",53,18],[257,"A man aged 58 who smoked for 40 years loses the urge to smoke after a stroke. Which region was likely damaged?","The anterior insula, as Naqvi showed that insula damage disrupts smoking addiction.",53,19],[257,"What is interoception and which region maps it?","The sensing of internal bodily states such as heartbeat. The anterior insula maps it.",53,20],[259,"How do hypothalamic releasing hormones reach the anterior pituitary?","Parvocellular neurons release them into median eminence capillaries, and the hypophyseal portal veins carry them at high concentration to the anterior lobe.",54,1],[259,"What did Geoffrey Harris show by cutting the pituitary stalk in animals in the 1940s?","Anterior pituitary output failed when the portal vessels did not regrow and returned when they did, proving portal blood control.",54,2],[259,"How do hormones reach the blood from the posterior pituitary?","Magnocellular neurons of the supraoptic and paraventricular nuclei send axons down the stalk and release hormone directly from their endings into the blood.",54,3],[259,"Which hypothalamic peptide of 41 amino acids drives ACTH release, and who identified it?","Corticotropin-releasing hormone from the paraventricular nucleus, identified by Wylie Vale in 1981.",54,4],[259,"What CRH-related findings are reported in depression?","CSF CRH is raised, post-mortem brains show more CRH neurons, and the ACTH response to injected CRH is blunted. CRH antagonists failed as antidepressants.",54,5],[260,"From which precursor protein is ACTH cleaved, and what else comes from it?","Pro-opiomelanocortin (POMC), which also yields beta-endorphin.",54,6],[260,"What is the role of vasopressin in ACTH release?","It is a helper that boosts the action of CRH through V1b receptors, but it is not the main driver.",54,7],[260,"Which pituitary hormones are released by TRH, GnRH and GHRH?","TRH releases TSH and prolactin. Pulsatile GnRH releases LH and FSH. GHRH releases growth hormone.",54,8],[260,"What does somatostatin do and which drug is its analogue?","It inhibits growth hormone release and lowers TSH. Octreotide is a long-acting analogue used in acromegaly and gigantism.",54,9],[260,"What controls prolactin secretion from the anterior pituitary?","Dopamine from the arcuate nucleus tonically inhibits prolactin through D2 receptors on lactotrophs.",54,10],[260,"What is the stalk effect on pituitary hormones when the pituitary stalk is compressed?","Compression of the pituitary stalk lowers most anterior hormones but raises prolactin, because its dopamine brake is lost.",54,11],[260,"How is the overnight dexamethasone suppression test done and what is the normal result?","1 mg dexamethasone is given at 11 pm and blood is taken at 8 am. Low ACTH and cortisol, showing suppression, is normal.",54,12],[260,"Which conditions cause failure to suppress cortisol on low-dose dexamethasone?","An ACTH-secreting pituitary adenoma, glucocorticoid receptor resistance and about half of people with melancholic depression.",54,13],[260,"What is the hormone pattern in primary adrenal failure?","Cortisol is low and ACTH is high, because negative feedback is lost.",54,14],[260,"When does the largest growth hormone pulse of the day occur?","Within an hour of sleep onset, during the first period of slow-wave sleep, as Takahashi showed in 1968.",54,15],[260,"How do ACTH, cortisol and TSH vary across the night?","ACTH and cortisol are lowest early in the night and rise towards dawn. TSH rises in the evening and sleep suppresses it.",54,16],[260,"What is the difference between the roles of prolactin and oxytocin in breastfeeding?","Prolactin, an anterior hormone, makes milk. Oxytocin, a posterior hormone, ejects milk and causes uterine cramps.",54,17],[260,"What are the peripheral and central roles of vasopressin?","It concentrates urine and raises blood pressure. In the brain it acts in the lateral septum and amygdala and shapes pair bonding in voles.",54,18],[260,"How long are oxytocin and vasopressin, and where is melatonin made?","Both are peptides of 9 amino acids. Melatonin comes from the pineal gland, not the pituitary.",54,19],[261,"A woman aged 32 develops galactorrhoea two months after starting risperidone. What explains this?","Risperidone blocks pituitary D2 receptors, removing dopamine's brake on prolactin. The pituitary lies outside the blood-brain barrier.",54,20],[264,"When is plasma cortisol normally highest and lowest?","Highest around 6 to 8 am and lowest around midnight, driven by the suprachiasmatic nucleus.",55,1],[264,"What does a raised late-night cortisol level suggest?","Loss of the normal midnight trough is an early sign of Cushing's syndrome.",55,2],[264,"What is the fast arm of the stress response?","The sympatho-adrenal medullary system: locus coeruleus noradrenaline and adrenaline from the adrenal medulla, acting within seconds.",55,3],[264,"What do sympathetic preganglionic fibres release onto the adrenal medulla?","Acetylcholine, which causes the medulla to secrete adrenaline.",55,4],[264,"What is the sequence of the slow arm of the stress response?","CRH from the paraventricular nucleus, helped by vasopressin, releases pituitary ACTH from POMC, which drives cortisol from the adrenal cortex over minutes.",55,5],[264,"Which zone of the adrenal cortex makes cortisol, and what mainly controls aldosterone?","The zona fasciculata makes cortisol. Aldosterone is mainly controlled by the renin-angiotensin system, not ACTH.",55,6],[265,"What is the cortisol awakening response?","An extra burst of cortisol after waking, about a 50% rise peaking 30 to 45 minutes after waking.",55,7],[265,"What did Fries and colleagues find about the cortisol awakening response?","It is larger when a demanding day such as an exam lies ahead.",55,8],[265,"How do mineralocorticoid and glucocorticoid receptors differ in their binding of cortisol?","MR has about 10 times higher affinity and is mostly occupied even at the trough. GR has lower affinity and fills only at the peak or in stress.",55,9],[265,"What are the functions of MR and GR in the stress response?","MR sets basal tone and the onset of the response. GR ends the response through negative feedback and is the main target of dexamethasone.",55,10],[265,"Who mapped brain MR and GR in rats, and where is MR densest?","Reul and de Kloet in 1985. MR is densest in the hippocampus.",55,11],[265,"What are the three stages of Selye's general adaptation syndrome?","Alarm, resistance and exhaustion. Exhaustion brought enlarged adrenals, a shrunken thymus and stomach ulcers. Selye described it in 1936.",55,12],[265,"What are allostasis and allostatic load?","Allostasis is adapting through change (Sterling and Eyer). Allostatic load is the wear and tear from repeated activation (McEwen).",55,13],[265,"A night-shift worker aged 45 has hypertension, central obesity, insulin resistance and poor sleep. What concept does this illustrate?","Allostatic load, the cumulative wear and tear of chronic stress responses.",55,14],[265,"How do kindling and learned helplessness differ from allostatic load?","Kindling is growing sensitivity to repeated episodes, and learned helplessness is a behavioural model of depression.",55,15],[265,"What hippocampal and amygdala changes follow chronic stress or corticosterone in rats?","CA3 apical dendrites shrink and dentate gyrus neurogenesis falls, while amygdala dendrites grow. These changes are early and reversible.",55,16],[265,"What is the glucocorticoid cascade hypothesis?","Proposed by Sapolsky, Krey and McEwen in 1986, cortisol damages the hippocampus, weakening its brake on the HPA axis so cortisol rises further.",55,17],[265,"What brain and cognitive findings occur in Cushing's disease?","High cortisol with smaller hippocampi and poor verbal memory. Starkman found hippocampal volume partly recovered after cortisol was lowered.",55,18],[266,"A woman aged 35 before a talk releases an adrenal steroid that switches off its own axis via low-affinity receptors. Which hormone?","Cortisol, which ends the stress response through glucocorticoid receptors in the hippocampus, hypothalamus and pituitary.",55,19],[266,"Does chronic stress cause neurofibrillary tangles or Lewy bodies in the hippocampus?","No. It causes dendritic shrinkage in CA3, not tangles or Lewy bodies.",55,20],[269,"What proportion of people with major depression have raised cortisol?","About 50%, mostly those with severe or melancholic depression.",56,1],[269,"What CSF finding did Nemeroff report in drug-free depression in 1984?","Raised corticotropin-releasing factor (CRF, also called CRH).",56,2],[269,"How did Carroll perform the dexamethasone suppression test in depression, and what did he find?","1 mg dexamethasone at 11 pm with cortisol measured at 4 pm next day. About half of melancholic patients failed to suppress.",56,3],[269,"Does DST non-suppression occur only in psychotic depression?","No, it also occurs in non-psychotic melancholic depression.",56,4],[270,"Why is the dexamethasone suppression test not used to diagnose depression?","Non-suppression also occurs in mania, dementia, anorexia, alcohol misuse, weight loss and with many drugs, so it is not specific. Repeating it does not help.",56,5],[270,"What is the combined dex/CRH test and how sensitive is it?","1.5 mg dexamethasone followed by 100 micrograms CRH the next afternoon. It detects cortisol escape in up to 80% of depressed inpatients.",56,6],[270,"What HPA axis pattern did Rachel Yehuda describe in PTSD?","Lower basal cortisol than trauma-exposed controls, raised CSF CRF, preserved but wider daily rhythm, and hypersuppression on 0.5 mg dexamethasone.",56,7],[270,"How does glucocorticoid feedback in PTSD contrast with melancholic depression?","PTSD shows sensitive receptors and enhanced feedback with hypersuppression. Melancholia shows receptor resistance and non-suppression.",56,8],[270,"What TSH response to TRH is seen in euthyroid depressed patients?","About 25% show a blunted TSH response. An exaggerated response suggests subclinical hypothyroidism.",56,9],[270,"What does the clonidine challenge test show in depression?","A blunted growth hormone rise, suggesting reduced postsynaptic alpha-2 receptor sensitivity, as Siever found.",56,10],[270,"What do apomorphine, buspirone and short Synacthen challenge tests probe?","Apomorphine probes dopamine, buspirone probes 5-HT1A receptors, and short Synacthen checks adrenal reserve.",56,11],[270,"What are the clinical features of hypothyroidism that may mimic depression?","Low mood, slowed thinking, weight gain, constipation, dry skin, cold intolerance, hoarse voice, low libido, slow-relaxing reflexes, bradycardia and raised TSH.",56,12],[270,"What is myxoedema madness and how is it treated?","Psychosis in severe hypothyroidism, described by Richard Asher in 1949. It clears with thyroid replacement.",56,13],[270,"Which features of hyperthyroidism can mimic an anxiety disorder?","Tremor, sweating, heat intolerance, tachycardia and weight loss despite increased appetite.",56,14],[270,"What are the clinical and biochemical features of Addison's disease?","Apathy, fatigue, weight loss, postural dizziness and pigmented skin creases and gums, with low sodium and high potassium. A short Synacthen test confirms it.",56,15],[270,"What are the psychiatric and physical features of Cushing's syndrome?","Depression with a round face, central weight gain, purple striae, hirsutism and hypertension.",56,16],[270,"A woman aged 40 has attacks of headache, palpitations, sweating, pallor and very high blood pressure. What is the screening test?","Plasma free metanephrines, to look for phaeochromocytoma, which can mimic panic disorder.",56,17],[270,"What are the features of primary hyperparathyroidism relevant to psychiatry?","Raised calcium with inappropriately high PTH, causing tiredness, thirst, constipation, kidney stones, low mood and personality change.",56,18],[271,"A man aged 31 drinks 8 litres daily; after fluid deprivation plasma is concentrated and urine dilute. What is the diagnosis?","Diabetes insipidus, because the kidney cannot concentrate urine without ADH action.",56,19],[271,"How does psychogenic polydipsia differ from diabetes insipidus on water deprivation testing?","In psychogenic polydipsia both plasma and urine are dilute, and urine concentrates once drinking stops. In diabetes insipidus urine stays dilute while plasma becomes concentrated.",56,20],[274,"Which blood inflammatory markers are most consistently raised in major depression?","IL-6, TNF-alpha and C-reactive protein, first shown for IL-6 and TNF-alpha in Dowlati's 2010 meta-analysis.",57,1],[274,"Can raised inflammatory markers be used as a blood test for depression?","No. They are modest group findings with much overlap, confounded by obesity, smoking and poor sleep, suggesting an inflamed subgroup only.",57,2],[274,"Which cytokines give mixed results in depression studies?","Interferon-gamma, IL-2 and the anti-inflammatory cytokines IL-10, IL-4 and TGF-beta.",57,3],[274,"What is sickness behaviour and who described it?","An adaptive programme of lethargy, poor appetite, anhedonia and social withdrawal driven by cytokines such as IL-1 beta. Robert Dantzer described it.",57,4],[274,"How do cytokines signal to the brain via nerves, given they cannot easily cross the blood-brain barrier?","Through vagal afferents to the brainstem. Cutting the vagus below the diaphragm blocks sickness behaviour in rats.",57,5],[275,"How does IL-1 beta cause fever without crossing the blood-brain barrier?","It induces COX-2 in brain endothelial cells, producing prostaglandin E2, which acts on hypothalamic EP3 receptors to raise the set point.",57,6],[275,"How often does interferon-alpha treatment cause depression?","In about a third of patients, roughly 30 to 45%.",57,7],[275,"What did Musselman show about preventing interferon-induced depression?","Starting paroxetine before interferon-alpha reduced severe depression.",57,8],[275,"What does indoleamine 2,3-dioxygenase do during inflammation?","IDO diverts tryptophan away from serotonin synthesis into the kynurenine pathway.",57,9],[275,"What do microglia and astrocytes make from kynurenine, and what are their actions?","Microglia make quinolinic acid, an excitotoxic NMDA agonist. Astrocytes make kynurenic acid, an NMDA antagonist.",57,10],[275,"In which disorder is CSF kynurenic acid raised?","Schizophrenia.",57,11],[275,"What does TSPO PET measure and what has it shown in depression?","It measures translocator protein, which rises on activated microglia. Setiawan found about 30% higher binding in depression.",57,12],[275,"Why is TSPO PET not a diagnostic test?","Results in psychosis are mixed, and the common rs6971 variant changes tracer binding. It remains a research tool.",57,13],[275,"What did Sekar link to schizophrenia risk?","High brain levels of complement C4, leading to excessive microglial synaptic pruning.",57,14],[275,"How is maternal infection in pregnancy linked to schizophrenia and autism?","Mid-pregnancy influenza with high fever slightly raises risk. Maternal immune activation, especially IL-6, rather than fetal viral infection drives the effect.",57,15],[275,"What did Smith show with the poly I:C maternal immune activation model?","Maternal IL-6 is necessary and sufficient for many of the offspring changes.",57,16],[275,"What did Sudo find in germ-free mice?","They showed an exaggerated ACTH and corticosterone response to restraint, partly reversed by early Bifidobacterium.",57,17],[275,"Which patients with treatment-resistant depression benefited from infliximab?","Only those with baseline CRP above 5 mg/L. Overall the trial was negative.",57,18],[275,"What did the BeneMin trial find and is any anti-inflammatory recommended for depression in the UK?","Minocycline did not improve negative symptoms of schizophrenia. No anti-inflammatory is licensed or recommended by NICE for depression.",57,19],[276,"A woman aged 39 with depression has a PET scan targeting a microglial mitochondrial protein affected by rs6971. What is the target?","Translocator protein (TSPO), a marker of microglial activation.",57,20],[278,"A woman aged 23 has psychosis after a flu-like illness, then seizures, lip-smacking and labile blood pressure. What is the likely diagnosis?","Anti-NMDA receptor encephalitis, with antibodies against the GluN1 subunit.",58,1],[278,"Describe the typical staged course of anti-NMDA receptor encephalitis.","A flu-like prodrome, then agitation, paranoia, insomnia or catatonia, then seizures, orofacial dyskinesia, autonomic instability and reduced consciousness.",58,2],[278,"Who described anti-NMDA receptor encephalitis and what is the antibody target?","Josep Dalmau in 2007. In 2008 his group showed IgG antibodies bind the GluN1 subunit.",58,3],[278,"How do NMDA receptor antibodies impair neuronal function?","They cross-link the receptors and cause internalisation, reducing glutamate signalling much as ketamine does.",58,4],[278,"Which sample is more sensitive for NMDA receptor antibodies, and what does CSF often show?","CSF is more sensitive than serum. CSF often shows a mild lymphocytosis.",58,5],[278,"Which tumour is associated with anti-NMDA receptor encephalitis and how often?","Ovarian teratoma, found in about a third to a half of adult women, so pelvic imaging is needed.",58,6],[278,"How is anti-NMDA receptor encephalitis treated?","Immunotherapy with steroids, immunoglobulin or plasma exchange, plus tumour removal. Early treatment improves outcome, as Titulaer showed.",58,7],[278,"How do patients with anti-NMDA receptor encephalitis respond to antipsychotics?","Poorly. They tolerate antipsychotics badly, and movements should not simply be blamed on the drugs.",58,8],[279,"Which antibody causes faciobrachial dystonic seizures and hyponatraemia in older men?","LGI1. The seizures precede amnesia, as Irani showed, and the disease is rarely paraneoplastic.",58,9],[279,"What syndrome do CASPR2 antibodies cause and which tumour is linked?","Morvan syndrome, with neuromyotonia, severe insomnia, sweating and confusion. Thymoma is often found.",58,10],[279,"Which antibody causes limbic encephalitis with prominent seizures and small cell lung cancer?","GABA-B receptor antibodies. About half of patients have small cell lung cancer.",58,11],[279,"With which tumours are anti-Hu and anti-Ma2 antibodies associated?","Anti-Hu is paraneoplastic and damages sensory nerves. Anti-Ma2 is linked with testicular tumours.",58,12],[279,"What causes stiff person syndrome and what are its features?","Antibodies to glutamic acid decarboxylase. It causes truncal stiffness, spasms and exaggerated startle, often with type 1 diabetes.",58,13],[279,"Which antibodies cause neuromyelitis optica and Lambert-Eaton syndrome respectively?","Aquaporin-4 antibodies cause neuromyelitis optica. Voltage-gated calcium channel antibodies cause Lambert-Eaton syndrome.",58,14],[279,"What are the features of SREAT (Hashimoto's encephalopathy)?","Subacute confusion with hallucinations, myoclonus or seizures and very high anti-TPO antibodies, often with normal thyroid function. It responds to steroids within days.",58,15],[279,"Why cannot SREAT be diagnosed from anti-TPO antibodies alone?","Anti-TPO antibodies are common in the population, so SREAT is a diagnosis of exclusion.",58,16],[279,"Which antibody is linked with psychosis in lupus?","Anti-ribosomal P antibodies, as Bonfa reported in 1987. Anti-dsDNA tracks lupus activity, mainly renal disease.",58,17],[279,"What is PANDAS and what is first-line management?","Sudden OCD or tics in prepubertal children after group A streptococcal infection, described by Swedo in 1998. Standard CBT with exposure and SSRIs is first-line.",58,18],[279,"Is there good evidence for antibiotics, IVIG or tonsillectomy in PANDAS?","No. The causal link is unproven, and only active infection should be treated.",58,19],[279,"What did Benros find about autoimmune disease, infection and schizophrenia risk?","In Danish registers, autoimmune disease raised risk by about 29%, severe infection by about 60%, and both together more than doubled it. This shows association, not cause.",58,20],[282,"What is ghrelin and where is it produced?","A 28 amino acid peptide from oxyntic cells of the stomach fundus. It is the only known circulating hunger hormone.",59,1],[282,"A woman aged 19 with anorexia nervosa and BMI 14 has a raised stomach hunger hormone. Which hormone and what does it suggest?","Ghrelin, which is paradoxically high, suggesting resistance to its hunger signal.",59,2],[282,"What are the two opposing neuron groups of the arcuate nucleus controlling appetite?","POMC neurons promote fullness via melanocortin-4 receptors. NPY/AgRP neurons drive hunger.",59,3],[282,"What is leptin and how does it act on the hypothalamus?","A hormone from fat cells in proportion to fat mass, product of the ob gene cloned in 1994. It activates POMC and inhibits NPY/AgRP neurons.",59,4],[282,"What happens to leptin in fasting, anorexia nervosa and common obesity?","It falls with fasting and is low in anorexia. It is high in common obesity because of leptin resistance.",59,5],[282,"Who benefits from recombinant leptin treatment?","People with rare recessive congenital leptin deficiency. Common obesity does not respond.",59,6],[282,"What is the commonest single-gene cause of severe early-onset obesity?","MC4R variants, often heterozygous, causing constant hunger and accelerated height growth. FTO variants are common but have small effects.",59,7],[283,"What did Cummings show about ghrelin levels around meals?","Ghrelin rises before each meal and falls within an hour of eating. It is low in obesity.",59,8],[283,"Name the main satiety signals from the gut and pancreas.","CCK from duodenal I cells, insulin from pancreatic beta cells and GLP-1 from the gut.",59,9],[283,"What is adiponectin and how does it change with body fat?","A hormone from fat that rises when fat is low and improves insulin sensitivity. It falls with visceral obesity.",59,10],[283,"What thyroid pattern is seen in anorexia nervosa and how is it managed?","Low T3 with normal TSH, the sick euthyroid state. It is adaptive and treated by refeeding, not thyroxine.",59,11],[283,"What are the cortisol, gonadotrophin and growth hormone changes in anorexia nervosa?","Cortisol is raised, LH and FSH are low causing amenorrhoea, and growth hormone is high with low IGF-1, showing GH resistance.",59,12],[283,"What would a high FSH suggest in a woman with amenorrhoea and low weight?","Ovarian failure rather than anorexia nervosa, in which FSH is low.",59,13],[283,"What did Luppino's 2010 meta-analysis find about obesity and depression?","Each raised the later risk of the other by about 50%.",59,14],[283,"Why may visceral fat contribute to depression?","It releases IL-6, TNF-alpha and leptin, lowers adiponectin and regenerates cortisol from cortisone.",59,15],[283,"What did Pillinger find in drug-naive first-episode schizophrenia?","Raised fasting glucose, insulin and insulin resistance, so antipsychotics add to a pre-existing risk.",59,16],[283,"Which antipsychotics cause the most weight gain and through which receptors?","Olanzapine and clozapine, linked to H1 histamine and 5-HT2C receptor blockade in hypothalamic appetite circuits.",59,17],[283,"How does semaglutide cause weight loss and how much was seen in STEP 1?","It is a weekly GLP-1 agonist acting on arcuate POMC cells and the hindbrain and slowing gastric emptying. STEP 1 showed about 15% weight loss.",59,18],[283,"What did insulin resistance predict in Watson's nine-year study?","Three measures of insulin resistance predicted new-onset major depression.",59,19],[284,"A man aged 19 on olanzapine for three months has thirst, polyuria, abdominal pain, drowsiness and urinary glucose and ketones. Diagnosis?","Diabetes mellitus with diabetic ketoacidosis, a medical emergency. Glucose or HbA1c monitoring before and during treatment is essential.",59,20],[286,"A woman aged 31 on lamotrigine and quetiapine has had no periods for three months. What is the first investigation?","A urine or serum pregnancy test, because pregnancy is the commonest cause of secondary amenorrhoea. Prolactin is checked next.",60,1],[286,"What is meant by secondary amenorrhoea in a woman of reproductive age?","Periods that stop after previously being regular. In a woman of reproductive age, pregnancy must be excluded first.",60,2],[286,"After a negative pregnancy test, in what order should secondary amenorrhoea be investigated?","Prolactin next, then thyroid function and androgens, and imaging such as pelvic ultrasound last.",60,3],[286,"How often is GnRH released from the hypothalamus into the portal blood?","In pulses roughly every 60 to 90 minutes, each pulse releasing LH and FSH from the pituitary.",60,4],[286,"What did Knobil show about pulsatile versus continuous GnRH in monkeys?","Pulsed GnRH restored LH and FSH, but a continuous infusion desensitised the pituitary and shut both down.",60,5],[286,"Why does a long-acting GnRH agonist depot lower testosterone after a brief initial rise?","Continuous stimulation desensitises pituitary GnRH receptors, so LH and FSH fall and sex hormones are switched off.",60,6],[286,"Which GnRH pulse frequency favours LH release and which favours FSH?","Fast pulses favour LH, while slow pulses favour FSH.",60,7],[286,"Which peptide drives GnRH neurons, and what happens when its receptor GPR54 is lost?","Kisspeptin from arcuate nucleus neurons drives GnRH. Loss of GPR54 causes hypogonadotropic hypogonadism, so puberty never starts.",60,8],[286,"Why do people with Kallmann syndrome have absent puberty and loss of smell?","GnRH neurons fail to migrate from the olfactory placode to the hypothalamus, so GnRH is lacking and smell development is affected.",60,9],[287,"How does a raised prolactin from an antipsychotic cause missed periods?","Prolactin suppresses kisspeptin neurons in the hypothalamus, so GnRH pulses fall and LH, FSH and oestradiol drop. The ovaries themselves are normal.",60,10],[287,"What is the typical LH to FSH pattern in polycystic ovary syndrome and why?","GnRH pulses stay fast, so LH is high relative to FSH. LH drives androgen production by ovarian theca cells.",60,11],[287,"How do LH and FSH differ between polycystic ovary syndrome and ovarian failure?","In PCOS LH is high relative to FSH, whereas in ovarian failure FSH rises and oestrogen falls.",60,12],[287,"A man aged 28 stops injecting anabolic steroids and becomes low in mood and tired. What explains this?","The steroids suppressed his own GnRH, LH and FSH by negative feedback, shrinking the testes. On stopping, low testosterone causes low mood, fatigue and loss of libido.",60,13],[287,"What did Bloch's hormone add-back and withdrawal study show about postpartum depression?","Five of eight women with past postpartum depression became depressed and none of eight controls did, despite identical hormone levels. The key factor is sensitivity to the hormone change.",60,14],[287,"Why does depression risk rise during the perimenopause?","Follicles run out, so FSH rises and oestradiol swings widely. Freeman found depressed mood tracked these hormonal changes, even in women with no prior depression.",60,15],[288,"A woman aged 49 is in the menopausal transition. Which falling follicle peptide lets FSH rise?","Inhibin B, made by granulosa cells, which normally acts as a selective brake on pituitary FSH.",60,16],[290,"How can a single neurexin gene produce hundreds of different synaptic proteins?","By alternative splicing of pre-mRNA, in which exons are kept or skipped in different combinations to make protein isoforms.",61,1],[290,"How many base pairs and protein-coding genes does the human genome contain?","About 3.1 billion base pairs and about 20 000 protein-coding genes, with exons forming only 1 to 2% of the genome.",61,2],[291,"Which enzymes load each tRNA with its amino acid and so truly read the genetic code?","The aminoacyl-tRNA synthetases.",61,3],[291,"What is post-translational modification? Give two examples.","Chemical change to a finished protein, such as phosphorylation by kinases and glycosylation in the Golgi.",61,4],[291,"Where does the non-disjunction behind most trisomy 21 occur?","In maternal meiosis I. Eggs are held in this stage from before birth, so risk rises with maternal age.",61,5],[291,"What is the difference between a transition and a transversion?","A transition swaps a purine for a purine or a pyrimidine for a pyrimidine. A transversion swaps a purine for a pyrimidine or the reverse, such as G to T.",61,6],[291,"What happens when five bases are deleted from an exon?","A frameshift, because the loss is not a multiple of three. Every later codon is misread and an early stop codon usually appears.",61,7],[291,"Two healthy carriers of phenylketonuria plan a child. What is the risk in each pregnancy?","One in four, as PKU is autosomal recessive. A healthy sibling of an affected child has a 2 in 3 chance of being a carrier.",61,8],[291,"How is mitochondrial DNA inherited, and what affects the severity of mitochondrial disease?","It passes from the mother to all her children. Severity depends on heteroplasmy, the mix of faulty and normal copies.",61,9],[291,"What is the liability-threshold model of inheritance in schizophrenia and autism?","Many genes and environmental factors add to a hidden liability, and illness appears once the total crosses a threshold.",61,10],[291,"What are the lifetime risks of schizophrenia in the general population and in first-degree relatives?","About 1% in the general population and about 10% in first-degree relatives.",61,11],[291,"What are the MZ and DZ twin concordance rates for schizophrenia?","About 45 to 50% in identical twins and about 10 to 15% in non-identical twins.",61,12],[291,"What did Heston's adoption study show about schizophrenia?","Schizophrenia occurred only in adopted-away children of mothers with the illness, supporting a genetic effect separate from upbringing.",61,13],[291,"What LOD scores confirm and exclude linkage?","A LOD score above 3 (odds of 1000 to 1) supports linkage, and below minus 2 excludes it. Linkage finds a region, not the mutation.",61,14],[291,"How does linkage differ from linkage disequilibrium?","Linkage tracks a marker with an illness through families. Linkage disequilibrium is nearby alleles travelling together across a population, so a GWAS hit may only tag the causal variant.",61,15],[291,"What is the difference between gene tracking and direct gene analysis?","Gene tracking uses linked markers to infer who inherited the faulty chromosome, while direct gene analysis reads the mutation itself.",61,16],[291,"A harsh parenting style is provoked by a difficult toddler's temperament. What type of gene-environment correlation is this?","Evocative gene-environment correlation, where a child's genetically influenced traits draw particular responses from others.",61,17],[291,"How do microRNAs differ from small interfering RNAs?","MicroRNAs are about 22 bases long, processed by Drosha, DGCR8 and Dicer, and pair loosely to tune many mRNAs via RISC. siRNA pairs perfectly with one mRNA and destroys it.",61,18],[292,"What are the approximate heritabilities of schizophrenia, bipolar disorder, autism, ADHD and depression?","About 80%, 80 to 85%, 80%, 75% and 37% respectively.",61,19],[292,"Which gene-environment interaction did Caspi report for antisocial behaviour in maltreated boys?","Maltreated boys with the low-activity MAOA variant, an X-linked gene, became more antisocial as adults than those with the high-activity form.",61,20],[295,"What p value threshold defines genome-wide significance in a GWAS?","p below 5 x 10^-8, which is 0.05 corrected for about a million tests. A value near 10^-6 is only suggestive.",62,1],[295,"What is a single nucleotide polymorphism, and when is it called common?","A one-letter DNA difference between people. It is common when more than 1% of people carry it.",62,2],[295,"What is the typical odds ratio of a common risk SNP for a psychiatric disorder?","About 1.05 to 1.2 per allele, so one SNP tells an individual almost nothing and studies need tens of thousands of people.",62,3],[295,"What is the winner's curse in genetic association studies?","The tendency for first reports to overstate the size of a variant's effect.",62,4],[295,"Why does a GWAS hit often not identify the causal variant itself?","Most hits lie outside coding DNA and simply tag a nearby causal variant through linkage disequilibrium.",62,5],[296,"How many schizophrenia loci did the PGC3 study report in 2022?","287 loci, up from 108 in 2014, enriched for genes used at synapses.",62,6],[296,"Where is the strongest schizophrenia GWAS signal and what gene explains much of it?","The MHC on chromosome 6. Higher copy number of complement C4A increases risk, plausibly through more synaptic pruning by microglia.",62,7],[296,"Which antipsychotic drug target and which glutamate genes are schizophrenia GWAS hits?","DRD2 is a hit, as are glutamate genes such as GRIN2A and GRM3. COMT, DISC1 and NRG1 are not.",62,8],[296,"What is missing heritability in schizophrenia?","The gap between twin heritability of about 80% and SNP heritability of about 24%. Rare variants and imperfect tagging fill part of it.",62,9],[296,"In LD score regression, what do the slope and the intercept indicate?","True polygenic signal raises the slope, while confounding such as population stratification raises the intercept.",62,10],[296,"What is the genetic correlation between schizophrenia and bipolar disorder, and with autism?","About 0.7 between schizophrenia and bipolar disorder, but only about 0.2 between schizophrenia and autism.",62,11],[296,"How much of schizophrenia liability does a polygenic risk score explain?","About 7%, so it is a research tool rather than a clinical test.",62,12],[296,"Why do polygenic scores built in European samples perform worse in people of African ancestry?","Linkage disequilibrium patterns and allele frequencies differ, so the fault lies with the tool, not lower heritability.",62,13],[296,"What does the Met allele of BDNF Val66Met do?","It reduces activity-dependent release of BDNF, and carriers have slightly smaller hippocampi.",62,14],[296,"How much does APOE e4 raise the risk of late-onset Alzheimer's disease?","About 3-fold with one copy and 8 to 15-fold with two. Even two copies raise risk without making dementia certain.",62,15],[296,"What is the DRD4 exon III 7-repeat allele associated with?","A small association with ADHD, with an odds ratio of about 1.3, and with novelty seeking.",62,16],[297,"In COMT Val158Met, which allele clears prefrontal dopamine faster and what follows?","Val works 3 to 4 times faster, so Val/Val people do slightly worse on working memory. Met is the slow, high-dopamine allele.",62,17],[297,"Why does COMT matter more for dopamine clearance in prefrontal cortex than in the striatum?","The prefrontal cortex has few dopamine transporters, so COMT does more of the clearing work there.",62,18],[299,"A boy aged 8 has learning disability, autistic features, a long face and large ears. What genetic finding is likely?","Fragile X syndrome: a CGG repeat of over 200 in FMR1 on the X chromosome, which methylates and silences the gene.",63,1],[299,"What does a fragile X premutation of 55 to 200 CGG repeats cause?","Early menopause in women and fragile X-associated tremor and ataxia syndrome (FXTAS) in older men. It expands to a full mutation through the mother.",63,2],[299,"What did the SCHEMA study find about rare variants in schizophrenia?","In about 24 000 cases and 97 000 controls, ultra-rare protein-truncating variants in 10 genes, including SETD1A and GRIN2A, greatly raised risk.",63,3],[300,"Which gene is implicated in schizophrenia by both GWAS and the SCHEMA rare-variant study?","GRIN2A, which encodes the GluN2A subunit of the NMDA receptor.",63,4],[300,"Name the main copy number variants that raise schizophrenia risk.","22q11.2 deletion, 1q21.1, 15q13.3, 3q29, 16p11.2 duplication and NRXN1 deletion. Each also raises the risk of autism and learning disability.",63,5],[300,"What are the causes of Down syndrome and their approximate proportions?","Non-disjunction about 95%, Robertsonian translocation about 4% and mosaicism about 1%.",63,6],[300,"A woman aged 24 has had two pregnancies with Down syndrome. What is the likely cause?","A Robertsonian translocation, often between chromosomes 14 and 21, in a healthy parent carrier with 45 chromosomes, not maternal age.",63,7],[300,"Why do people with Down syndrome develop Alzheimer's disease early?","Chromosome 21 carries APP, so three copies cause amyloid plaques by about age 40 and early dementia.",63,8],[300,"How do Edwards, Patau and Klinefelter syndromes differ?","Edwards is trisomy 18 with clenched overlapping fingers and rocker-bottom feet. Patau is trisomy 13 with cleft lip and extra digits. Klinefelter is 47,XXY with tall stature, small testes and a Barr body.",63,9],[300,"What are the features of 22q11.2 deletion syndrome and how often does psychosis develop?","Cleft palate and heart defects with learning problems. About 25% develop psychosis.",63,10],[300,"What are the key features of Williams and Smith-Magenis syndromes?","Williams (7q11.23, elastin gene) causes supravalvular aortic narrowing, high calcium and overfriendliness. Smith-Magenis (17p11.2) causes self-hugging, nail pulling and an inverted melatonin rhythm.",63,11],[300,"How do imprinting defects at 15q11-13 cause Prader-Willi and Angelman syndromes?","Loss of the paternal 15q11-13 causes Prader-Willi syndrome. Loss of maternal UBE3A causes Angelman syndrome, with laughter, seizures and absent speech.",63,12],[300,"What is anticipation in genetic disorders?","Repeat expansions that grow between generations, giving earlier onset or more severe illness.",63,13],[300,"What are the Huntington's disease CAG repeat ranges?","26 or fewer is normal, 27 to 35 intermediate, 36 to 39 reduced penetrance and 40 or more full penetrance. Juvenile cases usually have over 60.",63,14],[300,"Through which parent do Huntington's and fragile X repeats mainly expand?","Huntington's CAG repeats grow mostly through the father, whereas fragile X CGG repeats grow through the mother.",63,15],[300,"Which repeat causes myotonic dystrophy, and from which parent does the congenital form come?","A CTG repeat expansion. The floppy newborn congenital form is inherited from the mother.",63,16],[300,"A girl aged 2 loses speech and hand use after normal early development and wrings her hands. What is the diagnosis?","Rett syndrome, caused by a usually new MECP2 mutation on Xq28, with X-linked dominant inheritance and slowed head growth.",63,17],[300,"A boy aged 4 bites his lips and fingers and has dystonia and high uric acid. What is the diagnosis?","Lesch-Nyhan syndrome, an X-linked recessive deficiency of the enzyme HPRT.",63,18],[300,"Which genes cause autosomal dominant early-onset Alzheimer's disease?","APP, PSEN1 and PSEN2.",63,19],[301,"A woman aged 26 with overeating and mild learning disability has two maternal copies of chromosome 15. What is the diagnosis and psychiatric risk?","Prader-Willi syndrome due to maternal uniparental disomy, which carries a high risk of affective or cycloid psychosis.",63,20],[304,"Which blots detect DNA, RNA and protein respectively?","A Southern blot detects DNA, a Northern blot detects RNA and a Western blot detects protein, all using gel separation, membrane transfer and a probe.",64,1],[304,"RNA from post-mortem cortex is run on a gel, transferred to a membrane and probed. Which technique is this?","A Northern blot, which detects RNA.",64,2],[304,"What do restriction enzymes recognise and where do they come from?","They come from bacteria and cut DNA at short palindromic sequences that read the same on both strands.",64,3],[304,"A variant abolishes a restriction enzyme cut site, producing a longer fragment. What type of marker is this?","A restriction fragment length polymorphism (RFLP), the first DNA marker, later replaced by microsatellites.",64,4],[304,"What is molecular cloning in molecular genetics?","Inserting a DNA fragment into a plasmid vector and copying it inside bacteria.",64,5],[304,"How does a gene probe find its target sequence?","By hybridisation, where a labelled cloned sequence base-pairs with its complementary DNA or RNA.",64,6],[304,"What does the polymerase chain reaction do?","It amplifies one DNA target millions of times through repeated cycles of heating, primer binding and extension by a heat-stable polymerase.",64,7],[305,"What is the resolution of a karyotype compared with a chromosomal microarray?","A karyotype detects only changes over about 5 to 10 Mb, while a chromosomal microarray detects CNVs down to about 50 to 100 kb.",64,8],[305,"What is the first-tier genetic test for a boy aged 6 with unexplained learning disability and autism?","A chromosomal microarray, which scans the whole genome for copy number variants.",64,9],[305,"When is FISH useful and why is it not a screening test?","FISH uses one labelled probe to answer one question, such as whether a 22q11.2 deletion is present. It detects nothing outside that target.",64,10],[305,"How does whole exome sequencing differ from whole genome sequencing?","The exome covers only protein-coding exons, about 1 to 2% of the genome. Whole genome sequencing reads nearly all 3 billion bases, including introns, regulatory regions and structural changes.",64,11],[305,"What is Sanger sequencing used for?","Reading one gene at a time, especially to confirm a known variant.",64,12],[305,"How should a variant of uncertain significance from large-scale sequencing be handled?","It should not be used to guide clinical care.",64,13],[305,"What are the advantages of RNA sequencing over an expression microarray?","RNA sequencing counts every read, finds new transcripts and splice forms and has a wide dynamic range. Microarrays use fixed probes, miss new transcripts and saturate at high levels.",64,14],[305,"Why is single-nucleus RNA sequencing used on frozen post-mortem brain?","It assigns expression changes to individual cell types rather than a bulk mixture, and nuclei survive freezing whereas whole neurons do not.",64,15],[305,"How does proteomics identify thousands of proteins in a sample?","Proteins are cut into peptides and identified by mass spectrometry, which weighs them by mass-to-charge ratio. mRNA levels predict protein only moderately.",64,16],[305,"What does metabolomics measure and what is its main limitation?","Small molecules up to about 1500 daltons, using mass spectrometry or NMR. It is closest to the phenotype but shifts with diet and drugs.",64,17],[305,"What are eQTLs, mQTLs and pQTLs?","Variants whose genotype predicts mRNA level, DNA methylation and protein level respectively.",64,18],[306,"How can eQTL mapping identify the gene acted on by a non-coding GWAS hit?","If the GWAS signal and an eQTL share the same causal variant, that gene is the likely target, which need not be the nearest gene.",64,19],[308,"What is pleiotropy? Give a psychiatric example.","One gene or variant affecting several unrelated traits, such as the 22q11.2 deletion raising risk of schizophrenia, autism, ADHD and anxiety plus heart and palate defects.",65,1],[308,"What is the difference between genotype and phenotype, and how well do they match in psychiatry?","Genotype is the genetic make-up and phenotype is what can be observed or measured. In psychiatry they match only loosely.",65,2],[308,"What does a genetic correlation of about 0.7 between schizophrenia and bipolar disorder imply?","Much of their genetic risk is shared, so genes do not respect diagnostic boundaries.",65,3],[309,"What is locus heterogeneity? Give an example.","The same disorder arising from different genes, such as early-onset familial Alzheimer's from APP, PSEN1 or PSEN2.",65,4],[309,"On which chromosomes are APP, PSEN1 and PSEN2, and which is the commonest cause of familial early-onset Alzheimer's?","APP is on chromosome 21, PSEN1 on 14 and PSEN2 on 1. PSEN1 is the commonest cause.",65,5],[309,"What is allelic heterogeneity in genetic disorders?","Many different mutations within the same gene causing the same disorder, as with the hundreds of known PSEN1 mutations.",65,6],[309,"What is a phenocopy and why does it matter?","An environmental cause that mimics a genetic disorder in someone without the family variant, such as alcohol-related memory loss in a PSEN1 family. It weakens linkage studies and should prompt a search for treatable causes.",65,7],[309,"What is meant by penetrance of a genetic variant?","The proportion of carriers of a variant who actually show the trait.",65,8],[309,"What proportion of adults with the 22q11.2 deletion develop schizophrenia?","About 1 in 4, so most carriers never do, illustrating incomplete penetrance.",65,9],[309,"What is variable expressivity, and what is the classic example?","The same mutation causing different severity in affected relatives. In NF1, a mother may have only cafe-au-lait patches while her son has a plexiform neurofibroma and learning difficulties.",65,10],[309,"What is NF1 and what proportion of cases are new mutations?","An autosomal dominant disorder of the neurofibromin tumour suppressor gene on 17q11.2. About half of cases are new mutations.",65,11],[309,"What is an endophenotype in psychiatric genetics?","A measurable, heritable trait lying between genes and diagnosis that is easier to map than the illness itself. It is a research marker, not a diagnostic test.",65,12],[309,"What are the Gottesman and Gould criteria for an endophenotype?","It is associated with the illness, heritable, state-independent, co-segregates with illness in families and is more common in unaffected relatives than in the general population.",65,13],[309,"What did Holzman find about smooth pursuit eye movements in schizophrenia?","Jerky smooth pursuit occurs in schizophrenia and in about half of well first-degree relatives.",65,14],[309,"What is P50 sensory gating and which gene did Freedman link to its failure?","The brain normally damps its response to the second of two clicks 500 ms apart. Failed gating was linked to CHRNA7, the alpha-7 nicotinic receptor gene on chromosome 15.",65,15],[309,"Why might people with schizophrenia smoke heavily, according to P50 gating research?","Nicotine briefly restores P50 sensory gating via alpha-7 nicotinic receptors.",65,16],[309,"What is the Research Domain Criteria framework?","An NIMH research framework from 2010 crossing dimensional domains with units of analysis from genes to self-report. It is not a clinical diagnostic system and does not replace ICD-11.",65,17],[309,"What did the B-SNIP study find about biotypes in psychosis?","Grouping patients by cognition, EEG and eye movements produced three biotypes that cut across diagnoses.",65,18],[309,"Were the depression connectivity biotypes said to predict rTMS response supported?","No. A reanalysis found the clusters unstable and not clearly distinct.",65,19],[310,"A man aged 72 carries 37 CAG repeats in HTT and has no signs of Huntington's disease. What concept does this show?","Incomplete penetrance, since 36 to 39 repeats may or may not cause disease in a normal lifespan.",65,20],[313,"What is meant by the term epigenetics?","Changes in gene expression without any change in DNA sequence, which can persist through cell division and are partly shaped by the environment.",66,1],[313,"Why is a CpG cytosine to thymine change not epigenetic?","It is a point mutation that alters the DNA sequence itself, so it is genetic.",66,2],[313,"What are the three main epigenetic mechanisms?","DNA methylation, histone modification and non-coding RNAs such as microRNAs.",66,3],[313,"What is the usual effect of methylating a gene promoter at CpG sites?","It usually silences the gene.",66,4],[313,"How do histone acetylation and histone deacetylases affect transcription?","Acetylation loosens chromatin and increases transcription. HDACs remove acetyl groups, tightening chromatin and reducing transcription.",66,5],[314,"What do the histone marks H3K4me3, H3K27ac and H3K27me3 indicate?","H3K4me3 marks active promoters, H3K27ac marks active enhancers and H3K27me3 marks repressed genes.",66,6],[314,"What is X inactivation and how does it differ from genomic imprinting?","XIST randomly silences one X in each female cell, forming a Barr body and making carriers mosaic. Imprinting silences a gene copy by parent of origin, not at random.",66,7],[314,"What did Meaney find in pups raised by high licking and grooming rat mothers?","Less methylation of the hippocampal glucocorticoid receptor promoter, more receptors and tighter stress hormone feedback. The effect followed the rearing mother.",66,8],[314,"Could the low-care epigenetic pattern in Meaney's rats be reversed in adulthood?","Yes, an HDAC inhibitor reversed the low-care pattern in adult rats.",66,9],[314,"What did Klengel show about FKBP5, childhood abuse and PTSD?","In risk-allele carriers, abuse removed methylation in FKBP5 intron 7, making FKBP5 overactive, impairing cortisol feedback and raising PTSD risk.",66,10],[314,"What were the main findings in people conceived during the Dutch Hunger Winter?","About double the risk of schizophrenia and lower IGF2 methylation six decades later.",66,11],[314,"What is an epigenetic clock and what does it estimate?","A model estimating biological age from methylation at several hundred CpG sites. Severe adversity is linked to accelerated ageing on it, which differs from telomere length.",66,12],[314,"How does valproate act on chromatin?","It inhibits HDACs, keeping histones acetylated so chromatin opens and transcription increases. This may add to its mood effect and its teratogenicity.",66,13],[314,"What is the evidence that psychotherapy changes epigenetic marks?","A small study of combat veterans found methylation changes in stress genes such as FKBP5 in those who improved with prolonged exposure therapy. It needs replication.",66,14],[314,"If a pregnant woman is exposed to famine, which generation is the first truly unexposed one?","The great-grandchildren, because the fetus and its germ cells are exposed too. Effects in children or grandchildren are only intergenerational.",66,15],[314,"What is the current evidence for transgenerational epigenetic inheritance in humans?","It is shown in some rodent studies but contested in humans, where shared environment and culture confound findings.",66,16],[314,"After bisulphite treatment, how are methylated and unmethylated cytosines read?","Unmethylated cytosine becomes uracil and reads as T. Methylated cytosine resists conversion and still reads as C.",66,17],[314,"How do ChIP-seq and ATAC-seq differ?","ChIP-seq uses an antibody to pull down DNA bound to one histone mark. ATAC-seq uses Tn5 transposase to map open chromatin without antibodies and works on single nuclei.",66,18],[314,"Why should methylation differences in blood be interpreted with caution in psychiatry?","Methylation is tissue and cell-type specific, so blood is not brain, and differences may reflect cell composition, smoking or medication.",66,19],[318,"What is the main contribution of a transgenic or knockout mouse study?","It implicates the molecular pathway through which a gene produces a phenotype. It cannot show how common a variant is in patients.",67,1],[318,"Which questions do twin, linkage or association and transgenic studies answer?","Twin studies ask whether genes matter, linkage and association ask where they are, and transgenic models ask how they act.",67,2],[318,"What is the difference between a transgenic and a knockout mouse?","A transgenic mouse carries an added or altered gene, such as a human risk variant, while a knockout mouse has a gene removed.",67,3],[319,"What is the natural role of CRISPR in bacteria?","Spacers copied from viruses are stored between the repeats as a memory of infection, and Cas proteins use them to cut returning viruses.",67,4],[319,"What does Cas9 do when its guide RNA finds a matching DNA sequence?","It cuts both strands, making a double-strand break.",67,5],[319,"Why did CRISPR replace zinc finger nucleases and TALENs?","Retargeting needs only a new guide RNA, so several genes can be edited at once, whereas older tools need a new protein for each target. CRISPR still makes some off-target cuts.",67,6],[319,"Which DNA repair pathways follow a Cas9 cut, and how do they differ?","Non-homologous end joining is fast and error-prone, leaving insertions and deletions that knock genes out. Homology-directed repair is accurate but works mainly in dividing cells, not neurons.",67,7],[319,"What are CRISPR interference and CRISPR activation?","Dead Cas9, which binds without cutting, is fused to a repressor to switch a gene off or to an activator to switch it on, without changing the sequence.",67,8],[319,"How does base editing differ from standard Cas9 editing?","A deaminase joined to a Cas9 nickase changes one letter without a double-strand break or donor template. Prime editing can write small new sequences.",67,9],[319,"How do antisense oligonucleotides such as nusinersen differ from CRISPR?","They bind mRNA rather than DNA, wear off and need repeated intrathecal doses. Nusinersen is licensed for spinal muscular atrophy.",67,10],[319,"What happened to the huntingtin-lowering antisense drug tominersen?","Its phase 3 dosing was stopped in 2021.",67,11],[319,"Why is functional validation needed for GWAS hits?","Most hits are non-coding and tagged by many correlated variants, so the top variant is not always causal.",67,12],[319,"Why are isogenic stem cell-derived neuron lines useful for testing a risk variant?","The lines differ only at the variant inserted by CRISPR, so any difference must be due to that variant.",67,13],[319,"What does a pooled CRISPR screen in iPSC-derived neurons do?","It disrupts thousands of genes, one per cell, to find genes controlling traits such as survival under stress.",67,14],[319,"What was the first licensed CRISPR therapy in the UK and how does it work?","Casgevy (exa-cel), authorised by the MHRA in November 2023 for sickle cell disease and beta-thalassaemia. The patient's own stem cells are edited outside the body to restore fetal haemoglobin.",67,15],[319,"What is the main obstacle to gene editing in the adult brain?","Delivering the editing machinery across the blood-brain barrier.",67,16],[319,"How does somatic editing differ from germline editing, and what is the UK legal position?","Somatic editing affects only the treated person, while germline edits pass to future generations. Implanting a genetically altered embryo is prohibited under the Human Fertilisation and Embryology Act, with only licensed research allowed.",67,17],[320,"Sixty non-coding variants are tested together, each with either allele, for effects on a reporter gene. Which method is this?","A massively parallel reporter assay (MPRA), which finds variants that alter gene expression in a test system.",67,18],[323,"Why can grouping people by a genetic variant give stronger causal evidence than observational studies?","Alleles are allocated randomly at conception, so genotype groups resemble trial arms, reducing confounding. Fixed genotype also rules out reverse causation.",68,1],[323,"What is mendelian randomisation in causal inference?","Using genetic variants that affect an exposure as a proxy for it to test whether the exposure causes an outcome.",68,2],[323,"What are confounding and reverse causation in observational studies?","Confounding is a third factor linked to both exposure and outcome. Reverse causation is the illness changing the exposure.",68,3],[324,"What are the three core assumptions of mendelian randomisation?","Relevance (the variant affects the exposure), independence (no shared causes with the outcome) and the exclusion restriction (the variant acts only through the exposure).",68,4],[324,"What F statistic indicates a weak instrument in mendelian randomisation?","An F statistic below 10.",68,5],[324,"How does population stratification threaten mendelian randomisation?","Confounding by ancestry violates the independence assumption.",68,6],[324,"A variant that raises CRP also changes body weight by another pathway. Which assumption is violated?","The exclusion restriction, through horizontal pleiotropy, the commonest threat to mendelian randomisation.",68,7],[324,"How do one-sample and two-sample mendelian randomisation differ?","One-sample measures genotype, exposure and outcome in the same people. Two-sample uses summary statistics from separate GWAS of the exposure and the outcome, ideally of shared ancestry.",68,8],[324,"In MR-Egger, what do a non-zero intercept and the slope indicate?","A non-zero intercept suggests directional horizontal pleiotropy, and the slope gives the pleiotropy-adjusted causal estimate.",68,9],[324,"What biases does within-family mendelian randomisation remove?","Population stratification, assortative mating and dynastic effects of parental genotype. Estimates for education often shrink.",68,10],[324,"What is bidirectional mendelian randomisation used to test?","Running the analysis in both directions to test whether each trait causes the other.",68,11],[324,"What did ALDH2 mendelian randomisation studies in East Asia show about alcohol and stroke?","Carriers of the flushing allele drink less and have lower blood pressure and fewer strokes, with little effect in women who drink little. Alcohol itself raises stroke risk and moderate drinking is unlikely to protect.",68,12],[324,"What has mendelian randomisation shown about cannabis and schizophrenia?","Strong evidence that schizophrenia liability increases cannabis use, with weaker evidence for cannabis causing schizophrenia.",68,13],[324,"What has mendelian randomisation suggested about education and Alzheimer's disease?","Genetically predicted longer education is linked to lower Alzheimer's risk.",68,14],[324,"What is drug-target mendelian randomisation and how was it validated with statins?","It uses variants in a drug target gene as a proxy for lifelong drug action. HMGCR variants reproduce the small rise in diabetes risk seen with statins.",68,15],[324,"What does the IL6R variant finding mean for treating depression?","Carriers have lower depression risk, supporting IL-6 signalling as a causal target, but it does not justify prescribing tocilizumab for depression.",68,16],[324,"How does drug-target mendelian randomisation differ from pharmacogenetics?","Drug-target MR asks whether a target causes disease, while pharmacogenetics concerns how genes alter drug handling and dosing.",68,17],[327,"A man aged 23 whose father has schizophrenia asks about a commercial polygenic score. How much liability do current scores explain?","About 7%, too little to predict one person's illness, and no guideline recommends them in psychiatric practice.",69,1],[327,"What is a polygenic risk score?","The sum of common risk alleles a person carries, each weighted by its GWAS effect size.",69,2],[327,"What does genetic counselling involve for patients and families?","Accurate information on risks and options combined with psychological support, given in a non-directive way.",69,3],[327,"A woman aged 35 asks her genetic counsellor what she would do. How should the counsellor respond?","Stay non-directive by helping her explore her own values and circumstances to reach her own decision. Saying what most people choose is still directive.",69,4],[327,"What are the key features of the Huntington's predictive testing protocol?","More than one pre-test counselling session, time to reflect, a chosen supporter, the result given in person with planned follow-up, and freedom to stop at any stage.",69,5],[327,"A mother asks for her well daughter aged 14 to have a Huntington's predictive test. What should happen?","Defer testing until the child can make her own adult decision, as children are not tested for adult-onset disease without medical benefit. Offer support meanwhile.",69,6],[327,"What do CAG repeats of 27 to 35, 36 to 39 and 40 or more mean in Huntington's testing?","27 to 35 is intermediate, 36 to 39 is reduced penetrance and 40 or more is fully penetrant.",69,7],[328,"A woman aged 30 at 10 weeks of pregnancy wants a no-risk blood test for trisomy 21. Which test fits?","Cell-free DNA screening of placental DNA in maternal blood, from about 10 weeks. A higher-chance result must be confirmed by CVS or amniocentesis.",69,8],[328,"Is a high-chance cell-free DNA or nuchal translucency result a diagnosis?","No, both are screening tests. Confirmation needs chorionic villus sampling or amniocentesis, partly because placental mosaicism can give false positives.",69,9],[328,"When are chorionic villus sampling and amniocentesis performed, and what is their miscarriage risk?","CVS at 11 to 14 weeks and amniocentesis from 15 weeks. Both give a diagnostic fetal karyotype with a miscarriage risk under 0.5%.",69,10],[328,"Which genetic test is first-tier for unexplained learning disability, autism or birth defects?","A chromosomal microarray to detect copy number variants, including in psychosis with these features.",69,11],[328,"How should a novel rare variant with no supporting evidence be handled?","It is a variant of uncertain significance and must not guide clinical decisions or predictive testing of relatives.",69,12],[328,"What is cascade testing and when is it offered?","Testing relatives for the same variant once a pathogenic result is found, using ACMG grading from benign to pathogenic.",69,13],[328,"How are NHS genomic services organised in England?","The NHS Genomic Medicine Service began in 2018 after the 100 000 Genomes Project. The National Genomic Test Directory sets eligibility, and seven Genomic Laboratory Hubs do the testing.",69,14],[328,"Are direct-to-consumer genetic tests valid for clinical diagnosis?","No, tests sold straight to the public are not valid for diagnosis.",69,15],[328,"What is UK Biobank and what consent model does it use?","About 500 000 adults aged 40 to 69 whose DNA is linked to health data, with broad consent for future research and the right to withdraw.",69,16],[328,"What is healthy volunteer bias in UK Biobank?","Only about 5% of those invited took part, and they are healthier and wealthier than average, so prevalence estimates do not generalise.",69,17],[328,"Why do polygenic scores perform worse in people of African ancestry?","Most were built in European samples, and allele frequencies and linkage disequilibrium patterns differ.",69,18],[331,"By about which day after conception do the anterior and posterior neuropores normally close?","The anterior neuropore closes at about day 25 and the posterior neuropore at about day 28.",70,1],[331,"A woman aged 29 starts folic acid at 6 weeks of pregnancy. Why is this too late to prevent a neural tube defect?","The neural tube has already shut by about day 28, often before the pregnancy is known. Folic acid therefore needs to start before conception.",70,2],[331,"Which defects result from failed closure at the front and at the back of the neural tube?","Failure at the front causes anencephaly. Failure at the back causes spina bifida.",70,3],[331,"By how much did folic acid reduce repeat neural tube defects in the 1991 MRC Vitamin Study?","It reduced the risk of another affected pregnancy by about 72% in women who had already had an affected baby.",70,4],[331,"Which structures develop from the telencephalon?","The cerebral cortex, hippocampus, olfactory bulb and corpus striatum (caudate and putamen).",70,5],[331,"Which structures develop from the diencephalon?","The thalamus, hypothalamus, pineal gland, retina and posterior pituitary.",70,6],[332,"Which primary brain vesicle does not divide, and which structures does it form?","The mesencephalon (midbrain). Its tectum forms the colliculi and its tegmentum holds the red nucleus, substantia nigra and third nerve nuclei.",70,7],[332,"What do the metencephalon and myelencephalon form, and where does the Dandy-Walker malformation arise?","The metencephalon forms the pons and cerebellum and the myelencephalon forms the medulla. Dandy-Walker affects the cerebellum, so it is a metencephalon fault.",70,8],[332,"Name the main derivatives of the neural crest.","Peripheral nerve ganglia, Schwann cells, the adrenal medulla, melanocytes and the enteric nervous system.",70,9],[332,"Where do microglia come from, unlike neurons, astrocytes and oligodendrocytes?","Microglia come from yolk-sac cells. Neurons, astrocytes and oligodendrocytes come from the neural tube.",70,10],[332,"How do cortical neurons reach their final layer, and in what order are the layers built?","They migrate from the ventricular zone along radial glia, with reelin from Cajal-Retzius cells telling them where to stop. The cortex is built inside out, so the deepest layers form first.",70,11],[332,"By when is cortical neuronal migration largely complete, and what results if it fails?","By about 24 to 26 weeks of gestation. Failure gives heterotopia or lissencephaly, which cause seizures and learning disability.",70,12],[332,"What proportion of developing neurons die by apoptosis, and what did Levi-Montalcini show controls this?","About half die. Neurons compete for limited nerve growth factor made by their target, and those that fail to get enough die.",70,13],[332,"When does synaptic density peak, and how much is removed by later pruning?","It peaks in the first 2 years, at about 8 months in visual cortex. About 40% of synapses are then pruned through childhood and adolescence.",70,14],[332,"When does cortical folding begin and when is it near adult form?","The first sulci appear at about 16 weeks of gestation and folding is near adult by about age 2.",70,15],[332,"In what order does grey matter mature according to Gogtay, and which region matures last?","It matures from back to front, with the dorsolateral prefrontal cortex last, in the twenties. Myelination also continues into the twenties.",70,16],[332,"How does Casey's dual systems model explain teenage risk-taking, and when is the gap widest?","Reward circuits such as the ventral striatum mature early at puberty, while prefrontal control matures later. The gap is widest at about age 15.",70,17],[332,"What brain changes come with normal ageing, and which regions are affected most?","Volume loss speeds up after about age 60, mostly in prefrontal cortex and hippocampus, with wider ventricles and more white matter hyperintensities. Regions that matured last are lost first.",70,18],[333,"A boy aged 2 has severe epilepsy, a smooth cortex on MRI and a LIS1 mutation. Which developmental step failed?","Neuronal migration along radial glia, giving lissencephaly.",70,19],[336,"Who proposed the neurodevelopmental hypothesis of schizophrenia, and in what year?","Daniel Weinberger and, separately, Robin Murray and Shon Lewis, in 1987.",71,1],[336,"How did Weinberger explain why schizophrenia typically begins in early adulthood?","An early lesion stays silent until the dorsolateral prefrontal cortex matures and is needed in early adult life.",71,2],[336,"How did Kraepelin's view of schizophrenia differ from the neurodevelopmental hypothesis?","Kraepelin saw it as a progressive degenerative brain disease, like dementia. The neurodevelopmental view places a fixed fault before or around birth.",71,3],[336,"Which childhood and first-episode findings support a neurodevelopmental origin of schizophrenia?","Mild motor and learning delays in childhood and enlarged ventricles already present at the first episode.",71,4],[336,"Why does the absence of gliosis in post-mortem schizophrenia brains suggest early damage?","Gliosis is astrocyte scarring after damage in later life. Its absence suggests the lesion happened very early in development.",71,5],[336,"What did Feinberg propose in 1982 about the cause of schizophrenia?","That it results from excessive synaptic pruning in adolescence, the age when pruning normally peaks.",71,6],[336,"Which EEG change marks normal adolescent synaptic pruning in Feinberg's model?","A steep fall in deep, slow-wave sleep activity during adolescence.",71,7],[337,"Which post-mortem picture fits the excessive pruning model of schizophrenia?","Reduced neuropil (dendrites and synapses) with normal neuron numbers and no gliosis.",71,8],[337,"Which gene finding gave the pruning hypothesis a genetic mechanism, and who reported it?","Sekar in 2016 found that high-risk forms of complement C4A tag more synapses for removal.",71,9],[337,"By how much do obstetric complications raise the risk of schizophrenia, and which type carries most risk?","They roughly double it, with an odds ratio of about 2 in Cannon's meta-analysis. Complications causing fetal hypoxia carry the most risk.",71,10],[337,"What is the season of birth effect in schizophrenia, and what might explain it?","Birth in late winter or spring in the Northern Hemisphere gives an excess of about 5 to 8%, possibly from infection or low vitamin D.",71,11],[337,"Why does older paternal age raise the risk of schizophrenia?","Sperm stem cells keep dividing throughout life and build up new (de novo) mutations. The main effect is from older fathers, not mothers.",71,12],[337,"Why are minor physical anomalies and dermatoglyphic changes seen as evidence of early developmental fault?","Skin and brain both come from ectoderm, and fingerprint ridges are fixed by about 24 weeks. These signs date the problem to the first two trimesters.",71,13],[337,"What is the neurodevelopmental continuum proposed by Owen and O'Donovan?","Disorders are ranked by severity of early brain impairment: intellectual disability, autism, ADHD, schizophrenia, then bipolar disorder, sharing rare CNVs that become less common along the line.",71,14],[337,"A man aged 20 with schizophrenia has a 22q11.2 deletion. In which disorders are such CNVs commonest and rarest?","Rare CNVs are commonest in intellectual disability and autism, less common in ADHD and schizophrenia, and rarest in bipolar disorder.",71,15],[337,"Why is the social drift hypothesis not a neurodevelopmental model?","Social drift (Goldberg, 1963) says the illness causes later social decline. It does not place a fault in early brain development.",71,16],[340,"What did Harlow's wire and cloth mother experiment show about attachment?","Infant monkeys fed from the wire mother but clung to the cloth one and used it as a secure base. Contact comfort, not food, drives attachment.",72,1],[340,"How did Harlow's monkeys raised in isolation behave?","They rocked, clasped themselves, feared others and later mothered their own young poorly.",72,2],[340,"Which hormone rises together in parents and infants during synchronous play, and what does it predict?","Oxytocin, made in the hypothalamus. Feldman found higher levels predict more attuned parenting.",72,3],[341,"What did Plotsky and Meaney find in adult rats separated from their mothers as pups?","More hypothalamic CRF and exaggerated ACTH and corticosterone responses to stress, so a hyperreactive HPA axis.",72,4],[341,"What separation schedule did Plotsky and Meaney use in rat pups?","About 3 hours a day during the first two weeks of life.",72,5],[341,"How did women abused in childhood respond to Heim's public speaking and arithmetic stress test?","They showed an exaggerated ACTH and cortisol rise and a larger heart rate response. In those currently depressed, the ACTH rise was more than six times that of controls.",72,6],[341,"How can low resting cortisol in some PTSD groups fit with exaggerated stress responses after abuse?","They measure different things. Resting levels and reactivity to a stress test can differ, so the findings do not contradict each other.",72,7],[341,"Which study followed children adopted into UK families from Romanian institutions, and who led it?","The English and Romanian Adoptees (ERA) study, led by Rutter and later Sonuga-Barke.",72,8],[341,"What lasting pattern did the ERA study find in children deprived beyond about 6 months?","Quasi-autistic features, disinhibited social engagement, cognitive impairment and inattention with overactivity, which persisted into adulthood.",72,9],[341,"What adult brain finding did the ERA study report after prolonged institutional deprivation?","Total brain volume was about 8.6% smaller, falling further with each extra month of deprivation.",72,10],[341,"How does the Bucharest Early Intervention Project differ in design from the ERA study?","It was the first randomised trial of foster care against staying in an institution, inside Romania. The ERA study was an observational follow-up of adopted children.",72,11],[341,"What did the Bucharest project find about timing of foster placement?","Fostered children had higher IQ by about 4.5 years, with the largest gains when placed before about 24 months, suggesting a sensitive period.",72,12],[341,"What did Gee find in the brains of children who experienced early deprivation?","Early, adult-like coupling between the amygdala and medial prefrontal cortex, as if the brain fast-tracked its own regulation without a carer.",72,13],[341,"What did McCrory find in children aged about 12 exposed to domestic violence?","Stronger amygdala and anterior insula responses to angry faces, like soldiers after combat, which may raise later anxiety risk.",72,14],[341,"Who led the Adverse Childhood Experiences study, when, and how many adults took part?","Felitti, in 1998, surveyed about 9500 adults in a US health plan.",72,15],[341,"What key relationship did the ACE study show, and what risk did four or more ACEs carry?","A dose-response gradient across all types of adversity. Four or more ACEs gave about 4 to 12 times the risk of depression, suicide attempts and alcoholism, with heart disease also raised.",72,16],[345,"How does the placenta protect the fetus from maternal cortisol?","The enzyme 11-beta-hydroxysteroid dehydrogenase type 2 converts cortisol into inactive cortisone.",73,1],[345,"A woman aged 31 eats much liquorice and is highly stressed in pregnancy. How might this affect her baby?","Both lower placental 11-beta-HSD2, so more cortisol reaches the fetus. The baby may be small and develop a more reactive stress system.",73,2],[345,"What is meant by fetal programming of the stress system?","Excess cortisol reaching the fetus alters growth and sets a more reactive HPA axis for later life.",73,3],[345,"What did the Dutch Hunger Winter show about prenatal stress and later mental illness?","Babies exposed to famine early in pregnancy had about twice the later risk of schizophrenia.",73,4],[345,"What perinatal stress was linked to slower brain maturation in very preterm babies?","More painful skin-breaking procedures in neonatal intensive care went with slower maturing of white matter and deep grey matter (Brummelte).",73,5],[345,"Which brain finding is most consistently reported in adults maltreated as children?","A smaller hippocampus, often not yet visible in childhood, with an overreactive amygdala.",73,6],[346,"How did high maternal licking and grooming change rat pups' brains in Weaver's work?","It reduced methylation of the hippocampal glucocorticoid receptor gene, giving more receptors, better cortisol feedback and calmer adults.",73,7],[346,"How was it shown that the licking and grooming effect came from care rather than genes?","Cross-fostering pups between high and low licking mothers showed the effect followed the rearing mother.",73,8],[346,"What does DNA methylation do to a gene?","It adds a chemical tag that silences the gene, reducing its expression.",73,9],[346,"What two roles does the hippocampus play that make it vulnerable to chronic stress?","It stores memory for context and acts as a brake on the HPA axis. Long glucocorticoid exposure shrinks its dendrites and slows neurogenesis.",73,10],[346,"What is Sapolsky's glucocorticoid cascade hypothesis?","Cortisol damages the hippocampus, the damaged hippocampus brakes cortisol less, so cortisol rises further in a vicious circle.",73,11],[346,"What did Vyas find in adult rats restrained for 2 hours a day for 10 days?","Hippocampal CA3 neurons lost dendrites while basolateral amygdala neurons grew more. Medial prefrontal dendrites also shrank.",73,12],[346,"After chronic stress ends, which dendritic changes reverse and which persist?","Hippocampal and prefrontal changes mostly reverse with rest, but amygdala changes last longer, fitting lasting anxiety.",73,13],[346,"What did Liston find in medical students before a major exam, and what happened a month later?","They shifted attention poorly and had weaker fronto-parietal connectivity. Both returned to normal about a month after the exam.",73,14],[347,"What did McGowan find in the hippocampus of suicide victims who had been abused in childhood?","More methylation of the glucocorticoid receptor gene and fewer glucocorticoid receptors.",73,15],[350,"What did Hebb propose in 1949 about learning at synapses?","That cells which fire together strengthen their connection.",74,1],[350,"What is long-term potentiation, and who first described it?","A lasting increase in synaptic strength after brief high-frequency stimulation. Bliss and Lomo described it in 1973 in the rabbit hippocampus.",74,2],[350,"In Bliss and Lomo's experiment, which pathway was stimulated and where was the response recorded?","The perforant path was stimulated and a larger response was recorded in the dentate gyrus for hours to days.",74,3],[350,"What type of stimulation produces long-term depression rather than LTP?","Slow, low-frequency stimulation produces LTD, a lasting fall in synaptic strength.",74,4],[350,"Why is the NMDA receptor called a coincidence detector?","It opens only when glutamate binds and the cell is already depolarised, which expels the magnesium ion blocking the channel.",74,5],[351,"What did Hubel and Wiesel show by sewing shut one eye of young kittens?","The open eye took over the ocular dominance columns. The change was permanent if done early but did not occur in adult cats, showing a critical period.",74,6],[351,"A girl aged 4 has a squint. Why must it be treated early?","Amblyopia follows the same critical period rule as the kitten eye studies, so wiring becomes fixed if not corrected in time.",74,7],[351,"What did Elbert find in string players using magnetoencephalography?","The left-hand fingers had a larger cortical representation, largest in those who started before about age 13.",74,8],[351,"What happens when finger maps in the cortex expand and blur together in musicians?","The separate finger maps merge, causing musician's focal dystonia.",74,9],[351,"What hippocampal changes did Maguire find in London taxi drivers?","The posterior hippocampus was larger, scaling with years of driving, and the anterior hippocampus was smaller.",74,10],[351,"How was it shown that taxi training caused hippocampal change rather than reflecting pre-existing differences?","A longitudinal study of trainees found growth only in those who qualified.",74,11],[351,"What did Draganski find when adults learned to juggle for 3 months?","Voxel-based morphometry showed grey matter growth in the mid-temporal motion area and left posterior intraparietal sulcus, which shrank back after 3 months without practice.",74,12],[351,"What probably underlies the grey matter increase seen after juggling training?","New synapses, glia and blood vessels rather than new neurons.",74,13],[351,"What is learned non-use after stroke?","Failed attempts to use a weak arm teach the patient not to use it, and the arm's cortical map shrinks.",74,14],[351,"A man aged 66 has a weak right arm after a stroke. What is constraint-induced movement therapy and what does it achieve?","The good hand is put in a mitt and the weak arm is trained for several hours a day for about 2 weeks. Function improves and the motor map grows on TMS, as confirmed by the EXCITE trial.",74,15],[354,"What two criteria are needed for a diagnosis of disorder of intellectual development in ICD-11?","Significantly low intellectual functioning and low adaptive behaviour, both starting in the developmental period. Low IQ alone is not enough.",75,1],[354,"How does a specific learning difficulty such as dyslexia differ from learning disability?","In a specific learning difficulty, general intellectual ability is normal.",75,2],[354,"How does ICD-11 grade severity of intellectual disability?","Mild is 2 to 3 SD below the mean, moderate 3 to 4 SD below, and severe and profound more than 4 SD below. Severe and profound are told apart mainly by adaptive skills.",75,3],[354,"What are the traditional IQ bands for mild, moderate, severe and profound learning disability?","Mild 50 to 69, moderate 35 to 49, severe 20 to 34 and profound below 20.",75,4],[354,"What proportion of people with learning disability fall in the mild range?","About 85%.",75,5],[354,"What are the commonest genetic, commonest inherited and commonest preventable causes of learning disability?","Down syndrome is the commonest genetic cause, fragile X syndrome the commonest inherited cause and fetal alcohol spectrum disorder the commonest preventable cause.",75,6],[355,"Why is measured prevalence of learning disability about 1% when 2.3% of a normal curve falls below IQ 70?","Many people with IQ below 70 cope well with daily life, so they do not meet the adaptive behaviour criterion.",75,7],[355,"What is Penrose's two-group model of learning disability?","Severe disability occurs across all social classes and usually has a clear organic cause. Mild disability clusters in families and in poverty.",75,8],[355,"What did Reichenberg find in siblings of Swedish men with mild versus severe learning disability?","Siblings of men with mild disability had low IQs, while siblings of men with severe disability had near-average IQs, as severe cases often result from de novo mutations.",75,9],[355,"How does alcohol damage the developing brain, and what facial features suggest FASD?","It disrupts neuronal migration and triggers apoptosis. Features include a smooth philtrum, thin upper lip and short palpebral fissures, with poor growth.",75,10],[355,"What are the typical clinical features of fragile X syndrome?","Long face, large ears, large testes, gaze avoidance and social anxiety.",75,11],[355,"How common is congenital hypothyroidism, how is it detected, and when must treatment start?","It affects about 1 in 2000 to 3000 babies, is found on the day-5 bloodspot test, and treatment in the first 2 weeks prevents disability.",75,12],[355,"What is periventricular leukomalacia, and why does it mainly affect the legs?","Injury to immature oligodendrocytes from hypoxia or infection in babies born at 24 to 32 weeks. Leg fibres run nearest the ventricles, so the legs stiffen most.",75,13],[355,"What did Purpura find in the cortex of children with severe learning disability?","Normal neuron numbers but few, long, thin and twisted dendritic spines resembling immature spines.",75,14],[355,"What is the core deficit in dyslexia and which brain areas are underactive?","A phonological deficit in breaking words into sounds, with weak left temporo-parietal and left fusiform visual word form area activity. Phonics teaching partly normalises this.",75,15],[356,"What is the genetic cause of fragile X syndrome?","Over 200 CGG repeats in the FMR1 gene on the X chromosome, which becomes methylated and silenced so FMRP is lost.",75,16],[356,"Why do people with Down syndrome develop Alzheimer's disease early?","An extra copy of the APP gene on chromosome 21 raises amyloid, so plaques are near universal by about age 40.",75,17],[356,"A boy aged 7, unscreened at birth, has learning disability, fair hair, eczema and a musty smell. What is the diagnosis?","Phenylketonuria, due to absent phenylalanine hydroxylase. It is preventable with a low-phenylalanine diet after bloodspot screening.",75,18],[356,"Why do children with untreated phenylketonuria have fair hair and a musty smell?","Phenylalanine is not converted to tyrosine, so less melanin is made. The build-up of phenylalanine products gives the musty smell.",75,19],[357,"A man aged 25 has an IQ of 42 and needs help with daily tasks. What severity is this on traditional bands?","Moderate learning disability, since moderate covers IQ 35 to 49.",75,20],[359,"Describe the sequence of excitotoxic neuronal death after hypoxia such as cardiac arrest.","Energy failure causes glutamate release, NMDA receptors let in excess calcium, which activates proteases and nitric oxide synthase and overwhelms mitochondria, so the cell dies.",76,1],[359,"A scaffolder aged 41 falls onto the back of his head and later becomes disinhibited and impulsive. What MRI finding is likely?","Bilateral orbitofrontal contrecoup contusions, as the brain strikes the rough floor of the anterior skull.",76,2],[359,"Which brain areas are most vulnerable to contusion in head injury, and why?","The orbitofrontal cortex and temporal poles, because they rest against the ridged anterior skull floor and the sphenoid wing.",76,3],[359,"What causes diffuse axonal injury and what is its characteristic pathology?","Rotational forces shear axons at the grey-white junction and corpus callosum, leaving axonal retraction balls.",76,4],[359,"A man aged 23 is in deep coma after a car crash but his CT is almost normal. What injury should be suspected?","Diffuse axonal injury, which CT can largely miss despite deep coma.",76,5],[360,"Give the Russell and Smith post-traumatic amnesia grades of head injury severity.","Under 5 minutes very mild, 5 to 60 minutes mild, 1 to 24 hours moderate, 1 to 7 days severe and over 7 days very severe.",76,6],[360,"A woman aged 35 has post-traumatic amnesia lasting 4 days after an assault. How severe is the injury?","Severe, as PTA of 1 to 7 days is severe on the Russell and Smith grading.",76,7],[360,"Which Glasgow Coma Scale score indicates a severe head injury?","A lowest GCS of 8 or less.",76,8],[360,"Why do all four ventricles enlarge after traumatic subarachnoid haemorrhage?","Blood blocks CSF absorption at the arachnoid granulations, causing communicating hydrocephalus. Non-communicating hydrocephalus enlarges only ventricles above the block.",76,9],[360,"A man aged 79 on warfarin has fluctuating confusion and headache weeks after a minor fall. What is the likely cause?","A chronic subdural haematoma, from tearing of bridging veins stretched by brain atrophy.",76,10],[360,"What features define the vegetative state, and when is it considered permanent in UK guidance?","Eye opening and sleep-wake cycles without awareness. It is considered permanent after 6 months for non-traumatic and 12 months for traumatic causes.",76,11],[360,"What is the Kennard principle and what is its main limitation?","Young brains recover better from focal motor damage than adult brains. After severe diffuse early injury outcomes are often worse, as children may grow into deficits.",76,12],[360,"What are the rates of depression, euphoria and cognitive impairment in multiple sclerosis?","Lifetime depression about 50%, euphoria about 10% and cognitive impairment 40 to 65%, with processing speed affected first.",76,13],[360,"What does euphoria in multiple sclerosis indicate?","It is an organic sign linked to heavy frontal lesion load and cognitive impairment, not healthy coping. It differs from pathological laughing and crying.",76,14],[360,"A woman aged 24 develops psychosis followed by seizures and abnormal movements. Which encephalitis should be considered?","Anti-NMDA receptor encephalitis, caused by antibodies against NMDA receptors.",76,15],[360,"What is the commonest primary adult brain tumour, and what does an olfactory groove meningioma cause?","Meningioma. An olfactory groove meningioma causes apathy, tactlessness and loss of smell, and may present psychiatrically first.",76,16],[360,"How common is depression after stroke, and what is the status of Robinson's left frontal hypothesis?","About a third become depressed. Robinson linked it to left frontal lesions, but Carson's systematic review found no consistent link.",76,17],[361,"A woman aged 32 had optic neuritis 2 years ago and now has leg numbness, periventricular lesions and oligoclonal bands. What is the diagnosis?","Multiple sclerosis, with lesions spread in space and time.",76,18],[363,"What is the heritability of autism, and how is it inherited?","About 80% in a large Swedish family study. Inheritance is complex and polygenic, not Mendelian.",77,1],[363,"Does a heritability of 80% mean an 80% chance that a sibling will have autism?","No. Heritability is the share of variation between people due to genes, not a sibling's risk.",77,2],[363,"What types of genetic variation contribute to autism?","Thousands of common variants with tiny effects plus rare de novo mutations and copy number variants with large effects.",77,3],[363,"A boy aged 3 with autism has head circumference rising from the 40th to the 97th centile. What growth pattern is this?","Normal size at birth, then early overgrowth in the first 1 to 2 years, mainly frontal and temporal, before growth slows by adolescence (Courchesne).",77,4],[364,"What are neurexin and neuroligin, and where does each sit at the synapse?","Neurexin (NRXN1, on 2p16) is presynaptic and binds postsynaptic neuroligin. Together they help set whether a synapse excites or inhibits.",77,5],[364,"Which gene is lost in a 22q13.3 deletion, and what syndrome results?","SHANK3, a postsynaptic scaffolding protein at glutamate synapses. Its loss causes Phelan-McDermid syndrome with absent speech, low tone and autism.",77,6],[364,"What might explain early brain overgrowth in autism?","Too many neurons, too little pruning, or both. Post-mortem studies have found extra neurons in prefrontal cortex.",77,7],[364,"What cerebellar MRI finding did Courchesne report in autism in 1988?","Hypoplasia of lobules VI and VII of the cerebellar vermis.",77,8],[364,"What is the excitation-inhibition imbalance hypothesis of autism, and which facts support it?","Rubenstein and Merzenich proposed raised excitation relative to inhibition, making circuits noisy. It fits the 20 to 30% epilepsy rate and sensory over-sensitivity.",77,9],[364,"What pattern of connectivity did Just and colleagues find in autistic adults?","Reduced long-range frontal to posterior connectivity with preserved or increased local connectivity.",77,10],[364,"What is the oldest biochemical finding in autism, and how common is it?","Raised whole-blood serotonin, first reported in 1961 and found in about 25 to 30% of autistic children.",77,11],[364,"Does high blood serotonin in autism mean that brain serotonin is high?","No. Most blood serotonin is in platelets, taken up by the serotonin transporter, and does not reflect brain levels.",77,12],[364,"What did the SOARS-B trial find about intranasal oxytocin in autistic children?","Daily oxytocin for 24 weeks in about 290 children gave no improvement in social function.",77,13],[364,"What was the rationale for bumetanide in autism, and what did phase 3 trials show?","It blocks NKCC1 to lower neuronal chloride and restore GABA inhibition. BAMBI and later phase 3 trials showed no benefit for core symptoms.",77,14],[365,"What is the most replicated post-mortem finding in autism?","A reduced number of cerebellar Purkinje cells, the GABAergic output cells, found by Bauman and Kemper.",77,15],[366,"Which X-linked neuroligin genes did Jamain find altered in autistic brothers?","NLGN3 and NLGN4X.",77,16],[368,"What is the twin heritability of ADHD?","About 74%, among the highest in psychiatry.",78,1],[368,"Which environmental factors add to the risk of ADHD?","Preterm birth and low birth weight.",78,2],[368,"Which two variable repeat alleles were the classic ADHD candidate genes?","The DAT1 (SLC6A3) 10-repeat in the 3' untranslated region and the DRD4 7-repeat in exon 3, each with a tiny effect.",78,3],[368,"With which disorders are 5-HTTLPR and DRD2 TaqIA mainly linked, rather than ADHD?","5-HTTLPR is studied in depression and anxiety, and DRD2 TaqIA (in ANKK1) in addiction.",78,4],[368,"What did the first large ADHD GWAS by Demontis in 2019 find?","12 genome-wide significant loci, including FOXP2, and SNP heritability of about 22%. A later larger study found 27 loci.",78,5],[368,"Why is SNP heritability of ADHD much lower than twin heritability?","Twin studies capture all genetic effects, but SNP studies count only common variants. The gap is part of the missing heritability.",78,6],[369,"What did Shaw find about cortical maturation in ADHD?","Median peak cortical thickness came at about 10.5 years versus 7.5 in controls, with the greatest delay in lateral prefrontal cortex.",78,7],[369,"Which cortical region matured slightly early in ADHD in Shaw's study, and what does the pattern suggest?","Primary motor cortex. Overall the pattern suggests delayed maturation rather than a fixed lesion.",78,8],[369,"What did the ENIGMA mega-analysis find in children with ADHD?","Smaller accumbens, amygdala, caudate, hippocampus, putamen and intracranial volumes. Effects were small, not diagnostic and not seen in adults.",78,9],[369,"Which brain region is underactive in ADHD during stop-signal and go/no-go tasks?","The right inferior frontal cortex, with the supplementary motor area, anterior cingulate and striato-thalamic regions also underactive.",78,10],[369,"What is the default mode interference model of ADHD?","The default mode network is poorly suppressed during tasks and intrudes, causing lapses and variable reaction times. Stimulants improve suppression.",78,11],[369,"What does Sonuga-Barke's dual pathway model add to the executive account of ADHD?","A motivational route of delay aversion, where waiting feels unpleasant so a small immediate reward is chosen, with weak ventral striatal reward anticipation.",78,12],[369,"Describe Arnsten's inverted-U model of prefrontal catecholamine function and where ADHD sits.","Moderate dopamine at D1 and noradrenaline at alpha-2A receptors give best working memory, while too little or too much impairs it. ADHD sits on the low arm.",78,13],[369,"A mother asks whether an EEG theta to beta ratio test can diagnose her son's ADHD. What should she be told?","No. The effect shrank in meta-analysis and drowsiness raises the ratio. NICE NG87 does not support EEG, and diagnosis remains clinical.",78,14],[370,"A boy aged 8 has ADHD. What do repeated MRI scans over childhood typically show in his condition?","Delayed maturation of cortical thickness, peaking about three years later than in peers.",78,15],[373,"What action do all drugs that humans misuse share, according to Di Chiara and Imperato?","They all raise dopamine in the nucleus accumbens.",79,1],[373,"How do stimulants differ from opioids, alcohol and cannabinoids in raising accumbens dopamine?","Stimulants act directly, for example by blocking the dopamine transporter. The others act indirectly by removing GABA inhibition of VTA dopamine neurons.",79,2],[373,"What proportions of users become dependent on tobacco, heroin, cocaine, alcohol and cannabis?","About 32%, 23%, 17%, 15% and 9% respectively, so most users do not become dependent.",79,3],[373,"What do D2 receptor PET studies in addiction and in drug-naive monkeys show?","Low striatal D2 availability predicts later cocaine intake and is worsened by cocaine, so it is both a risk factor and a result.",79,4],[373,"A man aged 38 enjoys crack cocaine less but has intense urges when he sees a lighter. Which theory explains this?","Incentive sensitisation (Robinson and Berridge), where dopamine-driven wanting of cues becomes sensitised while liking stays flat or falls.",79,5],[374,"Why does oral methylphenidate rarely cause a high despite blocking over half of striatal dopamine transporters?","Brain levels rise slowly, which does not mimic the fast burst of a reward signal that intravenous cocaine produces.",79,6],[374,"What did Childress find when cocaine users watched a cocaine film?","Raised amygdala and anterior cingulate blood flow along with craving, while visual cortex responded in both users and controls.",79,7],[374,"What is delta-FosB and why is it important in addiction?","A truncated, unusually stable transcription factor that builds up over weeks in D1-type accumbens neurons, acting as a lasting switch that raises drug reward. c-Fos rises only briefly.",79,8],[374,"What is the difference between metabolic and pharmacodynamic tolerance?","In metabolic tolerance faster liver clearance lowers blood levels. In pharmacodynamic tolerance blood levels are unchanged but the target responds less.",79,9],[374,"What cellular adaptations underlie opioid tolerance?","Mu receptor phosphorylation, desensitisation and internalisation, with a compensatory rise in cAMP signalling.",79,10],[374,"What did Siegel show about conditioned tolerance, and why does it matter clinically?","Familiar drug-taking cues trigger a protective counter-response. Using in an unfamiliar setting loses this, which explains some overdose deaths.",79,11],[374,"Why does opioid withdrawal cause noradrenergic symptoms, and which drug class treats them?","Raised cAMP makes the locus coeruleus fire excessively. Alpha-2 agonists such as lofexidine damp this.",79,12],[374,"What is Solomon and Corbit's opponent process theory of addiction?","Each dose gives a quick pleasant a-process followed by a slower opposite b-process. With repetition the b-process grows, so use shifts towards escaping misery.",79,13],[374,"What does Koob mean by anti-reward?","Falling dopamine tone with rising CRF, dynorphin and noradrenaline in the extended amygdala, driving negative affect in withdrawal.",79,14],[374,"Name the three stages of the Koob and Volkow addiction cycle and the main brain region for each.","Binge or intoxication in the basal ganglia, withdrawal or negative affect in the extended amygdala, and preoccupation or anticipation in the prefrontal cortex and insula.",79,15],[374,"What shift in striatal control did Everitt and Robbins describe in addiction?","Control moves from goal-directed ventral striatum to habit-based dorsal striatum, and with weak prefrontal control habits become compulsions.",79,16],[374,"In the reinstatement model, which brain systems mediate relapse triggered by cues, stress and a priming dose?","Cues act through the basolateral amygdala, stress through CRF and noradrenaline in the BNST and central amygdala, and priming through dopamine plus prefrontal glutamate input to the accumbens.",79,17],[374,"What is meant by incubation of craving during abstinence?","Cue-induced drug seeking grows over the first weeks of abstinence rather than fading, as shown by Grimm.",79,18],[375,"Which brain systems mediate wanting and liking of rewards?","Mesolimbic dopamine drives wanting, while liking depends on opioid hotspots.",79,19],[378,"Which peptide fragment reliably provokes panic attacks in people with panic disorder, and through which receptor does it act?","CCK-4, a four-amino-acid fragment of cholecystokinin, acting at CCK-B receptors. CCK-B antagonists block the effect.",80,1],[378,"Apart from CCK-4, which two non-peptide challenges can trigger panic attacks in panic disorder?","Inhaled carbon dioxide and sodium lactate infusion. Neither is a peptide, which is a common exam trap.",80,2],[378,"Which neuropeptide is anxiolytic rather than anxiety-provoking and is often used as a distractor for CCK?","Neuropeptide Y. It calms anxiety rather than setting off alarm.",80,3],[378,"What did Etkin and Wager's imaging meta-analysis find shared by social anxiety disorder, specific phobia and PTSD?","All three showed overactivity of the amygdala and insula to emotional or fearful stimuli. Only PTSD also showed low ventromedial prefrontal activity.",80,4],[378,"What roles do the amygdala and the insula play in amplifying fear?","The amygdala detects and flags threat. The insula maps bodily sensations such as a racing heart, and together they amplify fear.",80,5],[378,"What is behavioural inhibition, who described it and roughly how common is it in toddlers?","Kagan described it as a shy, wary temperament in early childhood. It affects about 15 to 20% of toddlers and raises the risk of later social anxiety disorder.",80,6],[378,"What did Schwartz find when adults classed as inhibited at age 2 were scanned in their twenties?","They showed a greater amygdala response to novel faces than to familiar faces, compared with adults who had been bold toddlers.",80,7],[379,"How do fear and anxiety differ as states?","Fear is a rapid response to a clear, predictable cue. Anxiety is a sustained state of vigilance when the threat is uncertain.",80,8],[379,"In Davis's rat startle studies, which structure carries phasic fear and which carries sustained anxiety?","The central nucleus of the amygdala carries quick fear to a short predictable cue. The bed nucleus of the stria terminalis carries lasting anxiety in unpredictable settings.",80,9],[379,"What is the bed nucleus of the stria terminalis and why is it linked to generalised anxiety disorder?","It is part of the extended amygdala that uses CRF and drives hypothalamic and brainstem stress centres. It is a candidate hub for the sustained worry of generalised anxiety disorder.",80,10],[379,"What does Klein's false suffocation alarm theory of panic disorder propose?","A hypersensitive brainstem carbon dioxide monitor misfires and signals suffocation. This explains why CO2 and lactate provoke panic in panic disorder.",80,11],[379,"What concentration of CO2 is used in the single-breath panic challenge, and how do controls respond?","A single breath of 35% CO2 is used. Most patients with panic disorder panic, while most controls feel only mild discomfort.",80,12],[379,"Why does sodium lactate infusion provoke panic, and what shows the CO2 alarm lies partly in the brainstem?","Lactate is converted to bicarbonate and then CO2. People with damage to both amygdalae still panic after CO2, so the alarm is partly brainstem based.",80,13],[379,"What did Charney show with yohimbine in panic disorder, and what blunted the response?","Yohimbine blocks alpha-2 autoreceptors on the locus coeruleus, causing panic and a larger rise in MHPG. Clonidine, an alpha-2 agonist, blunted the response.",80,14],[379,"What is MHPG and which transmitter does it come from?","MHPG is the main breakdown product of noradrenaline, not serotonin. It rises more after yohimbine in panic disorder.",80,15],[379,"What did Malizia find using carbon-11 flumazenil PET in unmedicated patients with panic disorder?","Benzodiazepine-site binding on GABA-A receptors was reduced throughout the brain, most in the orbitofrontal cortex and insula. This suggests a weak GABA brake.",80,16],[379,"What did Nutt find when flumazenil was given to people with panic disorder and to controls?","Flumazenil provoked panic in patients but not in controls. This suggests the GABA-A receptor set-point has shifted in panic disorder.",80,17],[380,"A 28-year-old man has recurrent unexpected attacks of terror and fear of dying. What would flumazenil PET show in his disorder?","He has panic disorder, so PET would show reduced GABA-A benzodiazepine receptor binding. Amygdala overactivity with low vmPFC activity is the PTSD pattern instead.",80,18],[382,"What did Gilbertson's study of identical twins discordant for combat exposure show about the hippocampus in PTSD?","Both the veteran with PTSD and his unexposed twin had small hippocampi, and the twin's volume tracked his brother's severity. A small hippocampus is partly a pre-existing vulnerability factor.",81,1],[382,"Besides being a pre-existing risk factor, how else might the hippocampus be affected in PTSD?","Stress may also shrink it further, so both directions can operate.",81,2],[382,"What is the replicated imaging triad in PTSD described by Shin and colleagues?","An overactive amygdala, an underactive ventromedial prefrontal cortex and a smaller, less functional hippocampus.",81,3],[382,"What are the normal roles of the vmPFC and the hippocampus in controlling fear?","The vmPFC signals to the amygdala that a reminder is now safe. The hippocampus provides context about where and when danger occurred.",81,4],[383,"Does fear extinction erase the original fear memory?","No. Extinction forms a new safety memory, held by the vmPFC and gated by hippocampal context, that competes with the old fear memory.",81,5],[383,"What did Milad find when testing extinction recall in people with PTSD?","Fear learning was intact, but next-day recall of extinction was poor, with less vmPFC and hippocampal activity and more dorsal anterior cingulate activity.",81,6],[383,"What is memory reconsolidation and which receptor signalling supports it?","A recalled memory becomes briefly unstable and must be stored again. Noradrenaline acting at beta-adrenergic receptors supports this restabilisation.",81,7],[383,"Describe Brunet's propranolol trial for PTSD and its status.","Propranolol was given 90 minutes before writing about the trauma, weekly for six weeks, and reduced symptoms more than placebo. It works by blocking reconsolidation and remains experimental.",81,8],[383,"How does blocking reconsolidation differ from extinction in its effect on a fear memory?","Extinction builds a new competing safety memory. Blocking reconsolidation edits or weakens the original memory itself.",81,9],[383,"What is NICE's position on benzodiazepines for PTSD, and what is the biological concern?","NICE does not recommend benzodiazepines for PTSD. They may impair extinction learning.",81,10],[383,"What is the typical HPA axis profile in PTSD described by Yehuda?","Cortisol is low or normal, glucocorticoid receptors are more numerous and sensitive, and low-dose dexamethasone causes super-suppression of cortisol. CSF CRF is raised.",81,11],[383,"How does the dexamethasone suppression pattern in PTSD contrast with melancholic depression?","PTSD shows super-suppression with low or normal cortisol. Melancholic depression shows high cortisol that fails to suppress.",81,12],[383,"What did Geracioti find when sampling CSF through lumbar catheters in combat veterans with PTSD?","Hourly CSF sampling showed raised noradrenaline that tracked symptom severity. This fits startle, hypervigilance and poor sleep.",81,13],[383,"Which alpha-2 antagonist can provoke flashbacks in veterans with PTSD?","Yohimbine, which raises noradrenaline release by blocking alpha-2 autoreceptors.",81,14],[383,"What gene-environment interaction did Binder describe for PTSD?","FKBP5 risk alleles raised adult PTSD risk only in people who had suffered childhood abuse.",81,15],[383,"What does FKBP5 do and what epigenetic change did Klengel describe?","FKBP5 is a co-chaperone that reduces glucocorticoid receptor sensitivity. Klengel showed childhood trauma removes methyl tags from the gene, an epigenetic gene-environment effect.",81,16],[383,"Which gene is the classic gene-environment example for PTSD and which for depression?","FKBP5 is the PTSD example. SLC6A4, the serotonin transporter gene, is the classic depression example.",81,17],[384,"A 33-year-old woman has flashbacks and hypervigilance a year after assault, and fear does not fade with safe exposure. What imaging pattern is expected?","She has PTSD, which shows amygdala hyperreactivity with reduced ventromedial prefrontal activity. Her safety memory is poorly held, so the alarm keeps firing.",81,18],[386,"Which brain circuit is implicated in OCD?","A cortico-striato-thalamo-cortical loop running from the orbitofrontal cortex and anterior cingulate to the caudate, then through the thalamus and back to cortex.",82,1],[386,"A 26-year-old woman with contamination obsessions holds a cloth she believes is soiled during oxygen-15 PET. What change is expected?","Blood flow rises in the caudate, orbitofrontal cortex and anterior cingulate, as in Rauch's study. These areas are already overactive at rest.",82,2],[386,"What did Baxter show about caudate metabolism in OCD after treatment?","Responders to fluoxetine and to exposure and response prevention both showed reduced caudate glucose metabolism. Non-responders showed no change.",82,3],[387,"What basal ganglia pathway imbalance keeps the OCD loop running?","The direct pathway, the accelerator, outweighs the indirect pathway, the brake. Thalamic drive increases and orbitofrontal worry signals are amplified.",82,4],[387,"What glutamate findings have been reported in OCD?","Chakrabarty found raised CSF glutamate in drug-naive adults, and children showed raised caudate glutamate on MR spectroscopy that fell with paroxetine.",82,5],[387,"Which glutamate modulators have been trialled as augmenting agents in OCD, and are they standard?","Memantine and N-acetylcysteine have been trialled as add-ons. None is yet standard treatment.",82,6],[387,"Which class of drugs may worsen compulsive behaviour?","Dopamine agonists.",82,7],[387,"What happens in SAPAP3 knockout mice and what rescues them?","They groom compulsively until they wound their faces. Fluoxetine or restoring SAPAP3 in the striatum rescues them.",82,8],[387,"How do Hoxb8 mutant mice differ from SAPAP3 knockout mice?","Both over-groom, but in Hoxb8 mice the fault lies in microglia, whereas SAPAP3 is a cortico-striatal synaptic scaffold.",82,9],[387,"What did Gillan's devaluation task show about OCD?","People with OCD kept responding for a devalued outcome more than controls. This suggests over-reliance on habits rather than goal-directed control, with obsessions possibly arising later as explanations.",82,10],[387,"What is the heritability of OCD and which disorders are more common in relatives?","Heritability is about 40 to 50%. Relatives have more tic disorders.",82,11],[387,"What are the features of tic-related OCD under the DSM-5-TR specifier?","Earlier onset, more common in boys, and symmetry or just-right themes. It responds better to antipsychotic augmentation.",82,12],[387,"What is the status of PANDAS and what does it require?","PANDAS is a contested concept. It requires abrupt onset of symptoms after infection.",82,13],[387,"What did Kalanithi find in post-mortem basal ganglia from people with severe Tourette syndrome?","Parvalbumin-positive fast-spiking GABA interneurons in caudate and putamen were reduced by about half, and cholinergic interneurons were also reduced. Loss of this striatal brake may let tics escape.",82,14],[387,"Which brain areas are engaged by the premonitory urge before a tic?","Bohlhalter's fMRI showed the supplementary motor area, anterior cingulate and insula.",82,15],[387,"What visual processing abnormality did Feusner find in body dysmorphic disorder?","Visual cortex was underactive to low spatial frequency images of their own face, with frontostriatal overactivity. This fits a bias to detail over the whole face.",82,16],[387,"How does the neurobiology of hoarding disorder differ from OCD?","Hoarding involves anterior cingulate and insula overactivity when deciding about own possessions, not a caudate-centred loop. It responds less to SSRIs.",82,17],[387,"How do trichotillomania and OCD differ on stop-signal and set-shifting tasks?","Both impair motor inhibition, worse in trichotillomania. Only OCD impairs set-shifting.",82,18],[388,"Why is Baxter's OCD study important for linking psychological therapy to brain change?","Behaviour therapy and an SSRI both normalised the same overactive caudate circuit. It shows a talking therapy can produce measurable brain change.",82,19],[390,"Which two 1950s drug observations founded the monoamine deficiency hypothesis of depression?","Reserpine, which empties monoamine stores, lowered mood in some patients. Iproniazid, an MAOI that prevents monoamine breakdown, lifted mood.",83,1],[390,"By what mechanism does the antihypertensive drug reserpine deplete brain monoamines?","It blocks the vesicular pump that loads monoamines into storage vesicles, so serotonin and noradrenaline leak out and are broken down.",83,2],[390,"What evidence links noradrenaline specifically to depression?","Noradrenaline reuptake inhibitors such as reboxetine lift mood, venlafaxine blocks noradrenaline reuptake at higher doses, and AMPT causes relapse in noradrenergic drug responders.",83,3],[390,"Why does the delay in antidepressant response argue against a simple monoamine shortage?","Monoamines rise within hours of a dose, but mood improves only after 2 to 6 weeks. This points to slow downstream adaptive changes.",83,4],[390,"What did a 2023 review conclude about serotonin levels in depression?","It found no consistent evidence of low serotonin in depression.",83,5],[391,"How is acute tryptophan depletion performed and which enzyme does it starve?","Volunteers drink an amino acid mix lacking tryptophan, so brain serotonin falls within hours. It starves tryptophan hydroxylase, the rate-limiting enzyme of serotonin synthesis.",83,6],[391,"What did Delgado find in 1990 with acute tryptophan depletion?","People in remission on an SSRI quickly relapsed into low mood, while never-depressed volunteers barely changed.",83,7],[391,"What does AMPT deplete and in whom does it bring back depressive symptoms?","AMPT depletes noradrenaline and dopamine. It causes relapse in people well on noradrenergic drugs but not in those well on SSRIs.",83,8],[391,"What can and cannot be concluded from relapse after tryptophan depletion?","It shows the SSRI response depends on serotonin. It does not show that low serotonin alone causes depression.",83,9],[391,"How is the dexamethasone suppression test performed and what is found in severe melancholic depression?","1 mg dexamethasone is given at 23:00 and cortisol is measured next morning. In about half of severe melancholia cortisol fails to suppress, reflecting impaired glucocorticoid receptor feedback.",83,10],[391,"Can the dexamethasone suppression test be used to diagnose depression?","No. Although non-suppression shows an overactive HPA axis, it is not specific enough for diagnosis.",83,11],[391,"Outline Duman's neurotrophic hypothesis of depression.","Stress and cortisol reduce hippocampal BDNF, causing dendritic shrinkage and reduced neurogenesis in the dentate gyrus. Weeks of antidepressant treatment raise cAMP signalling and CREB, which switches on the BDNF gene.",83,12],[391,"Which transcription factor switches on the BDNF gene after chronic antidepressant treatment?","CREB, cAMP response element-binding protein. It is CREB, not the glucocorticoid receptor, that turns BDNF on.",83,13],[391,"Which inflammatory markers are raised in some depressed people and what natural experiment supports inflammation causing depression?","IL-6, TNF-alpha and CRP, often in treatment-resistant illness. About a third of patients given interferon-alpha for hepatitis C became depressed within weeks.",83,14],[391,"How do cytokines divert tryptophan away from serotonin?","They activate indoleamine 2,3-dioxygenase, which shunts tryptophan into the kynurenine pathway. This produces quinolinic acid, which can damage neurons.",83,15],[391,"What does FDG-PET show in depression, and which region is overactive?","Reduced resting metabolism in the dorsolateral prefrontal cortex and dorsal anterior cingulate. The subgenual cingulate, area 25, is overactive and was targeted by Mayberg with deep brain stimulation.",83,16],[391,"What did the ENIGMA consortium find about hippocampal volume in depression?","A smaller hippocampus was driven by recurrent episodes and onset before age 21, not by first episodes.",83,17],[391,"What are the features of vascular depression in late life?","Deep white matter hyperintensities on T2 and FLAIR linked to hypertension and diabetes, with later onset, more psychomotor slowing and poorer treatment response.",83,18],[391,"What is the twin heritability of major depression and how does it compare with bipolar disorder and schizophrenia?","About 37%, which is much lower than bipolar disorder or schizophrenia.",83,19],[391,"A 74-year-old man with low mood scores poorly on memory tests, often answering I don't know. What is likely, and next step?","Depressive pseudodementia is likely. A depression rating scale such as the Beck Depression Inventory should come before any scan or CSF test.",83,20],[395,"What is the twin heritability of bipolar disorder?","About 60 to 85%, among the highest in psychiatry.",84,1],[395,"What are the MZ and DZ twin concordance rates for bipolar disorder?","About 40 to 70% for identical twins and about 5 to 10% for non-identical twins.",84,2],[395,"What is the SNP-based heritability of bipolar disorder and how does it differ from twin heritability?","About 20%. It is the share explained by measured common variants, much lower than the 60 to 85% twin estimate.",84,3],[395,"What did the 2021 genome-wide study by Mullins and colleagues find in bipolar disorder?","In over 40,000 cases it found 64 risk loci. Bipolar I shared more genetic risk with schizophrenia and bipolar II more with major depression.",84,4],[395,"What is the genetic correlation between bipolar disorder and schizophrenia?","About 0.7. No single gene of large effect explains most cases.",84,5],[396,"What does CACNA1C encode and why is it relevant to bipolar disorder?","It encodes the pore-forming alpha-1C subunit of the L-type calcium channel, Cav1.2, which links neuronal activity to gene expression. It is a replicated bipolar risk locus.",84,6],[396,"Which syndrome is caused by rare gain-of-function mutations in CACNA1C, and what are its features?","Timothy syndrome, which includes long QT and autism.",84,7],[396,"What does ANK3 encode and what is its function?","Ankyrin G, a scaffold that anchors voltage-gated sodium channels at the axon initial segment and nodes of Ranvier.",84,8],[396,"What kind of genes top the list of bipolar risk genes from Ferreira's 2008 study?","Ion channels and scaffolds, CACNA1C and ANK3, rather than neurotransmitter receptors.",84,9],[396,"How do Clock delta-19 mutant mice behave and what reverses this?","They sleep less, are hyperactive, prefer sugar and cocaine and are less anxious, a mania-like profile. Lithium brings them back towards normal.",84,10],[396,"How does the Clock delta-19 mutation affect dopamine?","The faulty CLOCK protein increases firing of dopamine neurons in the ventral tegmental area.",84,11],[396,"What does Post's kindling model propose about the course of bipolar disorder?","Early episodes follow major stressors, but later ones come more often with little or no trigger. Each episode leaves lasting gene expression changes that lower the threshold for the next.",84,12],[396,"What evidence supports a dopamine excess model of mania?","Amphetamine and levodopa can trigger elation, and dopamine blockers calm mania. Bipolar depression may reflect low dopamine tone.",84,13],[396,"What is the role of protein kinase C in mania and which mood stabilisers affect it?","PKC, activated by diacylglycerol, appears overactive in mania. Long-term lithium and valproate both dampen PKC.",84,14],[396,"What is lithium's direct kinase target, as opposed to PKC?","Glycogen synthase kinase-3 beta.",84,15],[396,"Which drug that blocks protein kinase C reduced mania in a small randomised trial?","Tamoxifen, a breast cancer drug that enters the brain, as tested by Yildiz.",84,16],[396,"What does MR spectroscopy show in euthymic bipolar disorder and how is it interpreted?","Raised lactate, lower intracellular pH and less phosphocreatine. Kato interpreted this as mitochondrial dysfunction with reliance on glycolysis.",84,17],[396,"Are the spectroscopy and white matter findings in bipolar disorder diagnostic?","No. White matter hyperintensities are commoner and inherited mitochondrial diseases carry more mood disorder, but these are group averages, not diagnostic tests.",84,18],[399,"A 19-year-old woman's brother has schizophrenia and her parents are unaffected. What is her lifetime risk?","About 9 to 10%, roughly ten times the general population risk of about 1%. Most siblings never develop the illness.",85,1],[399,"What is the lifetime risk of schizophrenia for a child with one affected parent and with two affected parents?","About 13% with one affected parent and about 46% with two.",85,2],[399,"What is the lifetime risk of schizophrenia for MZ and DZ co-twins of an affected person?","About 48% for an identical co-twin and about 17% for a non-identical co-twin.",85,3],[399,"Why is the risk for parents of people with schizophrenia only about 6%?","Because of reduced fecundity. People with schizophrenia have fewer children, so those who became parents had lower liability.",85,4],[399,"What is the twin heritability of schizophrenia and what does it mean?","About 80%. It is a population estimate, not an individual's personal risk.",85,5],[399,"Which gene is disrupted by a balanced t(1;11) translocation in a Scottish family, and which illnesses ran with it?","DISC1 on 1q42. It ran with schizophrenia, bipolar disorder and recurrent depression.",85,6],[399,"Which candidate genes for schizophrenia came from Irish and Icelandic families?","Dysbindin, DTNBP1 on 6p22.3, from Irish families, which affects vesicle trafficking and glutamate release. Neuregulin 1 on 8p from Icelandic families, which acts on ErbB4.",85,7],[400,"Which was the first locus to reach genome-wide significance for psychosis?","ZNF804A, a zinc finger gene on 2q32, in 2008.",85,8],[400,"What did the PGC3 study find in 2022 and where is the strongest signal?","287 loci of small effect enriched in synaptic genes. The strongest signal is the MHC region, partly via C4A, which tags synapses for pruning by microglia.",85,9],[400,"What did the SCHEMA consortium find in schizophrenia?","Ten genes in which rare damaging variants carry large risk. Most older candidate genes do not stand out.",85,10],[400,"Which dopamine pathways relate to positive symptoms, negative symptoms, movement effects and prolactin?","Mesolimbic excess relates to positive symptoms and mesocortical deficit to negative and cognitive symptoms. Nigrostriatal blockade causes movement effects and tuberoinfundibular blockade raises prolactin.",85,11],[400,"What was the most consistent dopamine finding in Howes's 2012 meta-analysis of schizophrenia?","Raised presynaptic dopamine synthesis capacity on 18F-DOPA PET, effect size about 0.8, greatest in the associative striatum. D2 receptor numbers were not reliably raised.",85,12],[400,"What did Krystal show with low-dose ketamine in healthy volunteers in 1994?","Ketamine, an NMDA antagonist, produced positive, negative and cognitive symptoms within an hour. Amphetamine mimics only positive symptoms, so this supports NMDA receptor hypofunction.",85,13],[400,"Which natural human example supports NMDA receptor hypofunction in psychosis?","Anti-NMDA receptor encephalitis, which often begins with psychotic symptoms.",85,14],[400,"Why does NMDA receptor blockade lead to cortical overexcitation?","It hits fast-spiking parvalbumin GABA interneurons first, removing their brake on pyramidal cells. Cortical glutamate rises, gamma rhythms break down and striatal dopamine rises downstream.",85,15],[400,"What structural brain changes are seen in schizophrenia on CT and MRI?","Enlarged lateral and third ventricles, first shown by Johnstone in 1976, and reduced grey matter present at first episode before treatment. Normal leftward planum temporale asymmetry is reduced or reversed.",85,16],[400,"What do post-mortem studies show in schizophrenia and what does the absence of gliosis suggest?","Reduced neuropil and smaller neurons without gliosis. The lack of gliosis suggests an early neurodevelopmental origin rather than degeneration.",85,17],[400,"How can antipsychotics confound structural imaging in schizophrenia?","Chakos found haloperidol enlarged the caudate, which shrank back after switching to clozapine.",85,18],[401,"A 19-year-old woman is at clinical high risk of psychosis. Which abnormality is most marked in those who go on to psychosis?","Raised presynaptic dopamine synthesis capacity in the associative striatum. It is present before any full episode or antipsychotic treatment.",85,19],[404,"What did David's study of Swedish conscripts show about cognition before schizophrenia?","Young men who later developed schizophrenia already scored about 0.5 standard deviations lower at about age 18, years before psychotic symptoms.",86,1],[404,"How large is the cognitive deficit at first episode of schizophrenia and how does it change afterwards?","About 1 to 1.5 standard deviations at first episode, then it stays broadly stable.",86,2],[404,"What evidence shows cognitive deficits in schizophrenia are not caused by antipsychotics or drug misuse?","The deficits appear before onset and in people never treated with antipsychotics or who do not misuse drugs. This supports a neurodevelopmental model.",86,3],[404,"Why do cognitive deficits matter for outcomes in schizophrenia?","Green showed cognition predicts work and independent living better than positive symptoms do, so trials now target cognition directly.",86,4],[405,"Which cognitive domain shows the largest single deficit in schizophrenia and how is it measured?","Processing speed, at about 1.5 standard deviations, measured by digit symbol coding.",86,5],[405,"Which cognitive skill is best preserved in schizophrenia and how is this used clinically?","Vocabulary. Reading tests of irregular words are used to estimate premorbid IQ.",86,6],[405,"Is recognition or free recall memory better preserved in schizophrenia?","Recognition memory is better preserved than free recall.",86,7],[405,"What are the seven domains of the MATRICS battery?","Speed of processing, attention or vigilance, working memory, verbal learning, visual learning, reasoning and problem solving, and social cognition.",86,8],[405,"What is hypofrontality and who first described it?","Loss of the normal higher frontal than posterior blood flow at rest, described by Ingvar and Franzen in 1974 in chronic schizophrenia.",86,9],[405,"What did Weinberger find during the Wisconsin Card Sorting Test in schizophrenia?","The dorsolateral prefrontal cortex failed to activate normally during this rule-shifting task.",86,10],[405,"How does task load affect DLPFC activation in schizophrenia?","At easy levels the DLPFC over-activates, which is inefficient. At higher loads it fails to activate normally.",86,11],[405,"What did Glantz and Lewis find in post-mortem DLPFC in schizophrenia?","Normal cell numbers without gliosis, but deep layer III pyramidal cells had fewer dendritic spines. These cells carry cortico-cortical links needed for working memory.",86,12],[405,"What is the relationship between D1 receptor stimulation and working memory in Arnsten's studies?","It is an inverted U. Moderate D1 stimulation in the DLPFC helps, while too little or too much impairs working memory.",86,13],[405,"How effective are antipsychotics for cognitive deficits in schizophrenia?","They do little to improve cognition.",86,14],[405,"What did Wykes's meta-analysis show about cognitive remediation in schizophrenia?","It gives a modest gain with an effect size of about 0.45. Benefits carry over to daily life better when combined with vocational rehabilitation.",86,15],[406,"A 35-year-old man with schizophrenia shows little rise in blood flow during the Wisconsin Card Sorting Test. What does this show?","Reduced dorsolateral prefrontal activation during an executive task, or hypofrontality. It tracks cognitive and negative symptoms more than positive symptoms.",86,16],[408,"How does NICE define self-harm in its guidance?","Intentional self-poisoning or self-injury, irrespective of motive or degree of suicidal intent.",87,1],[408,"Roughly how many people die by suicide worldwide each year according to the WHO?","More than 700,000 people each year.",87,2],[408,"What is the gender paradox in suicide and self-harm in the UK?","About three in four suicides are men, whereas self-harm is commoner in women and girls and peaks in adolescence.",87,3],[408,"What did Swannell's meta-analysis find about the prevalence of non-suicidal self-injury?","About 17% of adolescents, 13% of young adults and 5.5% of adults had ever self-injured. Most never present to hospital.",87,4],[408,"What proportion of people seen in hospital after self-harm repeat it, or die by suicide, within a year?","About 1 in 6 repeat self-harm within a year, and about 0.5 to 2% die by suicide within a year.",87,5],[408,"What did Asberg find in 1976 when measuring CSF 5-HIAA in depressed inpatients?","Low CSF 5-HIAA, the main serotonin metabolite, was linked to violent suicide attempts and later death by suicide.",87,6],[408,"What is homovanillic acid and why is it a distractor for 5-HIAA?","HVA is the dopamine metabolite, not the serotonin one. MHPG and VMA are noradrenaline metabolites.",87,7],[409,"What did Cavanagh's review of psychological autopsy studies find?","About 90% of people who died by suicide had a mental disorder, most often depression.",87,8],[409,"What does NICE advise about using risk assessment scales to predict suicide?","NICE advises against using risk scales to predict who will die by suicide, as they have poor predictive value.",87,9],[409,"What are the two components of Mann's stress-diathesis model of suicidal behaviour?","A lasting trait diathesis, such as impulsive aggression, low serotonin function, early adversity and inherited factors. This meets a short-term state stressor such as depression, heavy drinking or major loss.",87,10],[409,"What is the heritability of suicidal behaviour?","About 30 to 50%, partly independent of any psychiatric disorder.",87,11],[409,"What did Danish adoption studies show about suicide?","Suicide was more common in the biological relatives, not the adoptive relatives, of adoptees who died by suicide.",87,12],[409,"What did McGowan find in the brains of suicide victims who had been abused as children?","Increased methylation of the glucocorticoid receptor gene in the hippocampus, which reduces its expression. Early adversity may set the stress system for life.",87,13],[409,"Besides suicide, which trait is low CSF 5-HIAA associated with across diagnoses?","Impulsive aggression across many psychiatric disorders.",87,14],[409,"What serotonin marker changes are found post-mortem in the ventral prefrontal cortex after suicide?","Fewer serotonin transporter sites with increased 5-HT1A and 5-HT2A receptors. The receptor rise probably compensates for reduced serotonin input.",87,15],[409,"What does dexamethasone non-suppression predict in depressed inpatients?","A several-fold higher rate of later suicide, reflecting an overactive HPA stress system.",87,16],[409,"What did Stanley find in the CSF of people with repeated non-suicidal self-injury, and what model does this support?","Lower beta-endorphin and met-enkephalin than controls. The endogenous opioid model proposes self-injury releases opioids that briefly relieve this deficit.",87,17],[409,"Can biological markers such as CSF 5-HIAA be used to predict an individual's suicide risk?","No. They are group-level findings and cannot predict an individual's risk.",87,18],[410,"A 37-year-old man with depression is admitted after a violent suicide attempt. Which CSF finding is most consistently reported in such patients?","Low CSF 5-HIAA, reflecting reduced serotonergic transmission.",87,19],[412,"A 19-year-old woman with sudden visual loss has a field that stays the same width at twice the distance. What does this suggest?","Functional visual loss. A tubular field is optically impossible because an organic field widens like a cone with distance.",88,1],[412,"Besides tubular fields, which visual field finding on repeated testing supports functional visual loss?","Spiralling visual fields.",88,2],[412,"What are the DSM-5-TR criteria for somatic symptom disorder?","One or more distressing bodily symptoms with excessive related thoughts, feelings or behaviours, usually lasting more than 6 months.",88,3],[412,"Must the symptom be medically unexplained to diagnose DSM-5-TR somatic symptom disorder?","No. It can be diagnosed even when there is a proven medical cause, such as endometriosis. There is also no symptom count.",88,4],[412,"What defines ICD-11 bodily distress disorder and what is its code?","Distressing bodily symptoms with excessive attention to them, not relieved by normal tests or reassurance, lasting at least several months. It is coded 6C20 and rated mild, moderate or severe.",88,5],[412,"What happened to neurasthenia, hypochondriasis and body dysmorphic disorder in ICD-11?","Neurasthenia was removed. Hypochondriasis, now health anxiety disorder, and body dysmorphic disorder moved to the obsessive-compulsive group.",88,6],[413,"What is functional neurological disorder and what are its names in DSM-5-TR and ICD-11?","The nervous system functions abnormally while its structure is intact. DSM-5-TR calls it functional neurological symptom disorder and ICD-11 dissociative neurological symptom disorder.",88,7],[413,"How common is functional neurological disorder in neurology clinics?","About 1 in 6 new neurology outpatients.",88,8],[413,"Is a psychological stressor required to diagnose functional neurological disorder?","No. A stressor is no longer required for diagnosis.",88,9],[413,"How does functional neurological disorder differ from malingering and factitious disorder?","In FND the symptoms are not produced intentionally. In malingering and factitious disorder symptoms are deliberately feigned.",88,10],[413,"On what basis is functional neurological disorder diagnosed?","On positive clinical signs, not just by excluding other disease.",88,11],[413,"What is Hoover's sign and what does it indicate?","Hip extension is weak when asked but returns involuntarily when the person flexes the other hip against resistance. It is a positive sign of functional weakness.",88,12],[413,"What clinical features suggest a functional tremor?","It eases with distraction and entrains to a rhythm tapped by the other hand.",88,13],[413,"What did Voon find using fMRI with fearful faces in functional limb weakness?","Stronger connectivity between the amygdala and the supplementary motor area than in controls, suggesting emotion directly shapes movement.",88,14],[413,"Which region is less active during functional tremor and what is its significance?","The right temporoparietal junction, which checks whether a movement is self-generated. Its underactivity explains loss of the sense of agency, so the movement feels involuntary.",88,15],[413,"How does predictive processing explain functional and somatic symptoms?","Strong top-down predictions override weak or unclear bodily signals, so symptoms are truly felt. Attention, anxiety and previous illness strengthen these priors.",88,16],[413,"Are people with somatic symptoms more accurate at sensing their own heartbeat?","No. They are often less accurate at interoception, not more.",88,17],[413,"What does treatment of functional symptoms aim to do?","Retrain attention and expectation, for example through physiotherapy and psychological therapy.",88,18],[414,"A 50-year-old woman has back pain, bloating and tiredness for a year, unrelieved by reassurance, and checks her body daily. ICD-11 diagnosis?","Bodily distress disorder, defined by distressing bodily symptoms with excessive attention to them for at least several months.",88,19],[416,"An 82-year-old man becomes confused two days after hip surgery. Which orientation domain is usually lost first?","Orientation to time, then place. Knowledge of own identity is lost last, if at all.",89,1],[416,"Can normal orientation to time, place and person exclude delirium?","No. Attention tests such as months of the year backwards are more sensitive than orientation.",89,2],[416,"What are the core features of delirium?","An acute disturbance of attention and awareness developing over hours or days and fluctuating in course.",89,3],[416,"According to NICE CG103, how common is delirium on medical wards?","It affects about 20 to 30% of people on medical wards.",89,4],[416,"What is the strongest predisposing factor for delirium, and which other risk factors does NICE list?","Pre-existing dementia is the strongest. NICE also lists age 65 or over, current hip fracture and severe illness.",89,5],[416,"How do predisposing and precipitating factors differ in delirium?","Predisposing factors such as dementia lower brain reserve. Precipitating factors such as infection, surgery, drugs or a urinary catheter trigger the episode.",89,6],[416,"What are the three motor subtypes of delirium, and which is commonest in older people?","Hyperactive, hypoactive and mixed. Hypoactive is commonest in older people, is often missed or mistaken for depression and has the worst prognosis.",89,7],[416,"Which brief screening tool is used for delirium and how long does it take?","The 4AT, which takes about 2 minutes.",89,8],[417,"What EEG changes did Engel and Romano describe in delirium?","Diffuse background slowing with more theta and delta activity, tracking severity and improving with recovery.",89,9],[417,"Which type of delirium is the exception to EEG slowing, and when is an EEG most useful?","Alcohol or benzodiazepine withdrawal delirium shows fast, low-voltage activity. EEG is most useful to exclude non-convulsive status epilepticus.",89,10],[417,"What is the cholinergic deficiency hypothesis of delirium and what supports it?","Delirium results from reduced acetylcholine. Anticholinergic drugs cause it, serum anticholinergic activity tracks severity and physostigmine reverses it.",89,11],[417,"What anticholinergic burden score is linked to cognitive decline and death?","A cumulative score of 3 or more across all drugs.",89,12],[417,"What evidence supports a relative dopamine excess in delirium?","Dopaminergic drugs such as levodopa, bupropion and cocaine can cause delirium, and dopamine blockers can help.",89,13],[417,"When does NICE CG103 allow haloperidol in delirium?","Short term, usually for 1 week or less, only when distress or risk persists despite non-drug measures. It is avoided in Parkinson's disease and Lewy body dementia.",89,14],[417,"What is the role of benzodiazepines in delirium?","They worsen most delirium and should be avoided, except in alcohol or benzodiazepine withdrawal.",89,15],[417,"Why does a urinary infection cause delirium more readily in a person with Alzheimer's disease?","Ageing and brain disease prime microglia. Peripheral cytokines such as IL-6 signal to the brain, and primed microglia over-react and amplify neuroinflammation.",89,16],[417,"By which routes do peripheral cytokines signal to the brain in delirium?","Through the vagus nerve, the circumventricular organs and blood vessel walls, without the infection invading the brain.",89,17],[417,"What is the long-term cognitive consequence of delirium?","Delirium accelerates later cognitive decline.",89,18],[418,"An 84-year-old man becomes acutely confused and drowsy two days after starting oxybutynin and amitriptyline. What is the mechanism and management?","Central cholinergic deficiency from additive anticholinergic burden. The offending drugs should be stopped rather than adding sedation.",89,19],[420,"Which peptide is deficient in narcolepsy type 1 and where is it made?","Orexin A, also called hypocretin-1, is deficient. It is made only by neurons in the lateral hypothalamus.",90,1],[420,"How does orexin normally keep a person awake?","It excites the histamine, noradrenaline and serotonin arousal neurons, acting like a spring that holds the sleep-wake flip-flop switch on wake.",90,2],[420,"What CSF orexin-A level is diagnostic of narcolepsy type 1?","A CSF orexin-A level of 110 pg/mL or less confirms narcolepsy type 1.",90,3],[420,"Why is melatonin not the deficient hormone in narcolepsy?","Melatonin comes from the pineal gland and stays normal. Narcolepsy is a failure of the wake switch, not of body clock timing.",90,4],[420,"Why is melanin-concentrating hormone a tempting but wrong answer for the peptide lost in narcolepsy?","Its neurons lie next to orexin cells in the lateral hypothalamus, but they promote sleep and survive in narcolepsy.",90,5],[421,"What is cataplexy and how is it distinguished from a seizure or faint?","Cataplexy is sudden loss of muscle tone, often triggered by laughter, from REM atonia intruding into wakefulness. Awareness is fully kept throughout.",90,6],[421,"What evidence suggests narcolepsy type 1 is autoimmune?","About 98% of patients carry HLA-DQB1*06:02, and cases rose after the 2009 H1N1 (Pandemrix) vaccine campaign.",90,7],[421,"How does idiopathic hypersomnia differ from narcolepsy type 1?","Night sleep is long, naps are unrefreshing and sleep drunkenness occurs on waking. There is no cataplexy and orexin is normal.",90,8],[421,"What did Rye find in the CSF of people with idiopathic hypersomnia?","Their CSF enhanced GABA-A receptor activity like a natural sedative, and the GABA-A antagonist flumazenil improved alertness.",90,9],[421,"A boy aged 16 has episodes lasting days of sleeping 20 hours daily, overeating and disinhibition. Diagnosis?","Kleine-Levin syndrome. Episodes of hypersomnia, hyperphagia, hypersexuality and derealisation alternate with completely normal periods, mostly in teenage boys.",90,10],[421,"Which feature is not part of Kleine-Levin syndrome?","Persistent hypertension is not a feature. About two thirds of cases are male.",90,11],[421,"What brain changes occur in obstructive sleep apnoea and are they reversible?","Intermittent hypoxia reduces hippocampal and frontal grey matter with memory problems. Grey matter partly recovers after about 3 months of CPAP.",90,12],[421,"Which clock gene variants delay or advance sleep timing?","A dominant CRY1 variant lengthens the internal day and delays sleep phase. A PER2 mutation speeds the clock and advances sleep.",90,13],[421,"What does the hyperarousal model of chronic insomnia propose, and what did FDG-PET show?","Insomnia is a brain switched on day and night. PET showed raised glucose metabolism both awake and asleep, with arousal areas failing to power down.",90,14],[421,"What is the increased risk of depression in chronic insomnia?","People with chronic insomnia carry about 2 to 3 times the usual risk of developing depression.",90,15],[421,"Why do sleepwalkers move about yet lack judgement and memory?","Sleepwalking arises from deep NREM (N3) sleep early in the night as a state dissociation. Motor areas wake while frontal areas stay asleep.",90,16],[421,"What is the biology of restless legs syndrome and when is iron advised?","Low brain iron disrupts dopamine signalling. Iron is advised if ferritin is 75 µg/L or less, even if within the laboratory range.",90,17],[421,"What kind of disease is fatal familial insomnia and which structure does it destroy?","It is an inherited prion disease that destroys the thalamus.",90,18],[421,"What MSLT mean sleep latency supports narcolepsy or idiopathic hypersomnia?","A mean sleep latency of 8 minutes or less on the multiple sleep latency test.",90,19],[422,"A man aged 70 punches his wife while dreaming and has anosmia and constipation. Diagnosis and prognosis?","REM sleep behaviour disorder. Over 70% develop a synucleinopathy such as Parkinson's disease or dementia with Lewy bodies within about 12 years.",90,20],[425,"What is the commonest genetic cause of learning disability and how does it usually arise?","Down syndrome. About 95% is free trisomy 21 from non-disjunction, mostly in maternal meiosis I, so risk rises with maternal age.",91,1],[425,"Why do people with Down syndrome develop Alzheimer's disease early?","APP sits on chromosome 21, so three copies raise amyloid-beta from birth. Plaques are almost universal by 40 and lifetime dementia risk exceeds 90%.",91,2],[425,"A boy aged 12 was a floppy poor feeder and now has insatiable appetite and skin picking. Diagnosis?","Prader-Willi syndrome, confirmed by methylation testing at 15q11-13 showing only the maternal pattern.",91,3],[425,"Which Prader-Willi subtype carries a higher risk of psychosis?","The maternal uniparental disomy subtype.",91,4],[426,"What does genomic imprinting mean for genes on chromosome 15q11-13?","Only one parent's copy of certain genes is normally switched on, so loss of that copy cannot be covered by the other.",91,5],[426,"What causes Prader-Willi syndrome and in what proportions?","Loss of paternal 15q11-13 expression, from a paternal deletion in about 70% or maternal uniparental disomy in about 25%.",91,6],[426,"What causes Angelman syndrome and what are its features?","Loss of maternal UBE3A expression. Features are absent speech, ataxic jerky gait, seizures, hand flapping and frequent laughter.",91,7],[426,"What deletion causes Williams syndrome and what are its physical features?","A 7q11.23 deletion including the elastin gene, causing supravalvular aortic stenosis and infantile hypercalcaemia.",91,8],[426,"What explains the over-friendliness of children with Williams syndrome?","Meyer-Lindenberg found a weak amygdala response to threatening faces, so social threat signals are poor. Visuospatial skills are weak and anxiety is common.",91,9],[426,"What are the features of 22q11.2 deletion syndrome and its psychosis risk?","Cleft palate, cardiac outflow defects and hypocalcaemia. About 1 in 4 adults develop schizophrenia.",91,10],[426,"What is the genetic basis and sleep abnormality of Smith-Magenis syndrome?","A 17p11.2 deletion affecting RAI1. Melatonin peaks by day, giving daytime naps and early waking, treated with morning beta-blocker and evening melatonin.",91,11],[426,"What genetic mechanism causes fragile X syndrome and how is it inherited?","Over 200 CGG repeats silence the FMR1 gene, so FMRP is lost. It is the commonest inherited cause, passed through carrier mothers.",91,12],[426,"What is the mGluR theory of fragile X syndrome?","Without FMRP braking local protein synthesis, mGluR5 signalling drives excessive long-term depression at synapses.",91,13],[426,"What are the physical signs of fragile X, and what does the premutation cause?","Long face, large ears, large testes and gaze aversion. A 55 to 200 repeat premutation causes a late-onset tremor-ataxia syndrome.",91,14],[426,"A girl aged 2 loses words and hand use after normal early development and wrings her hands. Gene?","Rett syndrome from a MECP2 mutation on Xq28. Regression follows 6 to 18 months of normal development, with slowing head growth.",91,15],[426,"What causes Lesch-Nyhan syndrome and does lowering urate stop self-injury?","X-linked HPRT loss causes excess urate, with striatal dopamine loss linked to dystonia and self-biting. Lowering urate treats gout but not self-injury.",91,16],[426,"What is the mechanism and neuropsychiatric burden of tuberous sclerosis?","Loss of hamartin or tuberin releases mTORC1 overgrowth, causing tubers and nodules. Epilepsy affects about 85% and autism about 40 to 50%.",91,17],[426,"Which enzyme is lost in phenylketonuria and how is disability prevented?","Phenylalanine hydroxylase, inherited recessively. Newborn heel-prick screening and a low-phenylalanine diet prevent learning disability.",91,18],[427,"Which feature reliably separates Williams syndrome from 22q11.2 deletion syndrome?","Calcium. Williams syndrome causes high calcium, whereas 22q11.2 deletion causes low calcium.",91,19],[427,"A newborn has a high-pitched mewing cry, microcephaly and low tone. Which chromosome region is lost?","The tip of the short arm of chromosome 5 (5p), causing cri du chat syndrome.",91,20],[430,"What was the design of the Minnesota starvation study?","Ancel Keys gave healthy young men half rations for six months in the 1940s. They lost about a quarter of their body weight.",92,1],[430,"What psychological changes did the Minnesota starvation volunteers develop?","Food preoccupation, low mood, irritability and social withdrawal, with bingeing when food returned.",92,2],[430,"Which core feature of anorexia nervosa did the Minnesota volunteers never develop, and why does it matter?","They never developed fear of fatness or body image distortion. This shows distortion belongs to the illness, not to starvation.",92,3],[430,"Why does the Minnesota study support weight restoration as the first step of treatment?","Food thoughts, low mood and bingeing are partly effects of starvation, so they are expected to ease with refeeding.",92,4],[431,"What pattern of ghrelin and leptin is found in anorexia nervosa?","Ghrelin is high and leptin is low. Hunger is present but overridden, not absent.",92,5],[431,"Why do periods stop in anorexia nervosa?","Low leptin slows hypothalamic GnRH pulses, so LH and oestrogen fall and amenorrhoea follows.",92,6],[431,"What happens to the growth hormone axis in anorexia nervosa?","Growth hormone is high but IGF-1 is low, because starvation makes the liver resistant to growth hormone.",92,7],[431,"What thyroid test pattern is seen in anorexia nervosa?","Low T3 with normal TSH, from reduced T4 to T3 conversion. This is an adaptive low T3 state, not hypothyroidism.",92,8],[431,"Which endocrine changes in anorexia nervosa combine to thin the bones?","High cortisol, low oestrogen, low IGF-1 and low T3 together reduce bone density.",92,9],[431,"What explains widened sulci and enlarged ventricles on MRI in anorexia nervosa?","Pseudoatrophy from grey matter loss and cortical thinning. Bernardoni showed cortical thickness recovers quickly with weight gain.",92,10],[431,"What is the twin and SNP heritability of anorexia nervosa?","Twin heritability is about 50 to 60%, and SNP heritability about 11 to 17%.",92,11],[431,"What serotonin receptor changes persist in women long recovered from anorexia nervosa?","PET shows raised 5-HT1A and reduced 5-HT2A binding, suggesting an anxiety-linked trait that starvation may soothe, rewarding restriction.",92,12],[431,"What did Foerde find when people with anorexia nervosa chose foods in the scanner?","The dorsal striatum habit system was more active and predicted next-day intake, suggesting restriction becomes habitual.",92,13],[431,"Which brain region may explain feeling full after small meals in anorexia nervosa?","The insula, which maps gut and heart signals, shows altered responses.",92,14],[431,"What did Marsh find in bulimia nervosa during a self-control task?","Weak frontostriatal control activity and more impulsive errors. Bulimia reflects undercontrol, while restriction reflects overcontrol.",92,15],[431,"How does binge eating disorder differ from bulimia nervosa clinically and on imaging?","Binge eating disorder has no purging or fasting. Food pictures cause a stronger medial orbitofrontal reward response.",92,16],[431,"A boy aged 10 eats few foods due to fear of choking but has no weight concerns. What is the diagnosis and its drivers?","ARFID, linked to sensory sensitivity, fear of choking or vomiting and low interest in food, without shape or weight concern.",92,17],[432,"What genetic correlations did Watson's 2019 anorexia GWAS find?","Eight risk loci, with positive correlation to OCD, anxiety, depression and HDL cholesterol, and negative correlation to BMI and insulin.",92,18],[432,"Why is anorexia nervosa described as a metabo-psychiatric disorder?","Its risk genes overlap with psychiatric disorders and also tilt metabolism towards leanness, which may make weight restoration hard.",92,19],[434,"A woman aged 31 is lucid for 36 hours after a seizure cluster, then becomes elated and religiose. Diagnosis?","Postictal psychosis, which follows a seizure cluster after a lucid interval of up to 72 hours and settles within days.",93,1],[434,"What are the risk factors and long-term risk of repeated postictal psychosis?","Bilateral seizure foci are a risk factor. Repeated episodes may evolve into chronic interictal psychosis.",93,2],[434,"What auras arise from stimulating the amygdala and the hippocampus in Gloor's studies?","Amygdala stimulation gave sudden unprovoked fear. Hippocampus and entorhinal cortex stimulation gave deja vu.",93,3],[434,"What features suggest mesial temporal lobe seizures rather than panic?","A rising epigastric sensation and brief stereotyped fear followed by automatisms such as lip-smacking point to a seizure.",93,4],[434,"What is the commonest cause of drug-resistant temporal lobe epilepsy and its MRI appearance?","Hippocampal sclerosis, with cell loss in CA1 and CA4. MRI shows a small hippocampus with high T2 and FLAIR signal.",93,5],[434,"Which childhood event is often found in the history of hippocampal sclerosis, and what treatment can help?","A prolonged febrile convulsion in early childhood. Surgical resection can stop the seizures.",93,6],[434,"What is the gold standard investigation to distinguish functional seizures from epilepsy?","Video-EEG capturing a typical attack. Normal interictal EEGs do not exclude epilepsy.",93,7],[435,"How does postictal delirium differ from postictal psychosis?","Postictal delirium starts immediately after the seizure with clouded awareness and no lucid interval.",93,8],[435,"Which clinical signs favour functional or dissociative seizures over epileptic seizures?","Eyes held shut, a long waxing and waning course, side-to-side head shaking and crying. Open eyes and lateral tongue biting favour epilepsy.",93,9],[435,"What proportion of people with functional seizures also have epilepsy?","About 10 to 20% have both.",93,10],[435,"How should serum prolactin be used after a suspected seizure?","Take blood 10 to 20 minutes after the event. A rise supports epilepsy but also follows syncope, and a normal level does not exclude it.",93,11],[435,"What features suggest non-convulsive status epilepticus?","Fluctuating awareness without convulsions, with continuous epileptiform discharges on EEG.",93,12],[435,"What are the features of schizophrenia-like interictal psychosis?","Psychosis in clear consciousness unrelated to seizure timing, starting about 14 years after epilepsy onset, often with a left temporal focus and warm affect.",93,13],[435,"What is forced normalisation in epilepsy and who described it?","Psychosis or mood disturbance appearing when seizures stop and the EEG normalises (Landolt), also called alternative psychosis by Tellenbach.",93,14],[435,"What evidence suggests depression in epilepsy is not just a reaction to seizures?","Depression and suicide attempts often precede the first seizure, and lower hippocampal 5-HT1A binding tracks depression in TLE.",93,15],[435,"What are the features of Geschwind syndrome?","Hypergraphia, deep religiosity, viscosity of speech and reduced sexual drive in temporal lobe epilepsy.",93,16],[435,"How does Kluver-Bucy syndrome differ from Geschwind syndrome in sexual behaviour?","Kluver-Bucy brings hypersexuality, whereas Geschwind syndrome brings reduced sexual interest.",93,17],[435,"What is levetiracetam's target and its main psychiatric risk?","It binds the vesicle protein SV2A. About 1 in 10 develop irritability, aggression or low mood, more with a past psychiatric history.",93,18],[436,"A man aged 40 with TLE has recurrent bouts lasting one to two days of irritability and low mood. Diagnosis?","Interictal dysphoric disorder, with brief recurrent bouts of irritability, low mood and anxiety that clear completely.",93,19],[438,"How does ICD-11 classify personality disorder?","By severity, with trait domain qualifiers and an optional borderline pattern specifier.",94,1],[438,"What did Donegan find on fMRI when people with BPD viewed emotional faces?","The amygdala responded more strongly than in controls.",94,2],[438,"A man aged 32 is callous and fearless and does not learn from punishment. Typical neurobiology?","Reduced amygdala response to others' fear and distress, with ventromedial prefrontal dysfunction, as in Blair's model of psychopathy.",94,3],[439,"What prefrontal finding accompanies amygdala hyperreactivity in borderline personality disorder?","Prefrontal and cingulate regulatory areas that calm the amygdala are less active, so there is a loud alarm with weak brakes.",94,4],[439,"Which psychological treatment may strengthen prefrontal brakes in borderline personality disorder?","Dialectical behaviour therapy (DBT).",94,5],[439,"What is the opioid hypothesis of self-injury in borderline personality disorder?","Baseline endogenous opioid tone is low. Self-injury releases opioids and briefly restores calm, so relief has a chemical basis.",94,6],[439,"Which endogenous opioids are low in the CSF of people who self-harm, and what does PET show?","Beta-endorphin and met-enkephalin are low, and PET shows altered mu-opioid receptor availability.",94,7],[439,"What effect did intranasal oxytocin have on trust in people with BPD?","It reduced trust and cooperation, most in those with anxious attachment and rejection sensitivity.",94,8],[439,"Why might oxytocin lower trust in fearful people?","Oxytocin increases the salience of social cues, which in a fearful person heightens vigilance rather than trust.",94,9],[439,"According to Blair's model, why does a child with psychopathic traits not learn that harming others is wrong?","The amygdala responds weakly to others' fear and distress, so harming others is never felt as aversive.",94,10],[439,"What is poor reversal learning and which region is implicated?","Failure to change behaviour when a reward turns into punishment, linked to ventromedial prefrontal cortex dysfunction.",94,11],[439,"What did Raine find in men with antisocial personality disorder?","About 11% less prefrontal grey matter, with smaller skin conductance and heart rate rises during a stressful task.",94,12],[439,"What is one of the best-replicated physiological markers of antisocial behaviour?","A low resting heart rate.",94,13],[439,"How do fearlessness theory and stimulation-seeking theory explain low arousal in antisocial behaviour?","Fearlessness theory says punishment deters less. Stimulation-seeking theory says low arousal feels unpleasant, so risk is sought.",94,14],[439,"What did Caspi find about MAOA genotype and maltreatment in the Dunedin cohort?","Maltreated boys with low-activity MAOA had high antisocial outcomes, while high-activity carriers were protected: a gene-environment interaction.",94,15],[439,"Which monoamines does MAOA break down and on which chromosome does it lie?","It is X-linked and breaks down serotonin, noradrenaline and dopamine.",94,16],[439,"Why is MAOA not a gene for violence?","Its risk appears mainly in combination with childhood maltreatment, so it is an interaction, not a direct cause.",94,17],[440,"A woman aged 23 swings to rage within minutes and rates neutral faces as hostile. Likely neural finding?","Amygdala hyperreactivity with weak prefrontal control, typical of borderline personality disorder.",94,18],[442,"What is the difference between comorbidity and multimorbidity?","Comorbidity is an additional illness alongside an index condition. Multimorbidity is two or more long-term conditions with no main one.",95,1],[442,"Which NICE guideline covers multimorbidity and what does it emphasise?","NICE NG56, which asks clinicians to plan care around the whole person rather than single diseases.",95,2],[442,"What did Barnett's Scottish primary care study show about multimorbidity and deprivation?","In about 1.75 million people, multimorbidity began 10 to 15 years earlier in the poorest areas.",95,3],[442,"How did deprivation affect combined mental and physical multimorbidity in Barnett's study?","Mental and physical illness together was nearly twice as common in the most deprived areas.",95,4],[442,"Were most people with multimorbidity older or younger than 65 in Barnett's study?","More people with multimorbidity were under 65 than over it.",95,5],[443,"What is the p factor described in the Dunedin birth cohort?","A single general psychopathology dimension, found by Caspi in the Dunedin cohort, explaining much overlap between mental disorders.",95,6],[443,"What does a higher p factor score predict?","More disorders, greater severity and longer duration of illness.",95,7],[443,"What might the p factor reflect psychologically?","A shared underlying vulnerability, possibly poor emotional regulation.",95,8],[443,"Why is the p factor different from Spearman's g?","The p factor is a general dimension of psychopathology, whereas g is a general factor of intelligence.",95,9],[443,"How many pleiotropic loci did the Cross-Disorder Group find across eight disorders, and what does pleiotropic mean?","They found 109. Pleiotropic means one locus raises risk for two or more disorders.",95,10],[443,"Into which three genetic groups did the eight psychiatric disorders fall?","A compulsive group (anorexia, OCD, Tourette), a mood and psychotic group (schizophrenia, bipolar, depression) and a neurodevelopmental group (autism, ADHD).",95,11],[443,"What is the genetic correlation between schizophrenia and bipolar disorder?","About 0.7, showing heavy genetic overlap.",95,12],[443,"What did Khandaker find about shared risk for coronary heart disease and depression?","Family history, IL-6, CRP and lipids were shared risks, and Mendelian randomisation suggested IL-6 may cause depression.",95,13],[443,"Why is Mendelian randomisation less prone to bias than observational studies?","It uses inherited gene variants, allocated randomly at conception, as a natural experiment, reducing confounding and reverse causation.",95,14],[443,"What metabolic state did Pillinger find in drug-naive first-episode schizophrenia?","Raised fasting glucose and insulin resistance already present before any antipsychotic.",95,15],[443,"How much earlier do people with schizophrenia die, and from what?","About 15 years earlier, mostly from physical illness.",95,16],[443,"What is McEwen's concept of allostatic load?","Chronic stress keeps cortisol, adrenaline and inflammation switched on, causing cumulative wear and tear on the hippocampus, vessels and metabolism.",95,17],[444,"A man aged 60 becomes depressed after a myocardial infarction with persistently raised CRP. Which mechanism may be causal?","Interleukin-6 signalling, which drives CRP production and may divert tryptophan from serotonin and dampen reward circuits.",95,18],[446,"A woman aged 33 has severe premenstrual irritability and low mood. Are her hormone levels likely abnormal?","No. Levels are usually normal, and her brain responds abnormally to normal hormone changes.",96,1],[446,"What are the core clinical features and timing of premenstrual dysphoric disorder?","Severe irritability, low mood and anxiety in the week before menses, clearing within a few days of bleeding.",96,2],[446,"Where does DSM-5-TR place PMDD and how many symptoms are required?","It is listed with the depressive disorders and requires five symptoms, at least one being a mood symptom.",96,3],[446,"How is the diagnosis of PMDD confirmed?","By prospective daily symptom ratings over at least two cycles. Blood tests do not diagnose it, but thyroid disease should be excluded.",96,4],[447,"What did Schmidt's GnRH agonist add-back study show in PMDD?","Suppressing the cycle removed symptoms, and normal doses of oestradiol or progesterone brought them back only in women with PMDD.",96,5],[447,"What cellular finding did Dubey report in women with PMDD?","Their cells handle steroid-responsive genes differently, through the ESC/E(Z) gene regulatory complex.",96,6],[447,"Which enzymes convert progesterone to allopregnanolone?","5-alpha-reductase and then 3-alpha-hydroxysteroid dehydrogenase.",96,7],[447,"How does allopregnanolone act at the GABA-A receptor, and why can it worsen mood in PMDD?","It is a positive allosteric modulator that usually calms. In sensitive women its luteal rise and fall can provoke anxiety and irritability.",96,8],[447,"What did Martinez show by giving dutasteride in PMDD?","Blocking 5-alpha-reductase prevented the luteal allopregnanolone rise and reduced irritability, sadness and anxiety.",96,9],[447,"How quickly do SSRIs work in PMDD compared with depression?","Within 1 to 2 days, even with luteal-phase-only dosing, compared with weeks in depression.",96,10],[447,"What mechanism may explain the rapid SSRI response in PMDD?","SSRIs may increase neurosteroid (allopregnanolone) synthesis, suggesting PMDD has distinct biology.",96,11],[447,"How is catamenial epilepsy defined in relation to the menstrual cycle?","A two-fold or greater rise in seizure frequency at one phase of the menstrual cycle.",96,12],[447,"Why do seizures increase perimenstrually in catamenial epilepsy?","Calming progesterone and allopregnanolone fall before menses, lowering the seizure threshold, while oestrogen tends to promote seizures.",96,13],[447,"Does transdermal oestradiol help depression before and after the menopause?","Schmidt found it helped perimenopausal depression, but Morrison found no benefit after the menopause when levels are low but stable.",96,14],[447,"What unifying theme links PMDD, postnatal and perimenopausal depression?","Abnormal sensitivity to normal hormone change, rather than abnormal hormone levels.",96,15],[448,"A woman aged 47 with irregular periods and hot flushes has first-onset depression. What mechanism is most likely?","Fluctuating oestradiol during the menopausal transition, rather than stable low oestradiol.",96,16],[450,"How does xanomeline treat psychosis without blocking D2 receptors?","It stimulates M4 receptors in the striatum, reducing dopamine release upstream of D2, and M1 receptors that aid cognition.",97,1],[450,"What is the role of trospium in xanomeline-trospium?","It is a charged quaternary antimuscarinic that does not cross the blood-brain barrier, blocking peripheral nausea, sweating and drooling.",97,2],[450,"What did Berman's 2000 study show about ketamine in depression?","A low-dose intravenous infusion lifted mood within hours rather than weeks.",97,3],[451,"Why does xanomeline-trospium not cause extrapyramidal or prolactin side effects?","D2 receptors are never blocked, so movement and prolactin problems do not arise.",97,4],[451,"What is the regulatory status of xanomeline-trospium?","The FDA approved it in September 2024, and NICE is still appraising it.",97,5],[451,"A woman aged 30 with resistant depression improves within hours of an infusion and feels detached. Which drug?","Ketamine. The detachment is transient dissociation that passes within hours.",97,6],[451,"Describe the cascade behind ketamine's rapid antidepressant effect.","NMDA block on GABA interneurons causes disinhibition and a glutamate surge, activating AMPA receptors, releasing BDNF and switching on mTOR.",97,7],[451,"How quickly do new prefrontal dendritic spines appear after ketamine?","Within 24 hours, matching the clinical timeline.",97,8],[451,"What blocks ketamine's antidepressant effect in rodents?","The mTOR inhibitor rapamycin and AMPA receptor antagonists.",97,9],[451,"What effect does a single ketamine dose have on suicidal ideation?","It reduces suicidal ideation within hours, partly independently of mood, but the effect fades over days.",97,10],[451,"What is esketamine, how is it given and what did NICE decide?","The S-enantiomer of ketamine, given as a supervised nasal spray with an oral antidepressant. NICE TA854 (2022) does not recommend it.",97,11],[451,"How does allopregnanolone differ from benzodiazepines at the GABA-A receptor?","It acts at extrasynaptic delta-subunit receptors setting tonic inhibition, whereas benzodiazepines bind the gamma subunit and miss these receptors.",97,12],[451,"What is zuranolone and what is its UK status?","An oral allopregnanolone analogue taken for 14 days for postnatal depression, approved by the MHRA in August 2025.",97,13],[451,"What is the main side effect of zuranolone and what advice follows?","Sleepiness, so patients must not drive during treatment.",97,14],[451,"How does brexanolone differ from zuranolone?","Brexanolone is an intravenous infusion over 60 hours, FDA approved in 2019 but not licensed in the UK.",97,15],[451,"Which receptor mediates psychedelic effects and how was this shown?","5-HT2A on layer V cortical neurons. Vollenweider showed pretreatment with the 5-HT2A blocker ketanserin abolished psilocybin effects.",97,16],[451,"What is the evidence and legal status of psilocybin for depression in the UK?","Trials with psychological support show benefit, but it missed its main outcome against escitalopram. It is unlicensed and Schedule 1.",97,17],[451,"What is a neuroplastogen and what shared target did Moliner identify?","A drug that rapidly grows new synapses. Moliner found psychedelics bind TrkB, the BDNF receptor, directly.",97,18],[451,"What effect does psilocybin have on the default mode network?","It lowers default mode network activity and broadens brain connectivity.",97,19],[453,"Which ketamine metabolite may act on AMPA receptors directly?","Hydroxynorketamine.",97,20],[455,"What is a star allele and a diplotype in pharmacogenetics?","A star allele is a defined haplotype with a functional status. The pair inherited is the diplotype, translated into a metaboliser phenotype.",98,1],[455,"What are the four CYP metaboliser phenotypes?","Poor, intermediate, normal and ultrarapid metaboliser.",98,2],[455,"A woman aged 34 on nortriptyline has sedation, dry mouth and wide QRS with triple levels. Explanation?","CYP2D6 poor metaboliser status, so the tricyclic accumulates. CPIC advises an alternative drug or halving the dose.",98,3],[456,"Which psychotropic drugs are mainly cleared by CYP2D6?","Tricyclics, paroxetine, venlafaxine, risperidone and aripiprazole.",98,4],[456,"How common are CYP2D6 poor metabolisers in Europeans and which alleles are typical?","About 5 to 10% of Europeans, often carrying two *4 alleles.",98,5],[456,"How common are CYP2D6 ultrarapid metabolisers and why?","About 1 to 2% of Europeans, more in North Africa, due to extra gene copies. They have low drug levels and treatment failure.",98,6],[456,"Which drugs does CYP2C19 clear, and why are East Asian poor metabolisers at risk on citalopram?","Citalopram, escitalopram, sertraline and diazepam. About 15% of East Asians are poor metabolisers, so citalopram levels and QT risk rise.",98,7],[456,"What is the effect of the CYP2C19 *17 allele?","It is a gain-of-function allele that lowers drug levels.",98,8],[456,"Why is codeine dangerous in CYP2D6 ultrarapid metabolisers?","Codeine is a prodrug converted to morphine by CYP2D6, so ultrarapid metabolisers make excess morphine with risk of serious sedation.",98,9],[456,"What did Koren report in 2006 regarding codeine and breastfeeding?","A breastfed infant died after the mother, a CYP2D6 ultrarapid metaboliser, took codeine.",98,10],[456,"What happens when a CYP2D6 poor metaboliser takes codeine?","Little morphine is made, so there is little or no pain relief.",98,11],[456,"What is phenoconversion in relation to CYP2D6 metaboliser status?","A drug interaction where a strong inhibitor such as fluoxetine or paroxetine makes a genetic normal CYP2D6 metaboliser behave like a poor one.",98,12],[456,"Do nicotine replacement patches prevent the rise in clozapine levels after stopping smoking?","No. Hydrocarbons in smoke, not nicotine, induce CYP1A2, so levels should be monitored and the dose reduced.",98,13],[456,"Which HLA allele predicts carbamazepine Stevens-Johnson syndrome and in whom should it be screened?","HLA-B*15:02, found in about 10% of Han Chinese and common in Thai and Malay people. Screen before carbamazepine in these groups.",98,14],[456,"Which HLA allele predicts carbamazepine hypersensitivity across all ancestries, and when do reactions appear?","HLA-A*31:01. Reactions usually appear within the first 8 weeks.",98,15],[456,"What is the evidence for commercial pharmacogenetic panels in psychiatry?","CYP and HLA genes are best evidenced. 5-HTTLPR and COMT are unproven, and combinatorial scores such as GUIDED missed their main outcome.",98,16],[456,"What can a pharmacogenetic report not account for?","Adherence, drug interactions and liver function, so it should inform rather than dictate care.",98,17],[457,"A man aged 44 on clozapine stops smoking and becomes drowsy with a sharp rise in clozapine level. Why?","Tobacco smoke induces CYP1A2. Stopping smoking removes induction, so clozapine levels rise, often by about half within a week.",98,18],[457,"Why does CYP2D6 testing not help predict carbamazepine problems?","Carbamazepine is cleared by CYP3A4, and its serious skin reactions are predicted by HLA genes.",98,19],[457,"Which drug reaction does HLA-B*57:01 predict?","Abacavir hypersensitivity, not carbamazepine reactions.",98,20],[460,"What is the therapeutic event in ECT?","A generalised tonic-clonic seizure. A focal seizure or subconvulsive current does not work.",99,1],[460,"How did Ottosson show that the seizure rather than the current is therapeutic?","In 1960 he shortened seizures with lidocaine while keeping the same current, and the benefit fell.",99,2],[461,"Why is bitemporal ECT chosen for a patient with psychotic depression and food refusal?","Bilateral placement acts faster and more reliably, at the cost of more cognitive side effects.",99,3],[461,"Where are right unilateral electrodes placed and what is their main advantage?","Over the non-dominant hemisphere, causing less amnesia than bilateral placement.",99,4],[461,"What did Sackeim find about right unilateral ECT dosing?","Low-dose unilateral ECT barely worked, but at about six times seizure threshold it nearly matches bilateral with less amnesia.",99,5],[461,"What is the seizure threshold and how do age and sex affect it?","The lowest charge that produces a seizure. It rises with age and is higher in men.",99,6],[461,"How do benzodiazepines affect ECT and how is this managed?","They raise the seizure threshold and shorten seizures. They are reduced or stopped beforehand, or flumazenil is used.",99,7],[461,"A woman aged 70 taking lorazepam has no seizure at ECT. Why?","Benzodiazepines raise the seizure threshold, and older age also raises it.",99,8],[461,"Which factors lower the seizure threshold in ECT?","Caffeine and hyperventilation lower the threshold and lengthen seizures.",99,9],[461,"What happens to the seizure threshold during an ECT course and after a missed seizure?","The threshold rises over a course, so dose is increased. A missed seizure is followed by restimulation at a higher charge.",99,10],[461,"How does the ECT Handbook judge seizure adequacy?","By EEG, not length: clear build-up, high-amplitude rhythmic polyspike and wave activity, and sharp post-ictal suppression.",99,11],[461,"What receptor change did Vetulani and Sulser describe with repeated antidepressant treatment, including ECT?","Downregulation of postsynaptic beta-adrenergic receptors, taking about two weeks.",99,12],[461,"What neurotrophic and structural changes follow a course of ECT?","BDNF rises and hippocampal neurogenesis increases. MRI shows a small reversible hippocampal volume increase, reflecting plasticity, not injury.",99,13],[461,"How does kindling differ from the anticonvulsant hypothesis?","In kindling, repeated stimulation lowers the seizure threshold, whereas the anticonvulsant hypothesis involves a rising threshold.",99,14],[462,"At what dose relative to seizure threshold is bilateral ECT usually given?","About one and a half times the seizure threshold.",99,15],[462,"What is Sackeim's anticonvulsant hypothesis of ECT?","The rising threshold, shorter seizures and increased GABA inhibition over a course are themselves what lift mood.",99,16],[464,"A woman aged 26 with a dog phobia improves with graded exposure. What brain process explains her reduced fear?","Extinction learning. The ventromedial prefrontal cortex forms a new safety memory that inhibits the amygdala, rather than erasing the fear memory.",100,1],[464,"Which receptor type is needed for extinction learning during exposure therapy?","The NMDA glutamate receptor. Extinction is new learning and depends on NMDA receptor activity.",100,2],[464,"What is the animal equivalent of the ventromedial prefrontal cortex that stores extinction memories?","The infralimbic cortex. It holds the new safe memory and uses it to suppress amygdala output.",100,3],[464,"Why is it wrong to say that exposure therapy erases the original fear memory?","The original fear memory persists in the amygdala. Extinction lays a new inhibitory memory over it, so fear can return later.",100,4],[464,"Name the three ways an extinguished fear can return after successful exposure therapy.","Renewal in a new context, spontaneous recovery with the passage of time, and reinstatement after stress.",100,5],[464,"Why should exposure therapy be practised in a variety of settings?","Because extinction is context-bound, so fear can be renewed in a new place. Varied practice makes the safety learning generalise.",100,6],[464,"What did Kandel argue in 1998 about psychotherapy and the brain?","He argued that therapy works through learning, and learning alters synapses, so talking therapy is a biological treatment.",100,7],[464,"What did Baxter find in 1992 when scanning people with OCD treated with fluoxetine or behaviour therapy?","Responders to either treatment showed reduced glucose metabolism in the right caudate nucleus, so both calmed the same circuit.",100,8],[465,"How do antidepressants and CBT differ in the direction in which they act on mood circuits?","Antidepressants act bottom-up by damping amygdala reactivity. CBT acts top-down by strengthening prefrontal control of emotion.",100,9],[465,"Do antidepressants and CBT act on entirely separate brain systems in depression?","No. They start at different levels but converge on a shared prefrontal-limbic circuit, as Goldapple showed in 2004 with CBT and paroxetine.",100,10],[465,"In McGrath's 2013 PET study, which insula pattern predicted remission with CBT?","Low glucose metabolism in the right anterior insula predicted remission with CBT and poor response to escitalopram.",100,11],[465,"In McGrath's study, what did high right anterior insula metabolism predict?","Better response to escitalopram and poor response to CBT. This is a group research finding, not a clinical test yet.",100,12],[465,"What is D-cycloserine and how was it used by Ressler in 2004?","It is an NMDA partial agonist. Given before exposure for fear of heights, it improved outcomes more than placebo.",100,13],[465,"Does D-cycloserine treat anxiety on its own?","No. It only speeds up extinction learning when combined with exposure; it has no anxiolytic effect by itself.",100,14],[465,"What is memory reconsolidation and why does it offer a window for change?","When a memory is recalled it becomes briefly unstable and must be stored again, giving a window in which it can be changed.",100,15],[465,"What did Nader show in 2000 about reconsolidation of fear memories in rats?","Blocking protein synthesis in the amygdala just after recall caused the fear memory to be lost.",100,16],[465,"What did Schiller find in 2010 when extinction training was given within the reconsolidation window?","The fear did not return afterwards, suggesting the original memory had been updated rather than merely inhibited.",100,17],[465,"How was propranolol used in PTSD reconsolidation studies by Brunet?","Given after trauma recall, it reduced later physiological arousal during trauma imagery.",100,18],[465,"How does reconsolidation differ from extinction?","Reconsolidation reopens and modifies the old memory itself. Extinction leaves the old memory intact and adds a new competing safety memory.",100,19],[468,"A woman aged 41 with depression unresponsive to two antidepressants is referred for rTMS. What is the standard frequency and target?","High-frequency 10 Hz excitatory stimulation over the left dorsolateral prefrontal cortex.",101,1],[468,"Why is the left dorsolateral prefrontal cortex stimulated with high-frequency rTMS in depression?","The left DLPFC is underactive in depression, and high-frequency pulses increase cortical excitability there.",101,2],[468,"What is the resting motor threshold in rTMS?","The lowest output that produces a contralateral thumb twitch on at least half of ten pulses. It is used to set each person's dose.",101,3],[468,"At what intensity is antidepressant rTMS usually given?","About 120% of the individual's resting motor threshold. This is a dosing measure, not a seizure threshold as in ECT.",101,4],[468,"Describe a standard course of rTMS for depression.","About 3000 pulses per session, five days a week for 4 to 6 weeks.",101,5],[468,"Where and at what frequency is inhibitory rTMS applied in depression?","Low-frequency 1 Hz stimulation is applied over the right DLPFC.",101,6],[468,"What is theta burst stimulation and how does it compare with standard rTMS?","It delivers 50 Hz triplets in a roughly 3-minute session. Blumberger in 2018 found it as effective as 10 Hz rTMS.",101,7],[469,"What is the NICE position on rTMS for depression?","NICE HealthTech guidance HTG396, formerly IPG542, supports rTMS with normal arrangements.",101,8],[469,"How does rTMS compare with ECT for severe, psychotic or suicidal depression?","ECT remains more effective. rTMS has the advantage of needing no anaesthetic and causing no memory loss.",101,9],[469,"Why is evidence for rTMS limited in people over 65?","Older adults were mostly excluded from trials, and brain atrophy increases the distance between coil and cortex.",101,10],[469,"What are the commonest and the most serious side effects of rTMS?","Headache and scalp discomfort are commonest and mild. Seizure is the most serious but rare, under 1 in 1000 sessions.",101,11],[469,"What are absolute contraindications to rTMS?","Metal or electronic devices in or near the head, such as cochlear implants and aneurysm clips.",101,12],[469,"Which factors need caution but are not absolute contraindications to rTMS?","A chest pacemaker, epilepsy and seizure-lowering drugs. Antidepressants, migraine and dental fillings are not a problem.",101,13],[469,"How does transcranial direct current stimulation work, and where is the anode placed for depression?","A weak 1 to 2 mA current alters resting membrane potential without firing neurons. The anode goes over the left DLPFC.",101,14],[469,"What did Brunoni find in 2017 comparing tDCS with escitalopram, and what does NICE advise?","tDCS beat sham but was inferior to escitalopram. NICE allows it only with special arrangements or in research.",101,15],[469,"What are the deep brain stimulation targets in Parkinson's disease, tremor and dystonia?","Subthalamic nucleus or GPi for Parkinson's, ventral intermediate thalamus for tremor, and GPi for dystonia.",101,16],[469,"Which deep brain stimulation targets have been used for OCD and for depression?","For OCD the anterior limb of the internal capsule and ventral striatum. Mayberg targeted the subcallosal cingulate, area 25, for depression.",101,17],[469,"Why is vagus nerve stimulation applied to the left rather than the right vagus?","The right vagus supplies the sinoatrial node, so right-sided stimulation risks bradycardia.",101,18],[469,"What is the NICE position on vagus nerve stimulation for depression?","NICE HTG551 allows it only with special arrangements, and the mood benefit builds slowly over months.",101,19],[470,"A man aged 40 with refractory epilepsy and a neck nerve cuff notices better mood after a year. What is the pathway?","Left vagus nerve stimulation sends signals to the nucleus of the solitary tract, then to the locus coeruleus and raphe nuclei.",101,20],[472,"Which transmitter and receptor are used at all autonomic ganglia, sympathetic and parasympathetic?","Acetylcholine acting on nicotinic receptors.",102,1],[472,"What transmitter do most sympathetic postganglionic fibres release onto blood vessels and the heart?","Noradrenaline.",102,2],[473,"What do parasympathetic postganglionic fibres release, and onto which receptors?","Acetylcholine onto muscarinic receptors.",102,3],[473,"What are the two main exceptions to the usual sympathetic pattern?","Sweat glands receive acetylcholine on muscarinic receptors, and the adrenal medulla acts like a ganglion releasing adrenaline into the blood.",102,4],[473,"What is respiratory sinus arrhythmia in a healthy heart?","The normal rise in heart rate on breathing in and fall on breathing out, reflecting vagal control.",102,5],[473,"What does heart rate variability mainly reflect?","Vagal, or parasympathetic, control of the heart. It is not average heart rate, contractility or the QT interval.",102,6],[473,"What happens to heart rate variability in depression and anxiety, and what does it signify?","It is reduced, as Kemp showed in 2010, indicating low vagal tone with relative sympathetic dominance.",102,7],[473,"Whose model links heart rate variability to prefrontal control of the amygdala?","Thayer's model, which links higher HRV to stronger prefrontal regulation of the amygdala.",102,8],[473,"What breathing rate is used in HRV biofeedback and why?","About 6 breaths a minute, near 0.1 Hz, which resonates with the baroreflex and raises vagal tone.",102,9],[473,"How do tricyclics, clozapine and quetiapine cause dizziness and falls?","They block alpha-1 adrenoceptors, preventing reflex vasoconstriction on standing and causing orthostatic hypotension.",102,10],[473,"How is orthostatic hypotension defined in terms of blood pressure and timing?","A fall in blood pressure of at least 20 mmHg systolic or 10 mmHg diastolic within 3 minutes of standing.",102,11],[473,"A woman aged 22 has palpitations on standing and is thought to be anxious. How is postural tachycardia syndrome defined?","A heart rate rise of at least 30 beats a minute on standing without a significant fall in blood pressure.",102,12],[473,"How does a vasovagal faint differ from postural tachycardia syndrome?","A vasovagal faint is a brief reflex fall in both heart rate and blood pressure, whereas POTS has tachycardia without hypotension.",102,13],[473,"What is the enteric nervous system and roughly how many neurons does it contain?","A network of about 500 million neurons in the gut wall that controls motility and secretion independently, the second brain.",102,14],[473,"Through which main route does the gut communicate with the brain in the gut-brain axis?","Mainly vagal afferent fibres, together with gut microbes and immune signals.",102,15],[473,"In which psychiatric disorders is interoceptive accuracy altered?","Panic disorder, anxiety and eating disorders.",102,16],[473,"A man aged 55 who drinks heavily has numb feet and absent ankle reflexes. Why are the feet affected first?","Alcohol neuropathy is length-dependent, so the longest nerves fail first, giving a glove-and-stocking pattern. Give thiamine before glucose.",102,17],[473,"How does recreational nitrous oxide cause subacute combined degeneration?","It oxidises the cobalt in vitamin B12, inactivating methionine synthase and causing functional B12 deficiency affecting dorsal columns and nerves.",102,18],[473,"A man aged 23 using nitrous oxide has a normal B12 level but sensory ataxia. How is deficiency confirmed and treated?","Raised homocysteine or methylmalonic acid confirms functional deficiency. Treat with B12 and stop the nitrous oxide.",102,19],[474,"A woman aged 27 with panic disorder counts her heartbeats during fMRI. Which sense and brain region are tested?","Interoception, the sense of the body's internal state, which Craig mapped to the insula.",102,20],[477,"A man aged 42 with Huntington's disease has worsening chorea. What striatal chemical change best explains it?","Loss of GABAergic medium spiny neurons with reduced glutamic acid decarboxylase, weakening the indirect pathway.",103,1],[477,"What is meant by prion-like spread in neurodegeneration?","A misfolded protein seed templates normal copies into its shape and spreads along connected neurons. It is not transmissible between people.",103,2],[478,"What did Clavaguera show in 2009 by injecting clumped tau into mouse hippocampus?","Tau inclusions formed at the injection site and then in synaptically connected regions, showing spread along networks.",103,3],[478,"What proportion of cognitively normal people over 70 have a positive amyloid PET scan?","About 1 in 3, and amyloid builds up for 15 to 20 years before symptoms.",103,4],[478,"What is primary age-related tauopathy, and who does it affect?","Neurofibrillary tangles limited to medial temporal memory areas in very old people, with little or no amyloid.",103,5],[478,"What is LATE and how does it present clinically?","Limbic-predominant age-related TDP-43 encephalopathy, often with hippocampal sclerosis. It causes slow amnesia with negative amyloid tests.",103,6],[478,"What is dual pathology, and what did Robinson find in 2018?","Having more than one disease process in the brain. Alzheimer change often coexisted with Lewy bodies, TDP-43 and vascular damage, lowering the dementia threshold.",103,7],[478,"Describe the three NIA-AA 2011 research stages of preclinical Alzheimer's disease.","Stage 1 is amyloid alone, stage 2 adds neuronal injury such as raised CSF tau, and stage 3 adds subtle cognitive decline.",103,8],[478,"A man aged 64 acts out his dreams. What proportion develop a synucleinopathy within 12 years?","About 74% of people with REM sleep behaviour disorder develop a synuclein disease within 12 years.",103,9],[478,"What is mild cognitive impairment and how often does it progress to dementia in clinic samples?","Decline beyond that expected for age with independence preserved. About 10 to 15% a year convert, and some revert to normal.",103,10],[478,"Give an example of a disease spectrum caused by a single gene mutation.","A C9orf72 repeat expansion can cause frontotemporal dementia, motor neurone disease, or both within one family.",103,11],[478,"How does DSM-5-TR distinguish mild from major neurocognitive disorder?","Mild disorder is modest decline with independence kept. Major disorder is decline that requires help with daily life.",103,12],[478,"How did Stern distinguish brain reserve from cognitive reserve?","Brain reserve is structural, such as brain size. Cognitive reserve is built by education, complex work and bilingualism.",103,13],[478,"What is the effect of high cognitive reserve on the course of dementia?","Symptoms start later for the same pathology, but once they appear decline is faster.",103,14],[478,"What did Snowdon's Nun Study find about early-life writing?","Low idea density in essays written around age 22 predicted Alzheimer's disease decades later.",103,15],[478,"How does resilience differ from resistance in neurodegeneration?","Resilience is keeping cognition despite heavy pathology. Resistance is not developing the pathology at all.",103,16],[478,"What did the 2024 Lancet Commission conclude about modifiable dementia risk?","About 45% of dementia is linked to 14 modifiable risk factors, including high LDL cholesterol and vision loss.",103,17],[478,"What is the genetics of Huntington's disease and why is onset earlier with paternal transmission?","Autosomal dominant CAG expansion in HTT on chromosome 4p. Repeats expand in sperm, causing anticipation through the father.",103,18],[478,"A woman aged 76 has gait disturbance, then urinary incontinence and cognitive decline. Which treatable condition and test are key?","Normal pressure hydrocephalus. Improvement in walking after a 30 to 50 mL lumbar tap predicts benefit from a shunt.",103,19],[479,"How many CAG repeats give full and reduced penetrance in Huntington's disease?","40 or more repeats give full penetrance; 36 to 39 give reduced penetrance.",103,20],[482,"A trainee sees flame-shaped silver-staining structures of paired helical filaments in hippocampal neurons. What is the main protein?","Hyperphosphorylated tau, forming intracellular neurofibrillary tangles.",104,1],[482,"What is the normal function of tau and what happens when it becomes hyperphosphorylated?","Tau stabilises microtubules. Excess phosphate makes it detach, so microtubules collapse, axonal transport fails and tau aggregates into paired helical filaments.",104,2],[482,"Describe the macroscopic appearance of the brain in advanced Alzheimer's disease.","Diffuse atrophy, often under 1000 g, worst in temporal and parietal lobes, with widened sulci and enlarged ventricles.",104,3],[482,"What is hydrocephalus ex vacuo in Alzheimer's disease?","Ventricular enlargement that passively fills the space left by brain atrophy, rather than raised pressure.",104,4],[482,"Which cortical areas are spared until late in Alzheimer's disease?","Primary motor, sensory and visual cortex, which is why walking and basic movement are kept for years.",104,5],[482,"Which tau isoforms are found in Alzheimer neurofibrillary tangles?","Both three-repeat and four-repeat tau, a mixed 3R and 4R pattern.",104,6],[483,"A woman aged 81 has plaque cores showing apple-green birefringence with Congo red. Which protein forms the core?","Amyloid-beta folded into beta-pleated sheets. The surrounding dystrophic neurites contain tau.",104,7],[483,"What are Hirano bodies and granulovacuolar degeneration?","Hirano bodies are eosinophilic actin rods in CA1 pyramidal cells. Granulovacuolar degeneration is clear vacuoles each with a dark central granule.",104,8],[483,"Describe the Braak and Braak stages of tangle spread in Alzheimer's disease.","Stages I to II affect the entorhinal cortex, III to IV the hippocampus and amygdala, and V to VI the neocortex.",104,9],[483,"Why is new learning the first function to fail in Alzheimer's disease?","Tangles start in the entorhinal cortex, which is the main input gateway to the hippocampus.",104,10],[483,"Which pathological measures correlate best with cognitive decline in Alzheimer's disease?","Tangle stage and synapse loss correlate best; plaque counts correlate poorly, as Nelson showed in 2012.",104,11],[483,"What did Whitehouse find in 1982, and what cholinergic enzyme changes occur in Alzheimer's cortex?","Marked cell loss in the nucleus basalis of Meynert. Choline acetyltransferase and acetylcholinesterase fall, while butyrylcholinesterase rises.",104,12],[483,"How is amyloid precursor protein processed to produce or avoid amyloid-beta?","Alpha-secretase cuts within the amyloid-beta region and prevents it. Beta-secretase (BACE1) then gamma-secretase release amyloid-beta.",104,13],[483,"What is the role of presenilin, and which amyloid-beta form is most aggregation-prone?","Presenilin is the catalytic part of gamma-secretase. Abeta42 is stickier than Abeta40.",104,14],[483,"What is the strongest evidence for the amyloid cascade hypothesis?","Every autosomal dominant Alzheimer gene mutation increases Abeta42 production.",104,15],[483,"On which chromosomes are APP, PSEN1 and PSEN2, and which is the commonest familial cause?","APP on 21, PSEN1 on 14 and PSEN2 on 1. PSEN1 is the commonest cause with the earliest onset.",104,16],[483,"Why do people with Down syndrome have a high risk of Alzheimer's disease?","The APP gene is on chromosome 21, so trisomy 21 gives an extra copy and more amyloid-beta.",104,17],[483,"How does APOE genotype alter Alzheimer's risk?","APOE is on chromosome 19. One e4 copy raises risk about 3 times and two copies about 10 to 15 times; e2 is protective.",104,18],[483,"A man aged 70 has gradual loss of new memories. What CSF pattern supports Alzheimer's disease?","Low Abeta42, because it is trapped in plaques, with raised phospho-tau and total tau.",104,19],[483,"What is the current UK status of lecanemab and donanemab?","Both are licensed by the MHRA, but NICE did not recommend them for NHS use in its 2025 guidance.",104,20],[487,"A man aged 76 with atrial fibrillation has three sudden stepwise declines and a left hemiparesis. What will post mortem show?","Multiple cortical and subcortical infarcts of different ages, indicating multi-infarct dementia.",105,1],[487,"What causes the stepwise course of multi-infarct dementia?","Repeated emboli from the heart or large arteries cause sudden losses, each followed by partial recovery.",105,2],[487,"What is the typical change in small penetrating arteries in hypertensive small vessel disease?","Hyaline arteriolosclerosis, with thickened walls and narrowed lumens, causing lacunes and white matter damage.",105,3],[488,"What is Binswanger's disease and how does it present?","Diffuse deep white matter damage with lacunes and cortical sparing, giving slow apathy, short-stepped gait and urinary urgency.",105,4],[488,"What is a strategic infarct in vascular dementia?","A single small stroke in a critical location that is enough to cause dementia.",105,5],[488,"Which single infarct causes sudden apathy, hypersomnolence and amnesia?","A paramedian thalamic infarct from posterior cerebral artery perforators. An artery of Percheron occlusion can affect both sides.",105,6],[488,"Which strategic infarct can mimic sudden Alzheimer's disease with alexia, agraphia and anomia?","A dominant, usually left, angular gyrus infarct.",105,7],[488,"What is the typical cognitive profile of vascular cognitive impairment?","Slowed processing and executive dysfunction, with poor free recall that improves with cues and recognition.",105,8],[488,"Why do cues help recall in vascular dementia but not in Alzheimer's disease?","In vascular dementia memories are stored but hard to retrieve. In Alzheimer's encoding fails, so the memory is never stored.",105,9],[488,"Why are depression and tearfulness common in vascular dementia?","Insight and personality are often preserved, so people are aware of their deficits.",105,10],[488,"What three elements do the NINDS-AIREN criteria require for vascular dementia?","Dementia, evidence of cerebrovascular disease, and a link such as onset within 3 months of stroke or abrupt stepwise decline.",105,11],[488,"What is the main weakness of the NINDS-AIREN criteria?","They are specific but insensitive, missing many slowly progressive small vessel cases.",105,12],[488,"How is the Hachinski ischaemic score interpreted?","A score of 7 or more favours vascular dementia and 4 or less favours degenerative dementia. It handles mixed disease poorly.",105,13],[488,"A man aged 45 with migraine with aura, depression and lacunar strokes has a family history. What is the diagnosis and gene?","CADASIL, an autosomal dominant condition caused by NOTCH3 mutations on chromosome 19.",105,14],[488,"What are the characteristic MRI and biopsy findings in CADASIL?","White matter change in the anterior temporal poles and external capsules, and granular osmiophilic material in vessel walls on skin biopsy.",105,15],[488,"What is cerebral amyloid angiopathy and how does it present?","Mainly Abeta40 deposited in cortical vessel walls, causing recurrent lobar haemorrhages, lobar microbleeds and superficial siderosis.",105,16],[488,"How do bleeding sites differ between amyloid angiopathy and hypertension?","Amyloid angiopathy causes lobar bleeds, while hypertension causes deep bleeds.",105,17],[488,"What is the commonest pathology in dementia over 85, and what did MRC CFAS show?","Mixed Alzheimer and vascular pathology. Vascular damage lowers the threshold at which Alzheimer change causes dementia.",105,18],[489,"A woman aged 74 with long-standing hypertension has apathy, shuffling gait and urgency. How does MRI separate Binswanger's from NPH?","Binswanger's shows confluent periventricular white matter change and lacunes. NPH shows ventricles enlarged out of proportion to sulci.",105,19],[491,"A man aged 58 with disinhibition has knife-blade frontal and anterior temporal atrophy with posterior sparing. What is the diagnosis?","Pick's disease, a 3R tauopathy with sharply bounded frontotemporal atrophy.",106,1],[491,"What six features are in the 2011 Rascovsky criteria for behavioural variant FTD, and how many are needed?","Disinhibition, apathy, loss of empathy, compulsive behaviour, hyperorality and dysexecutive profile. Three are needed for possible bvFTD.",106,2],[491,"A man aged 55 with crude remarks and sweet cravings scores 27 of 30 on a memory screen. Does this exclude bvFTD?","No. Memory and drawing are often preserved early, so the informant history of behaviour change is decisive.",106,3],[492,"What are the features and atrophy site of non-fluent agrammatic primary progressive aphasia?","Slow, effortful, telegraphic speech with sound errors and lost grammar words, from left posterior frontal and insular atrophy, usually tau.",106,4],[492,"What are the features and pathology of semantic variant primary progressive aphasia?","Fluent speech with loss of word meaning and preserved daily memory, from left anterior temporal atrophy, usually TDP-43 type C.",106,5],[492,"What bedside fluency pattern suggests semantic dementia?","Category fluency, such as naming animals, is much worse than letter fluency.",106,6],[492,"What happens when semantic dementia affects mainly the right anterior temporal lobe?","The person loses knowledge of people, with difficulty recognising who familiar people are.",106,7],[492,"A woman aged 64 has word-finding pauses and cannot repeat long sentences. What variant, atrophy site and usual cause?","Logopenic primary progressive aphasia, with left temporoparietal atrophy, usually due to Alzheimer's disease.",106,8],[492,"What is posterior cortical atrophy and its usual cause?","Progressive parietal and occipital degeneration causing higher visual problems with normal eyes and preserved memory, usually from Alzheimer's disease.",106,9],[492,"What are the three components of Balint syndrome?","Simultanagnosia, optic ataxia and oculomotor apraxia, from bilateral dorsal stream damage.",106,10],[492,"What are the features of Gerstmann syndrome and where is the lesion?","Finger agnosia, left-right confusion, acalculia and agraphia, from the dominant angular gyrus.",106,11],[492,"What are the approximate proportions of proteins underlying frontotemporal lobar degeneration?","TDP-43 about 50%, tau about 40% and FUS under 10%.",106,12],[492,"What are the features of FTLD-FUS?","Young onset, often sporadic, with obsessive behaviour and marked caudate atrophy; inclusions are negative for tau and TDP-43.",106,13],[492,"How is 3R or 4R tau determined, and which diseases have each type?","By splicing of MAPT exon 10. Pick's is 3R, PSP and corticobasal degeneration are 4R, and Alzheimer's has both.",106,14],[492,"What are Pick bodies and how are they best shown?","Round tau inclusions in dentate gyrus granule cells, shown with tau and ubiquitin immunostaining and Bielschowsky silver, but not Gallyas silver.",106,15],[492,"A man aged 52 with FTD develops psychosis and has relatives with motor neurone disease. Which gene is likely?","A C9orf72 GGGGCC repeat expansion on chromosome 9p21, the commonest familial cause of FTD and ALS, with TDP-43 pathology.",106,16],[492,"How do MAPT and GRN mutations differ despite both lying on chromosome 17q21?","MAPT gives tau-positive FTD with parkinsonism. GRN gives TDP-43 disease, often asymmetric with parietal atrophy and very low plasma progranulin.",106,17],[492,"A man aged 68 has early backward falls and cannot look down. What is the diagnosis and MRI sign?","Progressive supranuclear palsy, with midbrain atrophy and preserved pons giving the hummingbird sign.",106,18],[492,"Why is the gaze palsy in PSP called supranuclear?","The eyes still move on passive head tilting, so the lesion lies above the eye movement nuclei.",106,19],[492,"What are the clinical and pathological features of corticobasal degeneration, and how does it differ from PSP histologically?","Alien limb, asymmetric apraxia and myoclonus, with astrocytic plaques. PSP has tufted astrocytes instead.",106,20],[496,"A man aged 70 has bradykinesia, rest tremor, rigidity and reduced DaTscan uptake. Which lesion explains this?","Loss of dopamine neurons in the substantia nigra pars compacta projecting to the striatum.",107,1],[496,"What did Ehringer and Hornykiewicz show in 1960?","Striatal dopamine was markedly reduced in the brains of people with Parkinson's disease.",107,2],[496,"How much striatal dopamine is lost before the motor signs of Parkinson's disease appear?","About 70 to 80%, which explains the long silent prodrome.",107,3],[496,"Why does the midbrain look pale at post mortem in Parkinson's disease?","The neuromelanin-containing dopamine cells of the substantia nigra pars compacta have died; the locus coeruleus also looks pale.",107,4],[496,"How do D2-blocking antipsychotics cause parkinsonism?","They block dopamine at striatal D2 receptors, mimicking the dopamine shortage of Parkinson's disease.",107,5],[496,"Which pathological changes are wrongly attributed to Parkinson's disease but belong to Huntington's disease?","Caudate atrophy and loss of striatal GABAergic medium spiny neurons.",107,6],[497,"What is a Lewy body and what is it mainly made of?","A round eosinophilic neuronal inclusion with a dense core and pale halo, made mainly of alpha-synuclein with ubiquitin and p62. It is tau-negative.",107,7],[497,"Where does Lewy pathology begin in Braak staging, and what early symptoms does this explain?","In the olfactory bulb and dorsal vagal motor nucleus at stages 1 to 2, explaining early loss of smell and constipation.",107,8],[497,"At which Braak stages are the substantia nigra, limbic areas and neocortex reached?","The nigra at stage 3 when motor signs begin, limbic areas at stage 4 and neocortex at stages 5 to 6.",107,9],[497,"Which is the commonest dominant Parkinson's gene, and in which populations is G2019S common?","LRRK2. The G2019S variant is common in Ashkenazi Jewish and North African Berber people.",107,10],[497,"A woman aged 30 has Parkinson's disease with dystonia. Which recessive genes are likely?","Biallelic PRKN (parkin) or PINK1 mutations, which impair clearance of damaged mitochondria.",107,11],[497,"What is the commonest genetic risk factor for Parkinson's disease, and what does it do?","A single GBA variant, raising risk about 5-fold and speeding cognitive decline. Two copies cause Gaucher disease.",107,12],[497,"How does the drug contaminant MPTP cause parkinsonism?","Glial MAO-B converts it to MPP+, which the dopamine transporter carries into nigral cells, where it inhibits mitochondrial complex I.",107,13],[497,"What are the four core features of dementia with Lewy bodies in the 2017 criteria?","Fluctuating cognition, recurrent visual hallucinations, REM sleep behaviour disorder and parkinsonism.",107,14],[497,"How is probable dementia with Lewy bodies diagnosed, and what are the indicative biomarkers?","Two core features, or one core feature plus one indicative biomarker: low DaTscan uptake, low cardiac MIBG uptake or REM sleep without atonia.",107,15],[497,"How does the one-year rule separate DLB from Parkinson's disease dementia?","Dementia before or within one year of parkinsonism is DLB; later dementia is Parkinson's disease dementia. The pathology is the same.",107,16],[497,"A man aged 78 with DLB becomes rigid and drowsy after haloperidol. What is this and how common is it?","Severe neuroleptic sensitivity, affecting up to half of people with DLB, and it can be fatal.",107,17],[497,"How do MSA-P and MSA-C differ, and what MRI sign occurs in MSA-C?","MSA-P gives parkinsonism with poor levodopa response; MSA-C gives ataxia with the hot cross bun sign in the pons.",107,18],[497,"Which neurodegenerative disorders are synucleinopathies and which related disorders are tauopathies?","Parkinson's disease, Parkinson's disease dementia, DLB and MSA are synucleinopathies. PSP and corticobasal degeneration are tauopathies.",107,19],[498,"A woman aged 60 has parkinsonism with poor levodopa response, postural faintness and urinary retention. What is the pathology?","Multiple system atrophy, with alpha-synuclein glial cytoplasmic inclusions in oligodendrocytes, described by Papp and Lantos.",107,20],[500,"How can an agent with no nucleic acid cause Creutzfeldt-Jakob disease?","Misfolded PrPSc acts as a template that converts normal PrPC into protease-resistant beta-sheet protein.",108,1],[500,"Which gene encodes prion protein and on which chromosome?","PRNP, on chromosome 20.",108,2],[500,"How do the structures of normal PrPC and abnormal PrPSc differ?","PrPC is mainly alpha-helix and protease-sensitive. PrPSc is beta-sheet and resists protease, heat and formalin.",108,3],[500,"What did Prusiner discover in 1982?","Purified scrapie agent contained protein but no nucleic acid, which he called a prion.",108,4],[500,"Why is there no immune or inflammatory response in prion disease?","The prion is a misfolded host protein, so it is not recognised as foreign.",108,5],[501,"What is spongiform change and what makes up the classic histological triad of prion disease?","Small round holes in grey matter neuropil from swollen nerve endings, together with neuronal loss and reactive astrocytosis.",108,6],[501,"Why may a sporadic CJD brain look normal to the naked eye?","Death occurs within months, so there is little time for marked atrophy.",108,7],[501,"Which prion diseases can cause isolated cerebellar atrophy?","Ataxic forms such as the VV2 subtype of sporadic CJD and kuru.",108,8],[501,"How is abnormal prion protein demonstrated in brain tissue?","PrP immunostaining after formic acid and protease treatment; protease destroys normal PrPC, leaving only PrPSc to stain.",108,9],[501,"A man aged 66 has dementia worsening over weeks with startle myoclonus and ataxia. What is likely and what is the prognosis?","Sporadic CJD, the commonest form, with most people dying within about 4 to 6 months.",108,10],[501,"What MRI finding is typical of sporadic CJD?","Diffusion-weighted high signal in the cortical ribbon and caudate heads.",108,11],[501,"What EEG finding occurs in sporadic CJD?","Periodic sharp-wave complexes at about 1 Hz in around two thirds, often not present early.",108,12],[501,"Which CSF test is most accurate for sporadic CJD?","RT-QuIC, which detects prion seeds with about 90% sensitivity and 98 to 100% specificity. 14-3-3 is less specific.",108,13],[501,"How does variant CJD differ from sporadic CJD in age, course and investigations?","Median onset about 28 versus 65, a longer course of about 14 months, and EEG and 14-3-3 are often normal.",108,14],[501,"Why is tonsil biopsy positive in variant CJD?","Prions enter through food and accumulate in lymphoid tissue before reaching the brain.",108,15],[501,"What are the causes of iatrogenic CJD?","Cadaveric pituitary growth hormone, dura mater grafts and contaminated surgical instruments, with incubation lasting decades.",108,16],[501,"How was kuru transmitted and what was its incubation period?","By ritual mortuary feasts, with incubation that could exceed 50 years.",108,17],[501,"What is the genetics and pathology of fatal familial insomnia?","PRNP D178N mutation with methionine at codon 129, destroying the anterior and mediodorsal thalamus, causing insomnia and autonomic overactivity.",108,18],[502,"A man aged 24 has depression, painful legs and later ataxia. MRI shows bright pulvinar signal. What is the diagnosis?","Variant CJD, linked to BSE-contaminated beef, with the pulvinar sign seen in over 90%.",108,19],[504,"How does HIV cross the blood-brain barrier within days of infection?","Inside infected monocytes that become perivascular macrophages, the Trojan horse route.",109,1],[504,"Which brain cells does HIV infect, and through which receptors?","Microglia and perivascular macrophages, via CD4 and chemokine receptors. Neurons lack CD4 and are not infected.",109,2],[504,"Why does HIV remain in the brain despite effective antiretroviral treatment?","Early seeding of macrophages and microglia creates a persistent brain reservoir.",109,3],[504,"How does HIV damage neurons if it does not infect them?","Indirectly, through gp120, Tat, TNF and quinolinic acid, which overstimulate NMDA receptors.",109,4],[504,"What did Koenig show in 1986 about AIDS dementia?","HIV was present in brain macrophages of people with AIDS dementia.",109,5],[505,"What is the cognitive pattern of HIV-associated dementia?","Subcortical: slowed thinking, apathy, poor attention and unsteady gait, with language preserved.",109,6],[505,"A man aged 38 who injects drugs has weight loss, apathy and slowing. What test must be done first?","An HIV test, because antiretroviral treatment can reverse much of the decline.",109,7],[505,"How do the 2007 Frascati criteria define asymptomatic neurocognitive impairment?","Test scores at least 1 SD below norms in two domains, with no effect on daily life.",109,8],[505,"How do mild neurocognitive disorder and HIV-associated dementia differ under the Frascati criteria?","Mild disorder adds mild interference with daily life. Dementia needs at least 2 SD impairment with marked functional decline.",109,9],[505,"How common is HIV-associated neurocognitive disorder in the antiretroviral era?","Dementia is now rare, but milder HAND persists in about 30 to 50%, even with undetectable virus.",109,10],[505,"Below what CD4 count do opportunistic brain infections such as toxoplasmosis become likely?","Below 200 cells per microlitre.",109,11],[505,"A woman aged 35 with AIDS has fever and multiple ring-enhancing basal ganglia lesions. What is likely, and what gives a single lesion?","Toxoplasmosis causes multiple ring-enhancing lesions; primary CNS lymphoma is usually a single lesion.",109,12],[505,"What causes progressive multifocal leukoencephalopathy and how does it appear on MRI?","JC virus killing oligodendrocytes, giving patchy white matter lesions without enhancement or mass effect.",109,13],[505,"How is PML diagnosed and treated?","JC virus PCR in CSF confirms it, and restoring immune function is the only treatment.",109,14],[505,"A man aged 50 has grandiosity, poor judgement, dementia and slurred speech. What is likely and which pupil sign may occur?","General paresis of neurosyphilis. Argyll Robertson pupils are small, irregular and react to accommodation but not light.",109,15],[505,"Which syphilis blood tests track disease activity and which stay positive for life?","RPR and VDRL titres fall with cure and track activity. Treponemal tests such as EIA stay positive for life.",109,16],[505,"How does rabies reach the brain and what inclusion does it form?","It travels up peripheral nerves after a bite and forms cytoplasmic Negri bodies in hippocampal and Purkinje cells.",109,17],[505,"How do Cowdry type A bodies differ from Negri bodies?","Cowdry type A bodies are intranuclear, seen in herpes and SSPE. Negri bodies are cytoplasmic, seen in rabies.",109,18],[506,"A man who died of untreated AIDS with dementia has pale white matter. What are the histological features of HIV encephalitis?","Multinucleated giant cells formed by gp120-induced fusion, microglial nodules and white matter pallor.",109,19],[508,"What type of head injury exposure is thought to drive chronic traumatic encephalopathy?","Many repeated head impacts over years, most of which never cause concussion. Risk rises with the number of years of exposure.",110,1],[508,"A man aged 58 played professional football for 16 years without ever losing consciousness. Does the lack of concussion rule out CTE?","No. CTE is linked to thousands of small sub-concussive impacts such as heading, not to one dramatic injury with loss of consciousness.",110,2],[508,"What did Mackay's 2019 study find about former Scottish professional footballers?","They were about 3.5 times as likely to die of neurodegenerative disease, and later work found defenders were at highest risk.",110,3],[508,"Who first described the punch drunk syndrome in boxers, and in what year?","Martland described it in 1928. It was later called dementia pugilistica.",110,4],[508,"What was the main microscopic finding in Corsellis's 1973 study of retired boxers' brains?","Many neurofibrillary tangles made of tau but few amyloid plaques, which differs from Alzheimer's disease.",110,5],[508,"Which gross brain changes did Corsellis describe in retired boxers?","A torn, holed cavum septum pellucidum, a thin corpus callosum, enlarged ventricles, cerebellar scarring and cell loss in the substantia nigra.",110,6],[508,"Is APOE e4 alone enough to cause CTE without any head impacts?","No. APOE e4 may alter risk, but CTE is not seen without exposure to repeated head impacts.",110,7],[509,"What lesion defines CTE according to the 2016 McKee consensus criteria?","Phosphorylated tau in neurons, with or without astrocytes, clustered around small vessels at the depths of the cortical sulci in an irregular pattern.",110,8],[509,"Why does tau collect at the depths of the cortical sulci in CTE?","The sulcal depths take the greatest mechanical strain when the head is struck.",110,9],[509,"Where does tau pathology begin in Alzheimer's disease, in contrast to CTE?","In the entorhinal cortex, whereas CTE tau starts around vessels at the sulcal depths.",110,10],[509,"Which tau isoforms make up CTE filaments, and how does this compare with other tauopathies?","CTE has both 3R and 4R tau like Alzheimer's but with its own filament fold. Pick's disease is 3R only, while PSP and CBD are 4R only.",110,11],[509,"Can CTE be diagnosed in a living person?","No. CTE can only be confirmed at post mortem. In life the clinical syndrome is called traumatic encephalopathy syndrome.",110,12],[509,"What are the core features of traumatic encephalopathy syndrome under the 2021 NINDS criteria?","Substantial exposure to repeated head impacts plus cognitive change and/or neurobehavioural dysregulation, with a progressive course. Mood change and parkinsonism are supportive, not core.",110,13],[509,"What do MRI and amyloid PET usually show in suspected CTE?","MRI may be normal or show only mild atrophy, and amyloid PET is often negative. No scan confirms CTE.",110,14],[509,"Knife-blade frontal atrophy is seen at post mortem. Does this suggest CTE?","No. Knife-blade frontal and temporal atrophy is typical of Pick's disease, not CTE.",110,15],[510,"A man aged 60 played professional rugby for 15 years and is now increasingly forgetful and explosive. What is the best clinical diagnosis?","Traumatic encephalopathy syndrome, as he has repeated head impacts with progressive cognitive and behavioural change. Mild MRI atrophy does not argue against it.",110,16],[512,"A student aged 19 has disinhibition, labile mood, coarse tremor and raised liver enzymes. What would a slit lamp examination look for?","Kayser-Fleischer rings, golden-brown copper deposits at the edge of the cornea, which suggest Wilson's disease.",111,1],[512,"Which gene is affected in Wilson's disease, and how is it inherited?","ATP7B, a copper-pumping ATPase on chromosome 13. It is inherited in an autosomal recessive way.",111,2],[512,"What does the ATP7B protein normally do in the liver?","It loads copper onto caeruloplasmin and pumps spare copper into bile for excretion.",111,3],[512,"What serum and urine copper results are expected in Wilson's disease?","Low serum caeruloplasmin and raised 24-hour urinary copper.",111,4],[512,"Is low caeruloplasmin the cause of Wilson's disease?","No. It is a result: without ATP7B, copper cannot be loaded onto caeruloplasmin and the empty protein breaks down. The cause is ATP7B loss.",111,5],[512,"What neuropsychiatric features typically present in Wilson's disease, and at what age?","In teenagers or young adults: tremor, dysarthria, dystonia, disinhibition, mood change and psychosis.",111,6],[512,"How common are Kayser-Fleischer rings in Wilson's disease with brain involvement?","They are present in nearly all people whose Wilson's disease affects the brain.",111,7],[512,"What does the brain show at post mortem in Wilson's disease, and how does carbon monoxide damage differ?","The putamen is brick-red from copper and may have holes. Carbon monoxide gives pale damage mainly to the globus pallidus.",111,8],[512,"Which results point to haemochromatosis rather than Wilson's disease?","Raised serum ferritin with high transferrin saturation, showing iron overload rather than copper overload.",111,9],[513,"What are Alzheimer type II astrocytes and when are they seen?","Swollen astrocytes with large pale nuclei caused by high ammonia, seen in liver failure such as Wilson's disease. They are not a feature of Alzheimer's disease.",111,10],[513,"Which routine blood tests does NICE NG97 advise for suspected dementia?","FBC, ESR or CRP, urea and electrolytes, calcium, liver tests, HbA1c, thyroid function, and B12 and folate.",111,11],[513,"Should syphilis and HIV tests be routine in every dementia assessment under NICE NG97?","No. They are only advised when there are risk factors or suggestive clinical features.",111,12],[513,"What neurological signs suggest subacute combined degeneration of the cord from vitamin B12 deficiency?","Loss of joint position and vibration sense with extensor plantar responses, often alongside low mood and mental slowing.",111,13],[513,"A woman aged 70 on long-term metformin and omeprazole has normal haemoglobin. Can B12 deficiency still explain her cognitive decline?","Yes. Both drugs reduce B12 absorption, and Lindenbaum showed in 1988 that nerve damage can occur without anaemia.",111,14],[513,"What clinical features of hypothyroidism may accompany cognitive slowing, and what is its psychosis called?","Low mood, cold intolerance, hoarse voice and slow-relaxing ankle jerks. Asher called the psychosis myxoedematous madness.",111,15],[513,"Which enzyme is deficient in acute intermittent porphyria, and how is it inherited?","Porphobilinogen deaminase, inherited in an autosomal dominant way.",111,16],[513,"Name common triggers of an acute intermittent porphyria attack.","Alcohol, fasting, barbiturates and carbamazepine, all of which raise the demand for haem.",111,17],[513,"What are the features of MELAS and its commonest mutation?","Usually the maternally inherited mitochondrial m.3243A>G change, causing stroke-like episodes outside arterial territories, raised lactate, deafness, diabetes and cognitive decline.",111,18],[513,"Which inherited metabolic disorders can present in young adults with psychosis?","Niemann-Pick type C, with ataxia and poor downgaze, and metachromatic leukodystrophy from low arylsulfatase A, with frontal white matter damage.",111,19],[514,"A woman aged 27 has abdominal pain, weak legs and paranoia after heavy drinking, and her urine darkens on standing. What is the diagnosis?","Acute intermittent porphyria. Porphobilinogen in the urine turns into red-brown pigment on standing.",111,20],[516,"A man aged 61 has hand wasting, fasciculations, brisk reflexes and extensor plantars with normal sensation. What is the likely diagnosis?","Amyotrophic lateral sclerosis, because he has both upper and lower motor neuron signs in the same region with sensation preserved.",112,1],[516,"Which clinical signs come from upper motor neuron loss?","Brisk reflexes, increased tone and extensor plantar responses, from damage along the corticospinal tract.",112,2],[516,"Which clinical signs come from lower motor neuron loss?","Muscle wasting and fasciculation, from loss of anterior horn and brainstem motor neurons.",112,3],[516,"What is the commonest form of motor neuron disease?","Amyotrophic lateral sclerosis, which affects both upper and lower motor neurons.",112,4],[517,"Which functions are usually spared in ALS, and why?","Eye movements and bladder control, because the oculomotor nuclei and Onuf's nucleus are largely spared. Sensation is also kept.",112,5],[517,"What is the median survival in ALS and the usual cause of death?","About 2 to 4 years from onset, usually ending in respiratory failure.",112,6],[517,"How do primary lateral sclerosis and progressive muscular atrophy differ from ALS?","Primary lateral sclerosis is pure upper motor neuron disease and progressive muscular atrophy is pure lower motor neuron disease. ALS needs both.",112,7],[517,"How does myasthenia gravis differ clinically from ALS?","Myasthenia causes fatigable weakness without wasting, from antibodies against the acetylcholine receptor.",112,8],[517,"What is pseudobulbar affect in ALS?","Sudden uncontrolled laughing or crying out of keeping with mood, caused by loss of upper motor neuron control of the brainstem.",112,9],[517,"What are Bunina bodies, and what do they indicate?","Small round eosinophilic inclusions containing cystatin C in surviving motor neurons. They are specific to ALS.",112,10],[517,"What did Neumann discover about TDP-43 in ALS in 2006, and how common is it?","TDP-43 leaves the nucleus and clumps in the cytoplasm, forming skein-like inclusions. This is found in about 97% of ALS cases.",112,11],[517,"What proportion of ALS is familial?","About 10%. The rest is sporadic.",112,12],[517,"Which was the first ALS gene found, and what does it encode?","SOD1 on chromosome 21, found by Rosen in 1993. It encodes a copper-zinc enzyme that clears superoxide.",112,13],[517,"Do SOD1 mutations cause ALS through loss of function or gain of toxicity?","Gain of toxic function. Mice carrying mutant human SOD1 became ill despite normal mouse SOD1. SOD1 cases usually lack TDP-43 inclusions.",112,14],[517,"What is the commonest genetic cause of familial ALS and frontotemporal dementia?","A C9orf72 repeat expansion, identified in 2011. Carriers have the highest rates of FTD.",112,15],[517,"How common are cognitive or behavioural change and frontotemporal dementia in ALS?","About half show cognitive or behavioural change, and about 10 to 15% meet criteria for FTD.",112,16],[517,"A man aged 64 with ALS has apathy, rigid routines, loss of empathy and sweet craving but normal mood. What does this suggest?","Frontal lobe involvement on the ALS-FTD spectrum rather than depression. Cognitive screening such as the ECAS is advised.",112,17],[517,"Which screening tool is recommended for cognitive and behavioural change in all people with ALS?","The Edinburgh Cognitive and Behavioural ALS Screen (ECAS). Strong set criteria for the ALS-FTD spectrum in 2017.",112,18],[518,"Small round pink inclusions are found in a brain at post mortem. How are Negri bodies distinguished from Bunina bodies?","Negri bodies mark rabies and sit in hippocampal and Purkinje neurons, whereas Bunina bodies sit in surviving motor neurons in ALS.",112,19],[518,"Which inclusions are found in oligodendrocytes in multiple system atrophy, and why are they not seen in ALS?","Glial cytoplasmic inclusions of alpha-synuclein. They sit in oligodendrocytes, not in motor neurons.",112,20]];